/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220117-6","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"区民委員会","time":"午後 １時００分～午後 ４時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"聴取の順番を変更し、先に(5)「品川区オリンピック・パラリンピック特設サイト」および各種ＳＮＳによる情報発信の終了","agenda":"聴取の順番を変更し、先に(5)「品川区オリンピック・パラリンピック特設サイト」および各種ＳＮＳによる情報発信の終了","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"インスタグラムのアカウントを含めてですが、何か問題があるとかよほどのことがない限り、閉鎖という対応はあまり取らないと思うのです。そちらに関して、なぜ閉鎖をしなければいけなくなったのか、その経緯について改めて説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区全体の方針として、ツイッター、インスタグラムに関しては、区全体の公式のものがあります。特に問題があって閉鎖をするということではございません。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問","question":"基本的に経費がかからないものに関しては残っていると思いますし、意図的に閉鎖をする必要はないのではないかなと思うのです。認識を埋められればなと思うのですけれども、もう一度、閉鎖をする必要があるかどうか見解をお伺いしたいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"インスタグラムが、情報発信の役割を終えた後もそのままアカウントを持っておく必要があるのではというご質問かと思うのですが、そのまま持っている必要性もないと考えておりましたので、こちらは閉鎖することといたしました。","id":"exchange-002"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"中には一輪車だったり、地域スポーツクラブは、学校で行われているそういった個々の事業とどういう関わりがあるのかも伺いたいと思います。似た質問なのですけれども、４つのクラブに委託していると思うのですけれども、ご説明ほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"卓球教室の運営、あと地域でグラウンド・ゴルフ大会を催すとか、その地区の近場の方が来られるような大会という活動もやっていただいています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"そういう計画も持つべきだと私は思うのですが、その点、お伺いしたいと思います。７ページ目、スポーツの名の下に再開発事業を広げていくという考えがあるのかないのか、そこを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"今、コロナでなかなかできないのですが、障害者スポーツ指導者派遣事業というものも毎年予算を組んです。区としては、障害者水泳大会を長年やってありますので、今後もそれは取り組んでまいります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりどうしても現役世代がスポーツを楽しむとなると、施設の利用料金は無料だったり低廉だったり、そういう環境の整備は引き続き大切だと思います。現役を引退された方でも、定年退職後も誰もが気軽にスポーツに参加できるように、そうした環境整備を強く求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"去年の１２月４日の公式戦を見にいかせていただきまして、実際、どれぐらいいらっしゃったのかお伺いします。なるべくバランスよくいろいろな学校へ選手の方が行ってもらえるようにしていただきたいなと思っていまして、お伺いさせてください。","respondent":"中元スポーツ推進課長","answer":"バスケットボールは、今度の３月に初めてやる予定です。これから教育総合支援センターですとか、どこの学校みたいなお話も頂きながら、丁寧に進めていけたらなと考えているところです。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"伺いたい部分、荏原Ｂ地域スポーツクラブですと１８２団体、個別にどのような団体が所属されているのか。この１５４団体は、どういった団体、どういったジャンルのスポーツが自分のお住まいの地域で参加可能なサークルとして存在しているのか。","respondent":"中元スポーツ推進課長","answer":"その辺のところでサークルの情報というのは、なかなか地域スポーツクラブごとの一覧表のデジタル化というのは、今後の課題かと思っているところです。あくまで紙ベースの情報が主体となっていて、それを自分のエリアの区の施設に置いていらっしゃるような形になっています。","id":"exchange-007"},{"speaker":"くにば委員","kind":"意見","question":"１５４団体、紙ベースでその地域の各スポットで、こういった団体がありますという一覧を入手できるのかどうか。それぞれのスポーツクラブの中で紹介してほしいサークルを募って、例えばその２点について、ご見解を説明を求めました。","respondent":"中元スポーツ推進課長","answer":"私が異動してきたすぐのとき、４年ぐらい前に、スポーツ推進委員や地域スポーツクラブの紹介を一面とかでやりました。今後また地域スポーツクラブの方にもご意見をお伝えして、前向きに考えていきたいと思います。","id":"exchange-008"},{"speaker":"くにば委員","kind":"意見","question":"各地域スポーツクラブの皆様は、頑張ってスポーツの普及という部分に関しても努力されていることだと思いますので、ぜひとも区の努力という部分で、皆さんの情報を区民の方々にお伝えできる方法を考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"概要版ではなく全体版の部分のところも拝見させていただいた上での確認なのですけれども、令和元年度は５７.６％ということでよろしいのでしょうか。不定期実施層の２８.４％と非実施層の１０.１％、全体としてみたいなところで何か目標があれば、まず教えていただけたらと思います。","respondent":"中元スポーツ推進課長","answer":"成人の週１回以上のスポーツの実施率、国がたしか６５％で、東京都が７０％なのです。それで、スポーツを実施しない層につきましては、特に目標立てはしておりません。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"やはり不定期実施層であったり非実施層の方、その辺りのお考えについてありましたら、お聞かせいただきたいなと思っています。高校でやめてしまい、教育委員会とスポーツ推進課ではどういった連携を取っていらっしゃるのか、その辺りを説明を求めました。","respondent":"中元スポーツ推進課長","answer":"そこで出てきたのがこの地域スポーツクラブという考え方ということで、国のほうでも説明をされております。私どもで今取り組んでいるのが、大変好評でしたので、今後もやらせていただきたいと考えています。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"現在の区の考え方だったりが何かありましたらお聞かせいただきたいというのをもう一度確認させていただけたらと思います。こちら、区民の方へのＰＲですとか広報とか、地域に発信して盛り上げていくということはどのように進めていくのかというところも確認させてください。","respondent":"中元スポーツ推進課長","answer":"区内にある少年少女スポーツの団体の４種目、毎回コロナでなかなかできないのですが、今後もそれは引き続きチャレンジしていきたいと思っています。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"スポーツデビュープログラムは、すばらしい取組だなというふうにお聞きしていました。３０代、その辺りもまた今回の流れとは別のところでぜひ検討していっていただきたいなと考えていますので、こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"先ほど障害者施設で教えていらっしゃる方もいるとおっしゃっていましたが、また、そういうお立場的なところを一つお伺いしたいと思います。高齢ではない、そういう行き場、そういう方たちをターゲットにしたような取組をされているところがもしあれば教えてほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"スポーツ推進委員が経験とか知識を活かしてご対応してくださったりしている状態で、そのような形でサポートしている形になります。地域の中で様々いらっしゃいますので、あと、ご本人が了解してくださるのが一番大きなところかなと考えています。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"区民が体を動かしたいと思ったときに、そういう情報が得られやすい、またその情報発信の工夫をぜひ今後もお願いしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"スポーツ大使退任式について伺いたいのですけれども、予算は１１８万円余ということで、１１８万円の内訳を教えていただきたいです。これは例えばギャラが発生するのであるかとか、記念品に予算がかかるであるとか、内訳に関してお教えください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員おっしゃるとおり、まずギャラです。報償費と、業者の進行台本の作成、振り返りのＶＴＲ作成、それから当日スタッフの運営経費、花束等が含まれているところです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"確認","question":"その５施設の年間合計は約１１億円、おおよそ９,２００万円程度、今後赤字になる見込みだというふうに報道で聞いております。確認ですが、この赤字に関して負担が発生しないのかどうか、確認だけさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場の赤字のお話ですが、品川区にその負担はございません。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"東京都としても、赤字収支というところを改善していくために、可能な限り大井ホッケー競技場を活性化していかなければならないと。区にどの程度、施設利用に関して推進する何か施策をしてほしいだとか、そういった東京都からの連携であるとかアプローチというのはあるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場ですが、ホッケー協会を中心とした大きな大会が開かれたりですとか、もちろん区のほうにも、区で利用する場合にはぜひということでお話は頂いておりまして、優先的に利用させていただけるようにはなっております。","id":"exchange-018"},{"speaker":"くにば委員","kind":"意見","question":"八潮の大井ホッケー競技場ということで、可能な限り、せっかくの施設ですので、品川区としてもこの施設を有効利用して、今後、八潮地域の何か観光資源に寄与していってほしいと求めましたので、その点、ぜひともホッケー以外の競技でも活用してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問","question":"スポーツ大使の退任式について、この３人の方に大使を務めていただいて、今回、退任されるということなのですが、今後、何かスポーツというところで、東京２０２０大会のレガシーとして、この３人の方が活躍される場が区として何かあるのかというところだけ、１点お伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３人の方の今後ということなのですが、特に今から予算化してということはないのですけれども、区内在住であったり、品川区をホームとするチームにいる方ですので、ぜひまたそういう機会があったときにはお願いしたいと考えています。","id":"exchange-020"}]},{"id":"topic-04","title":"(1)令和３年度町会・自治会活動活性化促進調査の報告書","agenda":"(1)令和３年度町会・自治会活動活性化促進調査の報告書","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"順次伺っていきます。どのようなことを町会・自治会に協力依頼するのをやめたから、負担が減ったのか、具体的な取組であるとか内容についてお伺いしたいです。","respondent":"川島地域活動課長","answer":"そのほか、部長会という機会に、ポスターの掲出ですとかチラシの配布依頼につきましてもルールを徹底してもらうような形でお願いしております。今回のアンケート結果の負担軽減というお答えをしていただけることが多くなったというところにつながったと考えているところです。","id":"exchange-021"},{"speaker":"くにば委員","kind":"意見","question":"幾つか具体的な事例、例えば今、ざっくり言うと、チラシの配布であるとか、そういった手間を減らしたであるとか、その点のみ分かったのですけれども、何かこういったことをやめれば実際に減ったという、もう少し具体的な事例を幾つかご紹介いただければと思うのですがとの意見を述べました。","respondent":"川島地域活動課長","answer":"大きな負担になっている事例は、会議への出席です。それはちょっと難しいところがあるのだというところをお伝えさせていただいて、そういったことも少しずつ浸透してきているのかなと考えています。","id":"exchange-022"},{"speaker":"くにば委員","kind":"意見","question":"次の点です。４.町会・自治会の現状と課題というところの2)地域全体でメリットを感じられるようなというところの右側、具体的にこれは、説明を求めました。","respondent":"川島地域活動課長","answer":"いろいろなメニューを提供しまして使えるときに使っていただくという考え方と、その辺の反映をしていくというようなところも一つございました。町会長会議で私ども補助制度の説明をしておりまして、今回の調査結果も含めて、しっかり反映してやっていきたいと考えています。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"これは報告書の５ページですね、地域に無関係の不特定多数の人が閲覧可能であり、町会・自治会には不向きという意見もあった。なぜＳＮＳ、このツイッター、それについて何かお聞きになられている内容があればお知らせください。","respondent":"川島地域活動課長","answer":"使い方とかというのも多分いろいろなメリット・デメリットがあると思うので、その辺も加味しながら、こういったいろいろなツールを活用していければと考えています。","id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"続きまして、調査報告書の４.組織基盤に関するヒアリング結果、４ページ目になります。これの上から４点目、どのような施策が若い人との接点を作るという部分に寄与する解決策になるのか、そこについてのお考えを説明を求めました。","respondent":"川島地域活動課長","answer":"１つ例として挙げられるのが、役員を見つけてくるとかというところにつながるということですので、まずそういったところが一つあると思います。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"終わった後の飲み会に誘って、それで若い人たちの意見を聞くかみたいな、そういった部分を本当に今の若い人たちが求めているかどうか。もちろんこの町会の幹部の方々のお考えもあると思いますけれども、なかなか言いづらいかとは思うのですが、この辺についてお考えはいかがか尋ねました。","respondent":"川島地域活動課長","answer":"手法については、なかなかずばりという手法がない中ですので、いろいろ試行錯誤して町会の方たちも考えていらっしゃるのかなというところがあります。当然、町会・自治会活動の参考にしてくださいというような意味で、報告書のほうは説明させていただきたいと考えています。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"ありがとうございました。そこを１つでも多く、今の若い人たちはどういうことを求めているのか、情報共有もしていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"具体的に、この先、どういうふうにお考えになっているのか。取れているときもあるし、もう少し連携をしていただきたいというのがあるので、今後の展開だけ教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"防災課との連携は非常に重要なところで、現状ですと、例えば防災課職員を地域センターにぜひ配属してほしいといったような意見を聞く地域もあります。防災課とは何かあるごとに、その辺の地域への説明ですとか、それから事業があるときの打合せも含めて。","id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、課長からご答弁があったように、ぜひ積極的に防災課とも連携して、強固にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"８ページのところなのですけれども、地域センターの役割のところで、今、防災課の話が高橋伸明委員からもありましたが、職員の業務量が増加傾向にあるということなのですけれども、こちらは防災のお話だけではなくて具体的にどのようなことがあるのかというところを確認させていただけたらと思います。","respondent":"川島地域活動課長","answer":"そのお知らせですとか、それから窓口での取扱いも始まるというような、そういったニュアンスがあるということです。それから、そういったところも業務が増えてきているというような、そういったニュアンスで地域センターの職員が発言していたと認識しております。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"区全体でいろいろな新しい事業等があると、それに伴って業務量が増えているというところでよろしかったでしょうか。区民の方々、町会・自治会の皆さんも慣れていないので、様々整理しなければならないという状況にあるということでよろしかったか尋ねました。","respondent":"川島地域活動課長","answer":"業務が煩雑になるとかという話ではなくて、業務量が増加気味であるというのが職員の認識としてあったというようなことですので、こちらのほうも効率的な業務に努めながらしっかり遂行していると考えているところです。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"１２ページの木密地域のモデル事業、こちらはどういった内容になってくるのでしょうか。まだ検討中なのかもしれないのですが、イメージが分かれば説明を求めました。","respondent":"川島地域活動課長","answer":"こちらは例示という形で、例えばこういうことができるのではないかという、まだ発想の段階になります。ただ、防災課と地域とのつながりというのは非常に重要なところがありますので、その辺の連携は密にしていく必要があると私ども思っているところです。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"様々、区のほうで、ご意見としては区のほうから働きかけていただきたいなというようなご意見がアンケートではあるのかなと思うのです。はなかなか現実的に、先方もあるので難しい部分もあると思うのですが、その辺りの実感としてはどのように区として感じていらっしゃるか尋ねました。","respondent":"川島地域活動課長","answer":"今、連絡調整員制度を使わなくても、積極的に町会長・自治会長のほうに自ら出向いていって説明とかをしている事例が非常に多いという現実があります。手法は様々考えられるところですが、その辺を何かお手伝いできないかということを今考えております。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"管理組合ですとか理事会ですとか、そういったところの考え方を区として把握していただくというところを、ぜひやってほしいと求めました。どういうところがお互いにとってのｗｉｎ－ｗｉｎのポイントといいますか、防災だけではなくて、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"新妻副委員長","kind":"質問","question":"その３０町会・自治会は、どこが出ていないのかというのは当然把握されているということでよろしいでしょうか。なぜここの３０町会・自治会が出されなかったのか、理由を把握されているのかというところをお伺いしたいのですが。","respondent":"川島地域活動課長","answer":"回答率８５.１％ということで、八潮地区の回答率が４６.４％ということで、回答をお願いするというのは差し控えさせていただいて。","id":"exchange-035"},{"speaker":"新妻副委員長","kind":"意見","question":"自治会の、特に団地の自治会というのは、いわゆる平屋地域の町会とは少し考え方が違うと思いますし、確かに１年ごとに自治会長が変わっています。そういうところにもまた支援の目をぜひ向けていただいて、独特な地域でありますけれども、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西村委員","kind":"質問・要望","question":"私からも要望で、ぜひ要望させていただきたいのと、伺わせてください。すごくいい事例がありましたので、そのようなことが横展開していけばいいのかなと思いましたので、事例としてお伝えさせてください。","respondent":"川島地域活動課長","answer":"行政書士会に委託した事業がございまして、そちらのほうも積極的に使っていただけますように、ご案内をしっかりしていきたいと考えています。どんな媒体を使ってやるのかというのはありますが、その辺のご意見も参考にしたいと考えています。","id":"exchange-037"}]},{"id":"topic-05","title":"ワクチンパスポートアプリ","agenda":"ワクチンパスポートアプリ","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"やはり物すごく多岐にわたっていて、これを地域センターの担当の方で特にアプリに詳しい方とかでも、なかなか難しいのかなと思うのです。は、どういう体制を取ったらこのアプリに関する問合せに対応できているのか、その２点をまず説明を求めました。","respondent":"木村戸籍住民課長","answer":"実際に対面をしてご説明するという場面がどうしても必要だろうというところで、委託契約をしまして、本日から実際に要員がついてやっているです。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう１点、実際に１２月２０日にアプリが公開されて以降、紙の証明からアプリの発行のほうに利用者の方々が移っていったのか。例えば紙証明のほうはアプリが公開されてからぐんと減って、アプリに移っていったという、現在の比率であるとか状況をお伺いしたいです。","respondent":"木村戸籍住民課長","answer":"ざっくりではありますけれども、８割方が今、アプリとなります。委員おっしゃったように、アプリがスタートしてから、紙による発行はがくっと減っています。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"やはりデジタル化で寄与できるのかなと思いますので、区のほうでも証明書を発行したいという方には、どんどんアプリの利用を推奨してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-06","title":"デジタル社会の実現に向けた証明書発行等業務の新たな取り組み","agenda":"デジタル社会の実現に向けた証明書発行等業務の新たな取り組み","exchanges":[{"speaker":"新妻副委員長","kind":"質問","question":"ご質疑ございませんでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"くにば委員","kind":"意見","question":"これが例えば３日前、４日前になっても、この状況だととてもではないけれども開催の理解が得られないという状況で、ぎりぎりで判断をするのか。どうしても支出が避けられないものもあるか、まずその２点、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの実施の判断ですけれども、特に期限をいつまでにというところではございません。一部委託料等を支払っているところもありますので、まだ正確な数字は出ていない、やめる時期によってという形になろうかと考えています。","id":"exchange-042"},{"speaker":"くにば委員","kind":"確認","question":"どうしても厳しい判断をせざるを得ないときはやむを得ないがという方向性をおおむね確認できました。この使用料の内訳をお聞きしたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"きゅりあんの使用料につきましては、金曜日から設営をする形になりまして、また、駐車料金なども含めて６５万円ぐらいの予定になっております。","id":"exchange-043"},{"speaker":"くにば委員","kind":"意見","question":"それぞれ承知いたしました。これはもう３１回目のイベントということで、非常に内容もすばらしいものだと思いますので、開催できることを祈っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":47979,"voices":120}},{"id":"r04-20220117-7","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"（仮称）小山七丁目障害者グループホームの整備","agenda":"（仮称）小山七丁目障害者グループホームの整備","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"どのような経過でこの土地が取得されることになったのかを伺いたいのですけれども、そのようなものなのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただし、区の中でも検討させていただきまして、用地の東側には区立小山地域密着型多機能ホーム、小山倶楽部があります。ただし、土地の条件や様々な近隣の状況、地域の状況なども踏まえまして、その都度検討し、決定していくという方針です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、山口銀行のほうから区のほうにどうでしょうかということでお話があったと。そのような条件提示などはなかったのかということを伺います。","respondent":"松山障害者福祉課長","answer":"山口銀行からの申し出に対する条件というものですけれども、特に山口銀行からはございませんでした。この間検討をしてまいりまして、やはり障害者グループホームというものが必要であったことから、今回ご報告することに至ったというものです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"４１４m2ですので、何人ぐらいの定員になるのか。それで、幾らぐらいで取得をされたのか、金額も分かれば教えていただきたいのですが。","respondent":"松山障害者福祉課長","answer":"４か所いずれも精神障害者の方が対象ということで、既存の建物を借りて民間事業者が整備することができているというふうに認識しております。次に予算額なのですが、これは来年度予算で取得する予定ですので、まだこれからということになります。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、まだ先の話になると思うのですけれども、運営形態などはもう考えていらっしゃるのか。区立なのか、区立で指定管理なのかというところの検討はもうあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"運営形態についてのご質問にお答えいたします。設計以降は選定事業者にて実施予定ということで、その用地を民間事業者に貸付けを行いまして、運営していくという予定です。","id":"exchange-004"}]},{"id":"topic-02","title":"住民税非課税世帯等に対する臨時特別給付金","agenda":"住民税非課税世帯等に対する臨時特別給付金","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"単身世帯で年収が１００万円、各施設に置かれる、そうしたチラシ等はそのような内容にされるのですよね。それで、年収だったり、月額の収入だったりが、このような人だと分かるように説明や周知をされるのかということをちょっと確認したいと思います。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"ホームページと、あとチラシを、これからまた検討してまいります。そちらのほうでどのような形で載せられるかということで、ちょっと分かりやすくできればと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"相談ブース開設は第二庁舎の３階ということなのですが、あそこの暮らし・しごと応援センターの相談ブースを使うということになるのでしょうか。その相談を誰がやるのかということと、場所は具体的にどこなのかということを説明を求めました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"今予定していますのは、そちらの部屋を１つ確保しているのと、シナモロールの像があったところがあると思います。あそこに小さな受付ブースを設けさせていただきまして、そちらのほうで対応することを想定しております。","id":"exchange-006"},{"speaker":"せお委員","kind":"確認","question":"ちょっと確認なのですけれども、できていないとあるのですが、これは区がということでよろしいのですか。例えば生活福祉課が把握しているとか、そういったことではないのか、ちょっと説明を求めました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"は昨年１２月に支給された子ども世帯向けの臨時給付金、それと生活保護を受けている方については生活保護費の振込口座というようなことになっておりますので、その辺りの情報をお示しするという形になります。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"資料の裏面の周知方法の「暮らし・しごと応援センター、地域センター等」の、この「等」の内容ですけれども、ふれあい掲示板など、そのようなところも想定されている、予定されているかなという、そこの確認というか、お願いします。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"ご指摘いただきましたとおり、ふれあい掲示板のほか、区有施設に、例えば図書館等も含めて、これから調整という形になりますが、できる限り掲示するような方向で考えております。","id":"exchange-008"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"児童生徒としては６.５％というように推計をされたのですけれども、もう少し多い、約１０％になっていくのではないかと考えられますとあるのです。区民で、どれくらいの人数がいるのか、教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"恐らく医師の診断書に明記されない限りは手帳に反映されることもございませんので、私どものほうでは、正確な人数というものは分かっておりません。この発達障害者相談支援センターへいらっしゃる方も、正確な数としては、区としては計りかねます。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かに正確な数は、診断が出ても、そうした手帳だったり、支援につながっていなければ分からないと思うので、分かる範囲では、そうした手帳を持っていたり、支援につながっている方というところで区の把握している人数というのは、何人ぐらいなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"先ほど申しましたように、特に発達障害者だからということで統計を取っているものではございませんので、正確な人数は把握しかねます。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"周りがどう接するのかということをすごく分かりやすく書かれていて、そして対応が、支援がされているのだろうなと思うのです。私は何かもう少し、これだけ多くの方がいる中で把握するべきではないかなと、その辺は区としてはどのように考えていらっしゃいますかとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"できるだけご家族として包括的に支援をしていくというものですので、今回発達障害者相談支援センターのほうから相談実績が上がってきたものによれば。計画相談の４月からの累積ですが、１７６件ということになってあります。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはりそのようなところに早期に対応していくというところでは、子どものときからというところは大事なのではないかなと思うのです。特別支援教室や特別支援学級、このようなところから把握されている人数は、障害者福祉課としては把握されているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"連携は取ってはおりますが、なかなかその数として、ではどの面を切り取って統計数値として出していくのかということは検討していきたいと考えています。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"５倍、６倍という数で増えているなということが見てとれるのですけれども、教育委員会との連携というものも必要なのではないかと思うのです。ですので、そうした教育委員会との連携、その数の把握にしてもそうなのですけれども、そうしたところはあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"就学相談の説明会が毎年６月上旬に開催されますけれども、児童発達支援を利用している年長年齢のお子さんを持つ保護者と、開催通知を送っております。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"私はやはり発達障害に特化した係だったり、取り組み、計画というものが必要ではないかなと思うのです。次の質問ですけれども、発達障害者の成人期支援事業や就労継続支援Ｂ型に登録している人など、これは把握されている人数はあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"それから就労継続支援Ｂ型のほうです。それから成人期支援事業ですが、成人期支援事業も様々な活動を行っておりますので、合計で延べ９９６人ということになっております。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。今、その愛の手帳や精神障害者保健福祉手帳を取っている方の中での発達障害の方というものは、区としては把握されていますか尋ねました。","respondent":"松山障害者福祉課長","answer":"先ほども申し上げましたように、発達障害としての手帳ということではございませんので、その分、ちょっと統計が取りにくい状況にあります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"そのようなものも必要になってくると思ったので、その人数を把握されているというところがどうなのかと何度も伺ったのですけれども、分かりました。早期発見、早期支援というところでの区としての取り組みというものが、この間どのようなものがあるのか、伺います。","respondent":"松山障害者福祉課長","answer":"こちらの発達障害者支援施設の中に、その中で発達障害に関わる講座や、発達障害者とはという形でＰＲというものをしています。そういったものを目にしていただいて、実際は相談に行っていただくということが一番の近道だと考えております。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうした発達障害に関する普及啓発、それは何か、どのような取り組みをされているのでしょうか。そして相談先も書いてあるというような、そうした普及啓発は、区としてはどのようにされているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"オンラインでも行っておりますので、比較的参加しやすいのではないかと考えています。ペアレントトレーニングやサポーター養成のステップアップ講座というものを行っておりますので、区としては普及啓発というものに力を入れてあります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"これというのはどのようなところで、ホームページはあったとしても、どこか配られている場所というのはあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"品川区地域自立支援協議会の子ども支援部会で、事業者が集まって皆さんで作成した子ども発達支援ガイドブックなのですけれども、増刷する予定です。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"やはり区民全体に対しての発達障害というものに対して啓発をするということが、区としてもすごく大事な役割なのではないかなと。平成２８年に改正された発達障害者支援法の中にも書かれているのではないかと思うのですけれども、まず、その点についてはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"発達障害の理解を進めるための広報です。４月から相談支援センターという特化したものをつくり、そこを発達障害者相談支援センターを核として、啓発を進めてまいりたいと考えております。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点では、品川区の取り組みはどうされているのかということについても伺いたいと思います。去年の４月に開設された発達障害者相談支援センターは、体制でされているのか、その点についても教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"関係機関の中にも、ハローワークや東京都の発達障害者支援センター、現在就労支援部会で発達障害者に対する理解というものを進めているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ジョブコーチがついて、そのような就労をされている方というのがどれくらいいるのかも教えてほしいと求めました。手帳がないと受けられないサービスと、手帳がなくても受けられるサービスというのは、どのようなものがあるのかも教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"企業、あるいはハローワークのほうに付いて行って、就職した後も実際に継続できるように支援をするという形になっております。ただし、手帳がないと、やはり企業のほうでは障害者枠としてはカウントはされないということになっております。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"ラーメン屋でもそれはできたのですけれども、その大学の就学というのか、そのようなものはメニューとして結構あるものなのでしょうか。それだけ説明を求めました。","respondent":"松山障害者福祉課長","answer":"就労移行支援、その後の就労定着支援といったメニューは整っているのですが、支援メニューがあるかと言われますと。個別に支援しているという状況ですけれども、体制的にとか、メニュー的にというものは整っていない状況です。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その障害にもよるのだけれども、難聴の方だとか、いろいろな大学の支援というものがあるではないですか。ぜひそのようなものはメニュー化されたほうがいいかなと思っているので、ぜひそのようなものも模索していただきたい、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"せお委員","kind":"意見","question":"１点。子どもの相談も受けて、そういったところの今後の検討などはあるのか、説明を求めました。","respondent":"松山障害者福祉課長","answer":"計画相談も含めたものになるかと思いますが、確かに児童から大人までと一貫性を持ったというのは、非常に重要なことかと考えています。今後どのように発達障害に関わるものを進めていくかについては協議してまいります。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"相談だったり、品川児童学園に通ったりと、そのような流れがあったと思うのです。ぷらーすと、あとそういった相談支援事業所や品川児童学園などとの連携というものは、そこは今現在どのようになっているか尋ねました。","respondent":"松山障害者福祉課長","answer":"２月に開催予定をしておりまして、その連絡会の中で情報共有を図って横のつながりをつくっていくというところが、一番目指しています。新たに発達障害者相談支援センターができましたので、連携というものは、今後力を入れてやっていきたいと考えております。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"本当にセンター中心にというか、時系列で子どもの頃から大人のというところも、そういったところもつながっていけばいいなと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですが、本当に住民の皆さんの強い求めに応じてスタッフが配置をされるということになって、確かに今は大きな混乱は起きていないということです。ですので、常駐者を置くことは法を超える強い規制ではないのではないかと思うのですけれども、区の考えをお伺いいたします。","respondent":"鈴木生活衛生課長","answer":"多分国のほうの回答、説明は、法で認められた規制を超えるものをかける場合には条件があります。それについては、今の品川区の現状の中では、その要件を満たすものとは考えにくいので、区としてはその方法は取らないというものが前回の説明です。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"常駐者を置くこともできるし、それに代わるＩＣＴの対応もできるということですので、常駐者を置くということも判断できると。それは、でも事業者の判断だということでいいのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"ただし、どうしても常駐の従業員を配置するとなると、そのための人件費や、それから場所の確保、部屋ですね。そのようないろいろな準備等を考えると、事業者としては避けたいと考える事業者も多いというふうに聞いております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"意見","question":"安心・安全なホテル運営ができる制度というものは当然していくべきだし、置いてもいいし、私は法の規定を超えていないと思うのです。そして宿泊者の安全を守るためにお願いしていくべきではないかなと思いますので、私たちは、この陳情には引き続き賛成の立場ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはそれで支持をしますし、我々としては、それは結論を出していただきたい。それで、不採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"意見","question":"ご説明と質疑を聞いて十分理解をいたしました。公園の使用についてどうこうという、これからも築いていただくということで、しっかりお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"せお委員","kind":"質問","question":"ホテル側も一定の対応は取っていただいたり、区としても対応していただいたりというところで、不採択の結論を出したいと思います。私も、今は苦情はないということでしたけれども、何かもし、これから苦情がありましたら、早急に対応していただくことはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり少なくとも常駐者を配置していく、そこで１つの安心が確保されるのであれば、ぜひそうした立場で対応していただきたいなと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"担当の方が指導をしたり、チェックをしたりしているというところで、そこの法令と条例との関係をカバーしていただいていると思います。今後もぜひ継続的に、指導という言葉が適切かはあれですが、指導をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今第６波へ向けた体制についてということで(6)で説明いただいたのですけれども、オンライン診療が１０月までの利用件数等について書かれているのですけれども、どれぐらいされているのかというものがあれば伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"濃厚接触者への対応の変更ですが、感染者との最終接触日から６日目以降、陰性であれば勤務するという方針へ変更となっています。夜１１時４７分の通知で、本日中に私どもから至急お知らせする予定なのですが、先生方はまだ１４日だという認識でご説明したりというところで。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、この利用件数というものは、オンライン診療と往診調整は、今のところで分かるものはないということですか。分かれば伺いたいということと、その体制というものは、第５波を教訓にどういった体制を取られているのかということを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"職員の対応ですが、あとは先週の対応ですが、今のところは来ている状況になります。２１８人だったのですが、５日で１,０００人などになっていくわけなので、今日中にその辺を区内の医療機関の先生には周知をする予定にしております。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり第５波の経験があるからこそ、ぜひ職員の皆さんと、そして患者への健康等が超過密にならない状況をつくっていただけたらと思います。保育園や学校などの感染状況というものはどうなっているのか、クラスターは出ていないのか、その辺が分かればお聞きしたいのですが。","respondent":"鷹箸保健予防課長","answer":"その方の発症前２日のときの勤務状況を確認して、施設の中での濃厚接触者がいればその方々は検査をするという、通常どおりの対応をしております。幸い高齢者施設では、今クラスターが発生したというような認識はございません。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１月９日で１４９人ということで一気に上がっているのですが、もうこれから１週間経っていますので、ひとつ教えてほしいと求めました。６日目で濃厚接触者でＰＣＲ検査の結果がマイナスだったらばというような、品川区の場合は、その点についても教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"あの方針の変更で６日目以降抗原検査をして陰性という確認で仕事ができるという、ほぼ医療機関だというふうに考えていただいたらいいかと思います。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"障害者施設、今もやっていないのかもしれないのですけれども、どのような状況になっているのかも教えていただけたらと思います。そのすみ分けというものは、かかりつけ医に健康観察をお願いするということになるのか、ちょっと具体的なところで教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"高齢者施設や障害者施設の従業員の方々で、都の枠組みなどを使われて定期的に検査をされている施設は多いということを把握しております。我々のほうで、それ以降は保健所のほうは対応しないという、そのようなすみ分けになっています。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は東京都の仕組みとして、そのようなものも、東京都としてそこまで拡大するということもぜひ求めていただきたいとも思っているのですが。各部から４名ずつということなのですけれども、合わせて１日何人ぐらいという体制になっているのか、その点についても伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"それから残業についてですが、この体制でその対応はしているところですけれども、現状ではまだその日のうちに帰れている対応でやっています。正確な人数は、動きがあるので、ちょっと今お話はできないです。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなものが必要なのではないかと思うのですけれども、その考え方についてはいかがでしょうか。パルスオキシメーターや食料の配布というものは今までと同じようにされているのか、その点についての確認もさせてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"都が実施している無料の検査ですけれども、こちらについては確かに第１弾で報告というか、品川区の場合は１か所だけになると思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それをぜひ東京都にも求めてほしいと求めましたし、東京都がやらないところを区も積極的にやるような方向もご検討いただけたらと思っています。ぜひＰＣＲ検査ももっと積極的にできて、そのようなところで、ぜひＰＣＲ検査も拡充していただくようお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-05","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"そのようなものというのはどうなるのですか。高齢者ではない、職域や大規模接種でやった人に、多分これは日にちでいくのだろうから。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"６か月間隔の予約枠、７か月間隔の予約枠というものが、皆様に分かる状態で画面に出てきます。もし間隔が空いていない方がそこに入っても、予約が取れないような仕様になっていますので、そこに関しては大丈夫かとは思います。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問","question":"受け入れられないということですね。それから、先ほど１月中は金・土、金・土で１万枠と言ったのだけれども、２月も同じと考えていいのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"そこでモデルナの入り具合を考えて、１月２０日以降に２月の予約枠を設定しようというふうに現時点では考えております。あまりにも１万枠がすぐ埋まるような、それに追加して、曜日を増やして設定をしていくということで考えたいと思っています。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認なのですけれども、２回目のときのこのような課題がこのように変えられたというか、そのようなところが分かる範囲でお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１つ目のご質問の予約開始日は、4)以降は、こちらはもうなくなるものというふうにご理解をいただければと思います。それも、新しいシステムでは本当に１時間に数万件処理ができるというものですので、その辺りも解消できるものというふうに考えております。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"確認","question":"システムのほうですけれども、キャンセルするときに１回取り消してということで、非常に手間というか、消してしまったら次にまた入れなくなってしまったりなどということがあったりしたので、すみません、そこのところを確認したいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その方の予約を保持したまま、キャンセル枠の空き状況を見ることができます。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3618#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":44562,"voices":143}},{"id":"r04-20220117-8","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"建設委員会","time":"午後 １時００分～午後 ４時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"令和３年陳情第６０号、再開発するなら障害者支援施設の整備を事業者に要請する陳情","agenda":"令和３年陳情第６０号、再開発するなら障害者支援施設の整備を事業者に要請する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情については、これまでの再開発の事業の中で、こうした障害者施設などの公共施設の整備を求めたことはあるのかどうか伺いたいと思います。地域コミュニティ施設ですとか、高齢者福祉施設とか、そうしたものを求めたことがあるのかどうかというところで伺いたいと思います。","respondent":"多並都市開発課長","answer":"商業であったり、幅広く各部署にこの内容を説明して、要請事項ということで調整して伝えるということになっております。品川区においても、このような形で今後も進めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、この再開発、今回、再開発等促進区と言われておりますけれども、こうしたときは必ず求めるというような形にされているのかどうか。もし条件があるとすれば、どういうときに求めるのか伺います。","respondent":"多並都市開発課長","answer":"各事業を行う際には、これを必ず行っているということですので、それをやってきているという説明をさせていただきました。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"具体例などがあったらお答えいただけたらと思います。どうやって９００％、１０００％というような緩和をしているのか、仕組み上のことを伺います。","respondent":"多並都市開発課長","answer":"容積の緩和につきましては、東京都再開発等促進区を定める地区計画の運用基準を先ほどご説明させていただきました原則的な考え方ということで。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そこまでどうして高くなるのかという思いがあって、あと、道路や広場だけでよいのかなという思いもあります。区としては、開発をする際に、障害者施設などの公共施設を増やす機会とは捉えていないということなのか伺います。","respondent":"多並都市開発課長","answer":"冒頭ご説明の中で、なかなか専門的な内容なので、公共施設と公共公益施設は違うと先ほどご説明させていただきました。先ほども説明しましたけれども、様々ないろいろな施設がありますので、これについて１個１個協議していくと。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"なぜ出てくるのだろうと思ったときに、やっぱりどういう仕組みをもって再開発、やっぱり知らせ足りないのではないかというふうに感じたのです。その辺はどういう、中心は、どういう形で告知する形になるのか尋ねました。","respondent":"多並都市開発課長","answer":"市街地再開事業を検討される準備組合の皆様は、もちろん民間組織で検討していただいています。より連携しながら、まちづくりが皆さんで進められるように、それはやっていきたいと思うところです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"どこの段階でどういう人を巻き込むかというのはいろいろあろうかと思うのですけれども、でも、何となく唐突感が地域の中にあるのかなと。これに限らずです、最近すごく私は感じているのですが、その辺は改善できるものなのか尋ねました。","respondent":"多並都市開発課長","answer":"地域主体で検討していただいているまちづくりは、皆さんが知っていただきながら進められるようなことは、今後も各現場に合った形で進めていきたいと思うところです。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問","question":"地域のそれぞれの事情がある中で、一律で障害者施設の要請をするというのはするべきではないかなと思って、不採択でお願いします。それぞれの目線で、主体は民間ではありますけれども、引き続き寄り添った中でのアドバイスはしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"特に障害者施設に光を当てて、これをつくっていくべきだというようなことは、その願意に沿うことはできないということであります。総合的に判断していただくということがやはり必要だと思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"それも１つの課題だとは思いますけれども、運用はされているという、しっかりとした体制は整っていると思います。２番目の、あるいは開発事業者の皆さんが話し合って決めるべきものであって、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択です。障害者施設を増やしてほしいという思いは分かりますので、早く増やしていくべきだと考えますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"西本委員","kind":"意見","question":"それから情報提供もしっかりした中での進め方をしているということで、非常に私も安心しましたし、それをこれからもお願いしたいと考えています。そこはやっていかなければいけない部分もありますので、これからもよろしくお願いして、そういう結果にしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-02","title":"会議の運営上、予定表の順番を入替えまして、(5)環境表彰式・環境講演会","agenda":"会議の運営上、予定表の順番を入替えまして、(5)環境表彰式・環境講演会","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この表彰された方なのですけれども、これは何か冊子等で広報というか、報告書みたいなものは作るのですか。この後、表彰された方々をまとめたものとか。","respondent":"河内環境課長","answer":"ホームページなどでも表彰の状況を報告するとともに、副賞、またトロフィーなども併せまして、その顕彰をたたえまして、地域の活動がまた継続的になりますように工夫をしていくというようなところで行うものです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"何か冊子とかチラシとか、そういうものは、ご紹介の何かしらは何もないのですか。ホームページで紹介だけなのか、もうちょっと広げてもいいのではないかと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"冊子等は特に作っている状況ではございません。検討事項といたしまして、もうすぐ２５周年、そういった地域の総括ということも含めて検討してまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"１つだけ。副賞も含めて、こういうものをやっているなどというのは、環境館の中に何かそういうチャンスがあったらいいのではないかと思うのですけれどもとの意見を述べました。","respondent":"河内環境課長","answer":"ペーパーにつきましては、今後の検討事項といたしまして、そういった活動をしっかりと発信していきたいというふうに考えているところです。今後の臨時展示といいますか、イベントごとの展示の中で、またそちらのほうを対応していきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"やっぱり認知度をもっと上げていかないと、それに取り組むという意欲が出てこないと思うのです。環境に対して取り組んでいるというメッセージとして非常にいい機会だと思うので、ぜひ考えてほしいと求めましたが、いかがか尋ねました。","respondent":"河内環境課長","answer":"醸成ですか、さらに上積みとして地球温暖化対策だとか、そういったものをやっていきたいというふうに考えています。前向きに検討していきたいと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"コミュニティバスの試行運行開始","agenda":"コミュニティバスの試行運行開始","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１か所、乗り継ぎの需要なども生まれてくるのではないかというふうに思うのですが、そうした検討などはされたのか伺いたいと思います。この中でどういった検討、話合いなどをやっていこうというお考えなのか、より便利なものにしていくという位置づけなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどもご説明して、図書館の辺りに１か所あるというところが、まずは進めていきたいです。利用実績向上のために、何か地元の商店街と連携してやれるようなことがないか、地域とともにしっかり継続して行っていきたいという意味合いです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者連絡会のところは、今回の大井ルートを実施して、西大井の循環の区間、ここについてもいろいろ住民の意見を聞いてやっていくということですね。区も強く認識しているということでしたので、ここはやはり坂なども多いので、ぜひ実施していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"南大井方面、桜新道のほうに行く道は、これは当初の地域の方々の要望とのずれはないのかということ。地域の方々のご意見も町会とかで聞いておられると思うのですけれども、そこら辺のご意見はどうだったのかというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したとおりなのですが、１つあったのが、結果としてこういうルートを選定しています。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"恐らくこちらのほうが地域の方々の要望は強いのだろうと思いますが、その辺はいかがでしょうか。その目途といいますか、ほかの要因として決める要素がまだあるのかどうかとか、その辺をお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"なかなか運行開始までには、これは東急バスと一緒に課題を認識しておりますので、そこは今後継続してしていきたいです。そうしたところは協議の中でしっかり説明をしているのですが、そうしたところは、今後しっかり見込みとしては考えていかなければいけないかなです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の質疑のところで、ちょっと私も伺いたいのですけれども、西大井循環ルートで西大井本通りと、それから通学路となっているのか、この４ページの。この２つが引き続き対策を検討ということで、それ以外も含めて、協議の余地がどの程度なのかというのをもう少し詳しくお伺いしたいのが１つ。","respondent":"鈴木都市計画課長","answer":"やはり先ほどご説明した運行に当たっての基本的な考え方といいますか、ただ、この循環区間にオーケーが出るというのはなかなか難しいと。ソフト対策と相まって効果的に説明ができるのかというところは、ただ、これから来年度以降になろうかと思います。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"かなり詰めた協議をされているというところを確認させていただきました。できる限りの努力をしていただいて、大井ルートの開通を目指していただきたいというふうに強く要望いたしまして、お願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"芹澤委員","kind":"質問","question":"２点お伺いしたいのですが、この収支率５０％以上を何とかキープしないと、ほかの２ルートをやることで収支率が上がるというようなことにはならないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"会議のほうでは整理をさせていただいているところですので、区内の全体として収支率を５０％で考えるというところは、考え方としてはあると思います。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"そこのところをもうちょっと教えていただきたいのと、往路１台、復路１台が動いているということでいいのか。燃料は、ガソリン、軽油、その辺を説明を求めました。","respondent":"鈴木都市計画課長","answer":"３台ということになりますと、１台が予備になりますので、まずは開始の段階では３０分間隔というところでスタートせざるを得ないという状況です。来年の８月以降、バスが整いました後、基本的には、４台、３台で回して２０分間隔で運行を進めるという予定です。","id":"exchange-023"}]},{"id":"topic-04","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ご説明ありがとうございました。今回、第１回目の改定委員会が行われたということで、質疑応答など、どういった意見が出されていたのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１０年前と比較して、どのような落とし込みとなるのか、今分かる範囲で教えていただきたい。公募区民、そうした地域のまちづくりの具体的な例示も計画の中で紹介していただけないかと、そういったいろいろなご意見をいただいているところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料４のアンケートのところでも、使いやすいというような形で検討を進めていっていただきたいというふうに思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"２地区、公共あるいは私、民間事業者についても一緒になってやっているところです。継続して歩きやすい、改定の中でも重要な位置づけをしていきたいというふうに考えておりますので、しっかり計画の中で位置づけていきたいです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした下で、超高層再開発ですとか、大型開発を位置づけていくということはやめるべきだと考えておりますけれども、いかがでしょうか。まちづくりでＣＯ２、ＣＯ２排出をなくしていくというところで重要だと私も思いますけれども、ここのところも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"回答としては非常に多いというところで、声として１０％あったですので、今後もしっかり計画にも位置づけて実施していきたいです。高効率な建物更新、まちづくりを進めていくというところも、しっかり当計画で位置づけていきたいです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"多様な機能の集積が求められているというお話でしたので、やはりそうした求められる機能の集積というのが、こうした個店が並んでくるというのが。さらに改善していくためにも、そういった位置づけをしていくということが必要ではないかと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"例えばですが、そうしたところで、地域からの声をいかに広げてまちづくりにつなげていただくかというところを支援させていただいているところです。区としてもアドバイス、支援できるところはさせていただきながら… 区としましては、現状の区営住宅を維持しながら、既存の民間賃貸住宅や空き家等を有効に活用して住環境を整備していきたいと考えております。区営住宅を増やすことは、現在、考えてございません。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすることで住環境の改善にもつながっていくと思いますので、ぜひこのまちづくりマスタープランでも検討していただきたいというふうに思います。そうしたところがないように、参加していけるような運営を進めていくように、区としても支援をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"この調査、いろいろかけられているのですが、これ多分、委託ですか、それとも区の職員がされたのですか。その委託先と、それからコストを聞きたいと思います。","respondent":"鈴木都市計画課長","answer":"今年度から検討を開始しておりますが、委託の受注者はパシフィックコンサルタンツというところで、受注金額は１,３４０万円余という契約金額になります。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"現状把握の中で、社会情勢というところが幾つかありましたけれども、それを踏まえて、品川区の特徴とは何でしょうか。なので、そこら辺をどう考えられていますか。","respondent":"鈴木都市計画課長","answer":"数回検討会を開いて進めていくわけですが、先ほどの社会情勢の変化を踏まえた変更ということになるのですが、ご説明があった。今回、改定の中では、どうしたところをその中でも重点的に書いていくのかというところは、しっかり検討していきたいと考えています。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"イメージは何ですかと言われたら、９割以上の方が住み続けたいというのは、それでいいのかという話なのです。今までと同じような委員たち、そして地域の特性が見えるようなまちづくりという位置づけでやっていってほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"上位計画全体をカバーする計画で、その中でもやはりご指摘のように、地域の声をしっかりお聞きして計画を策定していくことは大事なところです。２年間という短期間での計画改定ということもあって、地区別で検討していくに当たって、これからしっかり考えていきたいと思います。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"１つの方法として、手法としてやるとしたらワークショップです。これからどういうまちにしていったらいいでしょうかみたいなのは、ぜひスタート時点で、希望を込めて意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"５つの次世代に求められる社会というものが挙げられておりまして、どういうような考え方になっているのかというのを１つお知らせいただきたいのと。ライフスタイルが変わるというところをどうやって位置づけていくのか、ちょっとうまく言えないのですけれども、教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"必然的に変わってきたというところで、今後こうしたところを受けて、どう検討の中でうたっていくかというところを考えていかなければいけないと。まちづくりの考え方、なかなか答弁になっていないかもしれませんが、そうしたところです。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうコミュニティに自分の居場所を求めて、電気は動いている、このような人が結構増えてくるのではないかと思います。この辺の観点については、どのようにお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"どういう考えをお持ちで生活をしていくかというところまで、これから考えていきたいと思いますが、しっかり考えていきたいというふうに考えております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"分科会で分けて話合いを審議していくということも、さらに深めていくことになるのではないかなというふうに思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この検討会に分科会という形で、今現在の予定としては考えてございませんが、検討していかなければいけないことにはなるかと思います。今現在では考えておりません。","id":"exchange-035"}]},{"id":"topic-05","title":"西五反田七丁目地区に関する都市計画案","agenda":"西五反田七丁目地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"計画建物の高さの２倍の範囲のところにチラシをポスティングする、ぜひ広く周知をしていただきたいというふうに思いますけれども、いかがでしょうか。今回、その中で６,３５０m2という大きな面積になっているのですけれども、こういった形になった理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"１２月２０日に行いました都市計画原案の説明会ですが、質疑は当日ありませんでした。先ほどご説明しました周辺に歩道状空地、これがまず規定でありまして、これが２ｍから５ｍ設置されています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"該当して、１０分の５、その５０％ということでよいのかどうかというところも確認させていただけたらと思います。２月２５日の説明会は、参加する方が少なくなるという傾向がありますので、事業者説明会のときには１５５名参加されているわけですから。","respondent":"多並都市開発課長","answer":"まず、右側の備考欄にあります建築基準法の第５３条第６項ということで、これはまたこれから施設計画を立てる際に具体的に出てくると。そういう細かな設備を、これは、これから具体的に定めていくということでここに書いているものということでご理解いただければと思います。","id":"exchange-037"},{"speaker":"芹澤委員","kind":"質問","question":"すみません、説明を聞き逃していたら恐縮なのですが、Ａ３資料の裏面のＡ－１地区等、道路に網かけがかかっている部分が、オレンジのところとピンクがあると思うのですけれども、まず、これのご説明をいただいてもいいか尋ねました。","respondent":"多並都市開発課長","answer":"今回でいうと、この高速道路があるほうの地区については、道路の中心線から地区として加えていると。右側の国道１号線側のほうについても同じような考え方でしているということで、この地区としての対象範囲としていく、そういう考えであります。","id":"exchange-038"},{"speaker":"芹澤委員","kind":"質問","question":"Ａ－１地区の今「２.０ｍ」と書いてあるところは、ここに建物が今あるのかと思っていたのですが、ここも含めて道路ということなのですか。紫色のところが道路の中心線になっているということなのか尋ねました。","respondent":"多並都市開発課長","answer":"Ａ－１地区とＡ－２地区に分けている理由は、この道路の脇から用途地域の今の容積率が違うので、Ａ－１とＡ－２で違うと。プラス３００％という緩和を図る、基の容積率が違うので、そういう分け方をさせていただいているという考え方であります。","id":"exchange-039"},{"speaker":"芹澤委員","kind":"質問","question":"両サイドの横断歩道まで少し遠いものですから、今後の将来性として、歩道橋と一体として何か開発をするという可能性はないのですか。例えば２階からつながるであったりとか、もしくは建て替えてエレベーターをつけるなりという可能性はあるのか尋ねました。","respondent":"多並都市開発課長","answer":"かなり広幅員な道路といいますか、２つの道路が交わっているところがありますので、そういう位置になります。国道事務所ともよく連携を図りながら、この中でいろいろ連携できないかというのは、今のところはそういう考えであります。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"ＴＯＣの建て替えが遅れているのは、この都市計画の申請を待っていたということなのでしょうか。そういう関係で遅れたのか尋ねました。","respondent":"多並都市開発課長","answer":"近年になって、それがまた建て替え計画の状況が整ってきたということで、区のほうに具体的な協議が最終的に来て今日に至っている。あくまでも民間計画が主体となりますので、民間計画、なんと言いますか……に至って、現在に至っているという認識です。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"そうした場合に、この地区計画との関係はどうなるのですか。なので、その辺はどういう絡みがあって、そこの時間的な経過も含めて教えていただきたいのですが。","respondent":"多並都市開発課長","answer":"地区計画につきましても、今回は、再開発等促進区を定める地区計画ではありませんので、一般的な地区計画です。その企画提案を受けて、今回まで都市計画の提案を案としてまとめていこうと、そういう段階であります。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"こういう形になると、建蔽率にしても何にしても優遇策がとれるわけではないですか。そうなってくると、ある一定の条件がないと、こういう手法は使えませんよということなのか、どこまでの範囲で使えるのか尋ねました。","respondent":"多並都市開発課長","answer":"まず、この高度利用地区というのは活用できないと、そういうところです。まちづくりとして整備していくとまとめておりますので、そういう考え方の、事業の内容です。","id":"exchange-043"},{"speaker":"西本委員","kind":"確認","question":"もう１つ、ちょっと入っているかなと思ったのですけれども入っていないので、あそこまでは延ばせなかったのかなとか思ったのです。どういう状況になっているか分からないのですが、あまり風紀的にもよくないので、そういう話はないのですねという確認だけです。","respondent":"多並都市開発課長","answer":"具体的な内容につきましては、ＴＯＣの敷地を母体としながらも、周辺で緑地を整備するための整備とする今回の範囲が示されているところです。地域の方と一緒に、より具体的な計画については検討していきたいと思うところです。","id":"exchange-044"}]},{"id":"topic-06","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"やはり品川区内でも、区営住宅を増設をしていくべきだというふうに思いますが、増設をしないというふうに考えているその理由を伺います。やはり東京都や国などに用地の取得を支援していただくというようなところで求めていくということも必要だと思いますけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"その考えに変更はございません。区営住宅を増やすことは現在考えてございません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々な公営住宅の改善点などを求めていきたいと思うのですけれども、区営住宅においても、いかがでしょうか。入居対象に同性カップルも含めていくようにしていただきたいというふうに思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"ご親族の方のほうからご説明いただくというような、そのような意味合いもありますので、連帯保証人は非常に大切だと考えております。その取扱いについては検討していくという文言もありますので、他区の状況、東京都の状況等を注視してまいりたいと考えております。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"東京都も連帯保証人としてではなくて、区としてもそういった形にしていけばいいのではないかというふうに思うのですが、いかがでしょうか。希望に沿って、ぜひ区の負担で設置をしていっていただきたいというふうに思いますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"支払いが遅れることを未然に防いでいるという側面もありますので、現状としては、連帯保証人を継続していく考えです。原状回復等の際に区の負担で実施してまいりますので、自費で設置して継続している入居者の方の故障時の修繕、区の負担では行っておりません。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"行わないということですけれども、様々改善を求めましたので、ぜひ改善をしていっていただきたいというふうに思います。若者や子育て世帯への家賃助成、住宅困窮されている方への家賃助成を実施していくべきだというふうに思うのですけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"家賃助成というご質問ですが、区としては、今現在はそういうことは考えておりません。他区からも品川区に住んでみたい、そういうふうに思っていただけるようなまちづくりを住宅を通じてしていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう１点、さらにこの助成率を引き上げていくということが必要なのではないかなというふうに思うのですが、いかがでしょうか。１回利用すると、再度利用できるようにしていただきたいというふうに思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"そのためには、１回という限定も適正な１つの判断材料だと考えています。高齢化による手すりの設置とか、１世帯の方が複数回申し込んでいただくということについては、今後検討してまいります。 失礼しました。補助率は、今現在、申込み件数が増加傾向ですので、現状の制度を維持していくというふうに考えてあります。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"教えてほしいのですが、３番の居住支援協議会ということなのですが、この居住支援という具体的な策が出てきたという認識でよろしいのでしょうか。そこをお聞きしたいのですが、関係性が知りたい。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおりでございまして、協議会の中から出たご意見を事業化したものがこちらです。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"いろいろあっ旋をするということをやっているのですけれども、そこで家賃を下げるとかという交渉もしておられるのでしょうか。なので、オーナーとかも含めて、家賃、例えば、従来よりも少し低くしてくださいとかという交渉はされないのか尋ねました。","respondent":"竹田住宅課長","answer":"家賃を下げるという交渉については、区は行っておりません。協力店５１店舗、住宅確保要配慮者に対する支援をしていきたいというふうなお考えをお持ちの方々ですので、そういった不動産店は。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"そういった場合に、空き家がいっぱいあるのだから、空き家対策の１つとして、１軒でも貸したほうが、オーナーにしてみればいいわけではないですか。そういう仕組みをつくると、お互いＷｉｎ－Ｗｉｎになるのではないのかと思うのですが、その辺の検討とかはしていないのか尋ねました。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおり、居住支援協議会のご意見をお聞きしながら、次は区として何ができるのかということを検討していきたいと考えています。家賃の問題も含めて検討していきたいと考えております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"どう追っても分からないといった場合に、そこに放置されてしまうわけではないですか。どうしてもずっとそのままの状況になってしまった場合に、品川区として何か対策をとれる、法的な何か保障されたものはあるのか尋ねました。","respondent":"竹田住宅課長","answer":"そういう方々にも貸していこう、あるいは不動産店については、そうなるように私どももご説明していきたいと考えております。それから、マンションの件ですが、国のほうで法改正がありまして、認定制度が今後施行になる予定です。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"そういう形でメッセージとして出しているのかどうかというのが１点と、それから、それは何年ぐらいなのですか。そうすると、やっぱりそこは割と短いスパンでやってもらわないといけないのではないかと思うのですが、その具体的なところを説明を求めました。","respondent":"竹田住宅課長","answer":"防災として、どのようなことを備えていただくことが適正なのかということは、今後考えていきたいと考えています。区の考え方としましては、そういったことを判断基準に、裁判所に手続するかどうか判断していきたいと考えております。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"人気があるので、どのように手続されているのか、それを確認させてくださいというのが１点。やっぱり区の不動産団体に入っていないと駄目だとか、今、登録できる事業者はどういう条件になっているのかということを確認させてください。","respondent":"竹田住宅課長","answer":"居住支援事業のほうは、今回、２団体に所属していらっしゃる方というふうに限定しています。そういった条件がクリアできれば利活用が進んでいくと考えておりますので、そういったハードルを１つずつクリアしていきたいと考えております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"確認","question":"４つの視点、立地だとか、そういうことはあまり関係ないのですか。所有者とか近隣の理解ということに尽きるというようなことで理解してよろしいのか尋ねました。","respondent":"竹田住宅課長","answer":"そういうスキームになっておりますので、要綱等の変更は必要ございません。非常に老朽化しているもので、なかなか利活用するのが難しいという案件が数多くありますけれども、今後も粘り強く取り組んでいきたいと考えています。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985406?Template=document&Id=4340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":66019,"voices":159}},{"id":"r04-20220117-9","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"文教委員会","time":"午後 １時００分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"令和４年度新入学学校選択の希望申請理由に関する調査結果","agenda":"令和４年度新入学学校選択の希望申請理由に関する調査結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"指定校変更自体は１月から受け付けているのですけれども、昨年の５月の文教委員会で、伺いたいと思います。そういうケースがあるとしたら、例年何人ぐらいそういった方がいらっしゃるのかというのを伺いたいと思います。","respondent":"勝亦学務課長、有馬庶務課長","answer":"指定校変更の実績ですけれども、今年度に関しましては、小学校で入学できている方が約８０名、それから、中学校が２０名となっています。いわゆる学校の受入枠がないという状況になりますので、同じ学校をご希望いただいても… 来年の４月以降の教室、各校の対応策ですけれども、来年度に向けては１５校１７教室を整備しています。浅間台小学校で２教室、以下１教室ですけれども、以上です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一回確認したいのですが、それとも希望自体も受け付けないということなのか、そこを確認させてほしいと求めました。例外規定を使って、もう４０人学級で対応するしかないと考えていらっしゃる学校、今の時点でどこか予測しているのか伺いたいと思います。","respondent":"勝亦学務課長","answer":"そういった形での、学校選択で入れなかった方のご希望はできませんということでご説明申し上げて、希望をしていただかないような形で対応しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私は、選択制でそういう状況に学校を追い込んで教育の質を上げるというやり方自体は間違いだと考えています。こういった状況を見ても、形だけの選択制というのはもうやめるべきなのではないかと思いますけれども、区教委のお考えをお伺いしたいと思います。","respondent":"勝亦学務課長","answer":"そういった当初の目的、現在の目的、そういった学校の特色を出して選ばれる学校になっていくという考え方は変わってございません。地域とともにある学校という形で、コミュニティ・スクールなどを進める中で、学校選択制の意味がなくなったとは考えてございません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも区教委自身は地域と学校の絆を壊しているわけですから、こういった結果を毎年見せられていますけれども、いよいよ選択制というのは根本から考え直す必要があるのではないかと改めて意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もこの調査結果について伺いたいと思います。このアンケート結果を受けて、それぞれの学校で何か努力をしたというのでしょうか、そういうものがあったら教えてほしいと求めました。","respondent":"勝亦学務課長","answer":"原因等は出てまいりませんけれども、中には、校長先生のお話に感銘を受けたというご意見もいただいたりしている部分があります。そういった部分、お褒めの言葉と捉えて、学校の教育活動の独自性を出す中でも励みになっているものと考えております。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"でも、その方たちにはアンケートを取らないわけではないですか。何かその活かし方という、何かそれぞれの学校で工夫されてしかるべきではないかと思うのですが、その辺についてお考えを説明を求めました。","respondent":"勝亦学務課長、矢部教育総合支援センター長、工藤指導課長","answer":"アンケート結果の活用と、目標と活用という部分のご質問です。保護者の方のお考えがあるのだということで、そういった個別具体のお話は出てまいりますので… 少し学校現場の話をしますと、学校の内容、特色を説明するときに、大変活用して参考になりました。説明する活用… 希望申請した場合には、今回の報告とほぼ同じなのですけれども、兄弟関係、友人関係で、２番目に通学上便利というのが来て、３番目に教育活動です。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"で、選択してもらうためには、やはり情報公開が大事だと考えています。校則含めてもっとオープンにしていきましょうということを教育委員会としてもおっしゃってほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"地域によってそれぞれ経緯とか歴史とか、子どもの実態もありますので、その中で共有するです。今、実際に校則の見直しについての取組を学校だよりで毎月のように出している学校もありますので、好事例は紹介していきたいと考えております。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"好事例がこういった形で切磋琢磨につながると私も考えておりますので、引き続き各校といろいろ協議してほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"そういう校長先生の悩みを聞いたりするような機会を設けていただいているのかというのが１点と、ここでも差が出るのではないかと思っているのです。","respondent":"勝亦学務課長","answer":"そういったものを総合的に見ていただいて、学校の人気、不人気というよりは、本当のよさというものを見ていただくのは大切かと考えています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"では、芳水のところの居木神社に行くのですかと言うと、行かないのです。何でですかと言うと、こちらはお祭りでにぎわっていないから、向こうには行きづらいと。","respondent":"勝亦学務課長","answer":"確かに特に小学生のお話で言いますと、やはり人間関係とか友人関係の中では、学校のお友達というのが一番濃密な人間関係なのかと考えております。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"議事録を見直しするのを忘れてしまったのですけれども、兄弟枠の方というのは、全然入れないのですか。例年、何人ぐらい大体残ってしまうのかというのが分かれば。","respondent":"勝亦学務課長","answer":"今現在、兄弟枠でお待ちいただいている方につきましては、小学校で８７名お待ちいただいております。昨年度の実績ですけれども、今手元に数字はないのですけれども、半分程度の実現率かと記憶しています。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"もっともっと厳しい、大変なところの学校改修をより早くするみたいな、そういう計画というのはお持ちなのか尋ねました。","respondent":"有馬庶務課長","answer":"もちろん状況を見ながら対応しているところですけれども、そういったことはありませんので、教室を確保して対応していこうというのが原則の考え方になっております。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"各委員の質疑を伺っていて分かったところもあり、今の松澤委員から確認のあった兄弟枠のところ、抽選の兄弟枠の方の入れる入れないが半分ぐらいだと。私も今、手元にあって、自宅に置いてきてしまったので分からないのですが、それを改めて教えてほしいと求めました。","respondent":"勝亦学務課長","answer":"学校のほうにお送りしております、先ほどご説明いたしました学校案内で、学校選択をお選びいただく際に、兄弟枠についても触れてあります。抽選の中では第１位の順位として優先的に取り扱いますという記載に併せまして、そちらのほうは注意書きで明記して、周知しています。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"あえてここではご答弁は求めませんが、最適解というのでしょうか、そういうところは少し必要なのかと。今どのように取り組んできたのかとか、今どう考えていらっしゃるのか、あれば説明を求めました。","respondent":"工藤指導課長","answer":"学校の経営方針、熟議を通しながら進めているところですので、１年で大きく変わるであるとかということはない。現状今、取り組んでおりますけれども、さらに実現していくよう進めてまいりたいと考えているところです。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"こういう感じだと、タブレットを配られても、あまり活用されていないのではないかという保護者からの意見も伺ったりしたのです。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"３つ目としては、学校の第６波への対応方針について確認したいのですが、これまでの対応と何か変えたようなところはあるのでしょうか。伺いたいと思います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"すみません、正確な数字はないのですけれども、１月で約４０名出てあります。昨年の１１月１２月と感染者がゼロの状況から、半月でこれぐらいの数字が出ているという状況です。 小学校が１０１、中学校が１１ですが、６年生が大半を占めております。今日少し怪しいというか、陽性者が出た学校も、部活については今日は全体で控えたいという報告は受けております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"第６波で新たな対応をするということは特にないのかという確認をさせていただきたいのと、あと、報道等でも。改めて２点求めたいのですけれども、改めて保健所とも連携して実施してほしいのですけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"感染の対応ですけれども、国の統計報告としましては、学校内の感染は非常に少ないです。現状の対応の中で一定程度抑え込めていると考えていますので、当然、それ以外の部分について定期的に検査を行っていくという考え方ではございません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、とにかくやれることはぜひ様々全力を尽くしてやっていただきたいと思うので、やはりしっかりやれることをやってほしいと求めました。そこら辺は住民の意見などもしっかり伺いながら、強化していただきたいと重ねてお願い申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは教育委員会に求めることなのか、マスクは過敏であってできない子もいたりする中で、やはり換気がすごく求められると思うのです。どのように情報共有をされているのか、改めて伺いたいのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"換気をはじめ、感染防止対策は、校長会でも生活指導主任会でも毎回お伝えしています。差があると思いますので、お子さんに寄り添って健康第一で進めるように、これからも周知してまいりたいと思います。","id":"exchange-019"},{"speaker":"吉田委員","kind":"意見","question":"ぜひお願いします。で防寒という視点で、今までだったら許されないようなことも柔軟に対応していただけるよう、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"１つだけ。２つ学級閉鎖というお話がありましたけれども、やはり今はタブレットを使ってやるものなのか、そこだけ説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"やはりオンラインということで、せっかく配付のタブレットがありますので、活用していくということでございました。プリントがいい場合もあれば、「結構です」というおうちもあるということは踏まえて、全体的にはタブレット活用を進めております。","id":"exchange-021"},{"speaker":"松本委員","kind":"質問・要望","question":"今の吉田委員からの質問に関連しますが、文部科学省から、学校教育活動を継続するためのチェックリストが１４日に出ているかと思います。この周知の状況がどうなっているのかというところと、要望としては、そこのところの対応状況をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"通知文につきまして、先週末ということですので、こちらで確認しまして、必要な周知をしていきたいと思っています。","id":"exchange-022"}]},{"id":"topic-03","title":"を改めて聴取いたします。 (3)西大井広場公園内における認可保育園の運営期間延長","agenda":"を改めて聴取いたします。 (3)西大井広場公園内における認可保育園の運営期間延長","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"待機児童はまだ解消されていないですし、期限を区切るというよりも、子育てをめぐる環境が改善されるまではぜひ継続していただきたいと思っています。少し伺いたいと思っていまして、１０年ではない理由なども含めて、伺いたいと思います。","respondent":"若生保育支援課長","answer":"ただ、今後の人口の動向は、１０年先はなかなか見込むのが難しい部分ではあります。その見直しの状況を見まして、今後、この１５年という期間をどうしていくのかというところは改めて考えていく必要があると認識しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"需要を算出するに当たっても、事実上待機なのだけれども待機児から外されてしまっている方々などもしっかり視野に入れて考えていただきたいと。毎回言っているのですけれども、改めてここでも要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"だから、そのときは限られた年限でという説明をされたと思うのです。今の説明会には、やはり公園利用者というか、そういう近隣の方たちも説明会の対象として含まれているのか、その辺について伺いたいと思います。","respondent":"若生保育支援課長","answer":"西大井広場公園内の保育所の設置の前段としての説明会のときのご説明の範囲ですけれども、当然、公園整備と併せて説明会を開催することとして。当時の説明では上限が１０年だったということで、同様に説明が必要になりますので、説明会を実施する予定です。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくの保育園ですので、ぜひ近隣の方たちに温かく受け入れてもらえるような保育園運営をしてほしいと求めました。どうしても人数が多かろうが少なかろうがありますので、その辺の合意というか、その状況について教えてほしいと求めました。","respondent":"若生保育支援課長","answer":"こちらの公園内の保育所を１０年より先どうするかというところでは協議を進めてきたところでございまして、事業者の意向を聞き取ってあります。こうしたことも含めまして協議をしていきたいと考えております。","id":"exchange-026"},{"speaker":"吉田委員","kind":"提案","question":"具体的にどうすべきという提案が今思いつくわけではないのですけども、ぜひ工夫していってほしいと求めました。これは要望ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"そちらのほうのでということなのかというのが１点と、１５年に延長ということなのですけれども、またこれが再延長みたいな形でしていくのかというのを教えてほしいと求めました。","respondent":"若生保育支援課長","answer":"今回５年という判断をしたわけなのですけれども、５年間でその先さらに延長するということになった場合は、更新は、制度上は可能です。やはり保育の需要を見ていかないといけない部分ではありますので、今のところ、その先のところというのはまだ未定です。","id":"exchange-028"},{"speaker":"湯澤副委員長","kind":"意見","question":"ぜひそうなったときにはお願いしたいと思いますし、そういったところも課題になってくると思いますので、そちらのほうもぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"１５年間になったというところで見ていくと、当然、十分な採算が取れていると見立てるところもある。当然、事業者としての運営状況というのは、これは今後の見立ても含めて問題なくやっていけるというところでいいかどうかの確認をお願いします。","respondent":"若生保育支援課長","answer":"実際、事業者からの話を聞く限りでは、少なくとも１０年では採算が難しいというところは聞いているところです。は、どういったやり方で保育園を継続しつつ事業者の負担を軽減できるかということは考えていかなければいけないと思っているところです。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"この間の第３回定例会で質問させていただきましたけれども、都市公園法の中、教室がどんどん空いていくと思うのです。そのような活用とかをしていいのかどうか、もしくは、既にそういうお考えがあっての前提かというのが、その辺が分かれば説明を求めました。","respondent":"若生保育支援課長","answer":"実は、事業者からの、こういう場合はこういう活用の仕方をというところまではまだお話ができていないというのが現状です。一つは定期利用のような形も考えられると思うのですけれども、そういったことは可能かどうかは、今後お話しするという形になろうかと思ってあります。","id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"できなかったことについての内容については伺ったのですけれども、右のほうに赤字で、コロナ禍でも継続できる形へということが書かれていますよね。ほかにも何かあったら教えていただきたいのと、何かご意見とか聞き取っておられることがあったら伺いたいのですけれども、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"地域との連携事業はなかなか今できない状況ではあるのですけれども、状況がよくなってからは、広いところではやっているところです。これについてはなるべく導入するという方向で、具体的なことはもう少し研究させていただいて、今取り組んでいるところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"その中で１点、私たちがよく求めている斜めの大人の関係、あまり広報すると人が集まり過ぎてしまうという。個別の工夫として実行されたことなのか、何か一つのよい事例として今後広めていくようなお考えがあるのか伺いたいのですが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"広くは広報していないけれども、そのような趣旨もありまして、環境的に近くにそういうスペースがある児童センターで行いました。全館やったわけではなく、ハード面の中で活かされるところで行っております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"子どもたちへの支援で、ぜひその辺のことはこれからも工夫していただいて、よい事例については共有して広げていってほしいと求めました。これは最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこを確認させていただきたいのと、あと、直営館が１３館でしたか。そこら辺、どういう感じで把握されているのかというのも伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"１３館直営館があるのですけれども、１３館で、そこの意見もまとめて提出してもらったというところがあります。密という言葉は今どき言いにくいのですけれども、情報共有は密にしていたので、状況的には同じ感じでやっております。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望と質問なのですけれども、予算もさらに増やしていくべきなのではないかと思いますけれども、それはいかがでしょうか。１ページ目では６４７件が相談件数となっていますけれども、３ページ目でいくと７７６件という数字が出てくるのですが、お伺いしたいと思います。","respondent":"廣田子ども育成課長、山下子ども家庭支援センター長","answer":"子ども・若者の支援に関しましては、高校生に、利用していない方がどういうところを求められているのかというアンケートを実施しております。その内容を見ながら、求められている支援についてコロナ禍で感じたことと併せて… 対して３ページ目でお示ししております、令和２年４月１日から１２月末日の段階で、件数について相違があります。１２月末時点での令和２年の受理の状況が４７８件、被虐待相談の欄に記載の数字です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"今の所管の子どもの権利条約についての認識というのを改めて伺いたいというのが１つ。それと、これ、こういった点からも広げる必要があるのではないかと思うのですけれども、それはいかがか尋ねました。","respondent":"山下子ども家庭支援センター長","answer":"やはり国際的な取決めといいますか、皆さんこれを世界的に進めていこうということの動きの中で、やはり大事な一つの視点だろうと認識しております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"これもすごく大事にしていただきたいですし、広い認識というのをつくっていけるようにもしてほしいと求めました。ぜひ利用していない方、利用している方の意見を聞くということですけれども、ぜひ予算のほうも充実していく方向で重ねてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"虐待のほうなのですけれども、先ほど特徴的ということで、令和３年度は児童本人から通報があったという話がございました。これ、分かればでいいのですけれども、どうやって通報したのかというところを教えてほしいと求めました。","respondent":"山下子ども家庭支援センター長","answer":"一定、来所か電話かといったような手段というところにおきましては、電話での相談だったかと記憶しています。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"何がまず虐待なのか、手段がない子どもたちがどうやったら通報できるのかというところも検討しながら本件については当たってほしいと求めました。これはあくまで要望でとどめておきます。","respondent":"山下子ども家庭支援センター長","answer":"子ども家庭支援センターとしましても、名刺サイズの、電話番号を記したようなものを各学校の児童・生徒に配布させていただきました。今の委員からのご指摘は、私どもといたしましては、こういった相談窓口があるのだというところは周知啓発に努めているところです。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"４０代が２名というのは、要は４０代の方が少ない理由を教えてほしいのが１点と、児童センターの職員はやはり相当なストレスの中でやっているのか。実際に話も聞いていると思うことがあるのですけども、それについて区としてどのように捉えられているのか、説明を求めました。","respondent":"廣田子ども育成課長","answer":"ここ２年はコロナがあったので、事業も経験できない職員がいたので、そこも育っていないという状況で、このような言葉が出てきたという。事業の在り方を職員の身の丈と利用者の求めるサービスとバランスを取る必要があると課題が見え、今検証をしている背景となっております。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"言わば子どもの遊びというのは絶対密になるではないですか。密になるのが子どもの遊びですから。","respondent":"廣田子ども育成課長","answer":"２年生に１月に配っていただいたのですが、ＱＲコードをタブレットで読んで、保護者と一緒に回答してくださいという形でお願いしています。高校にも２校ほどご協力いただいて、ワークショップ等もやっていって、聞いていくということを考えてあります。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういうのができているのは知りませんでした。どういう方向性に行くとか、学校とも連携しながら、引き続き頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"延べですから、それぐらいの方が何らかのことを求めて児童センターに来て、また心を満たして帰っていっていたのだろう。令和３年度、これからどういうことをやっていけば、つながり続ける工夫の取組を改めて説明を求めました。","respondent":"廣田子ども育成課長","answer":"配置４から６年目の職員を集めて、職員が汗を流しながら、どうやったらいいかということを考える機会を次年度にも続けてやっていこうと思います。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"まもるっちの中では、ＨＥＡＲＴＳへの通報も、登録ですかね。入っていないということだけ、もし分かれば教えていただきたいのですが、可能であればお答えほしいと求めました。","respondent":"山下子ども家庭支援センター長","answer":"それは、教育総合支援センター長からも、少しそういったような連絡であったり相談というのが増えているといったようなところがあったかと思います。教育総合支援センターから子ども家庭支援センターへの連絡というのは連携が取れるものと認識をしております。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"そういったところの取組というのは一つ安心はできるのですが、ダイレクトにというのですか、直につながれるような部分も必要なのかと。産後の家事・育児をなぜ支援するのかということに立ち返ったときには、あと、もしあれば説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"教育総合支援センターのほうでは、１１月３０日に、虐待の相談が少し増えているというご報告があったかと存じます。これまでも、少し気にかかることがあったということでご連絡をいただきまして、私ども児童相談の部門と連携して対応に当たったことはあります。","id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"何かあったときには連携しますみたいな、そういうのはないですよね。逆に言うと、それが利用促進を阻害してしまったらいけないのですけれども、そこ、すみません、確認させてください。","respondent":"山下子ども家庭支援センター長","answer":"子ども家庭支援センター内の連携のようなところについて特に記載をしているところではございませんけれども、そういった支援ないし手立てが必要であろうというところにつきましては、秘匿性についてはきちんと担保しながら対応してまいりたいと考えています。","id":"exchange-047"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"乳幼児の親子に対しては緊急事態宣言下でも利用可能にしたという判断、そういうのも本当に大変だったのだろうと考えています。少し具体的に教えていただければと思うのと、どういった対応を取ったかというのがもし分かれば、教えてほしいと求めました。","respondent":"廣田子ども育成課長","answer":"本当に具体的にすごくたくさん現場からこんな厚い回答が来たのですけれども、やはりご家庭で在宅勤務が増えて、そういう相談もかなりありました。状況によっては子ども家庭支援センターだったりとか、ここについては、こちらの職員のほうで受け止めたりしていたと聞いています。","id":"exchange-048"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"先ほど来ご質問の中にもあったかもしれないのですけれども、コロナが明けてからも、コロナ前に戻るということがもしかしたら難しいかもしれない。そういったところについては、どういったお考えで、今後どういった取組をされようと思っているのかというのがあれば、教えてほしいと求めました。","respondent":"山下子ども家庭支援センター長","answer":"本日の所管事務調査を通じまして、虐待の増減の部分にコロナの影響がどれほどあったかというのは、なかなか見えづらいところがあります。","id":"exchange-049"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"本当にいざというときに頼れる人がいるということを認識してもらうことと、あと、いざとなれば助けてくれる人がいるということを認識する。保護者もそうかもしれませんが、そういった体制づくりに努めていただきながら、引き続きたゆみのない支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"もしくは所管課につないでいらっしゃるのかというところを伺いたいというのが１つです。その３つをお伺いしたいと思います。","respondent":"廣田子ども育成課長、山下子ども家庭支援センター長","answer":"教育総合支援センター、ＨＥＡＲＴＳとも連携しながら、そのようなこともあります。この中でＺｏｏｍとかで会った子も含まれていると思います。ご連絡をしても通じない、訪問してみてもご家庭の様子が見えないといったようなところから、こちらにご連絡いただくような場合があります。","id":"exchange-051"},{"speaker":"安藤委員","kind":"確認","question":"確認したいのですが、すまいるスクールのところで、スタッフが感染して、それが子どもにうつったということなのか、そこら辺を確認したいのと、それとあと、すまいるスクールのほうは、第６波に入ってから、特にこれまでの対応と、コロナ感染対策というのは何か変えたところがあるのか、伺います。","respondent":"廣田子ども育成課長","answer":"３日ぐらいで次々発熱をしているので、ＰＣＲ検査を実施して陽性になったり、誰からということは特定できない。学校と同じように黙食という形で実施をしておりますので、コロナの第５波のときと感染が安定になったときも対応は全く変えておりません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"そういう意味では、健康とか命の問題が一番深刻なのですけれども、定期的なスタッフへの検査というのはやるべきなのではないか。高齢者施設はやっているわけですから、そういったのを改めて検討していく必要があると思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"どういう言い方をしたらいいのでしょうか。どういう状況からこの事態が分かったのかをお聞きします。","respondent":"若生保育支援課長","answer":"こちらの判明した経緯ですけれども、退職した職員から区への通報がございまして、それを基に東京都に情報提供を行いまして、令和２年７月に東京都が特別立入検査を行い、状況を確認した結果、こういったことが判明したという経緯です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に深刻な問題だと思うのです。その後、再発防止の取組をするということですが、どうやって再発防止をするのかということを具体的に聞かせてほしいと求めました。","respondent":"若生保育支援課長","answer":"それから、全従業員へのコンプライアンス等、法令遵守の教育をきちんと継続的に行っていく。認可保育園も含めまして、きちんと適正な運営が行えるように、継続して指導等を行っていく必要があると考えております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"これ、利用しているお子さんとか家庭については、配置がなされていなかったわけなのですが、どういった不利益があったのか、実害があったのかというのと、あと、そういった利用者の方への説明というのですか、謝罪などはどのように行われるのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"少なからずの影響はあったということで、これは当然、法人側としても説明を行う必要があると考えています。お知らせについては、どのようにしていくかというところは、法人に確認をしてまいりたいと考えております。","id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"もともとは年１回、ここに関して、過去の立入りの調査状況というのはどのようになっていますでしょうか。東京都が年１回全部できているのかというところもあるのですけれども、あるいはきちんと年１回やられていたのかというところをお願いします。","respondent":"立木保育課長","answer":"指導検査ですので、保育課からお答えいたします。特段その際には、品川区内の、通常の指導検査の中では適正な運営がされているという結果が出ていたという状況です。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問・要望","question":"区がどうのこうのではなくて、これは考えないといけないのは、虚偽の報告をしていた可能性を検討しないといけないと思うのです。立入りについて条文がきちんとあるわけですから、罰金含めて対応するようにということを都と協議していただきたいと思うのですが、いかがか尋ねました。","respondent":"立木保育課長","answer":"今回の件に関しましては、広域的なところで突き合わせをしないと分からなかったという部分があります。東京都とも連携を取っておりまして、そちらのほうをきちんと対処するように、区のほうからも東京都のほうには話をしています。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"全体、私たち今までいろいろ保育園の質のところで質問する中で感じるところなのですけれども、どういう通報の仕組みなのでしょうか。この事業者に限らず、全体としてどのように捉えているのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"社内通報制度を設置し、区としては一定、そういった状況は防げるだろうということは考えてあります。このような公表を行うことで社会的な一定程度の制裁というところは行われているものと区としては認識しております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日、取りあえずそういう仕組みがきちんとできることを要望いたします。これは今日は要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/921668?Template=document&Id=5056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":63270,"voices":160}},{"id":"r04-20220117-5","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"総務委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"マイナポイント第２弾（国事業）の実施","agenda":"マイナポイント第２弾（国事業）の実施","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"こういう国のコロナへの支援のやり方について、区としてどういうご見解を持っているのかということを１点目に伺いたいと思います。それから３つ目、あるいは登録しておかないと公金が受け取れなくなったり、何かそういうことがあるのか尋ねました。","respondent":"宮澤情報推進課長","answer":"このマイナポイント事業自体の実施にあたりまして、公金受取口座であったり、個人情報につきましては適切な管理をして行っていくです。この登録につきましては任意という形になってありますので、登録したい方は登録できるという形になってあります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"質問の１点目についてはちょっと曖昧な感じですけれども、とにかく私としては給付金、困っている方に素直に給付金を出す対策を取ってほしかった。個人情報と引き換えに給付金を出すというやり方は取ってほしくなかったという意見を申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡部委員","kind":"確認","question":"１件だけ確認です。それとも地域センターに委託でそれ専用の職員を配置しているということなのか、ちょっと地域センターのその部分だけ、明確に説明を求めました。","respondent":"宮澤情報推進課長","answer":"地域センターにおきましては、地域センターの職員が窓口にお見えになった方の対応をしているという形です。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"第二庁舎にマイナンバーカードの交付特設会場を設置しているということで確認したのですけれども。その特設会場の設置について、担当課同士でどのような議論があってあそこに設置されたのかという部分をお知らせいただけたらと思うのですけれども。","respondent":"宮澤情報推進課長","answer":"現在、第二庁舎３階の広いロビーの部分で、マイナンバーカードの交付特設会場という形で、令和２年より実施しています。この間、マイナポイント事業の第１弾が始まってありますので、申込みが分からないという方についての支援もそこで行っているところです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"基本的なことをお聞きしたいのですが、まず現在のマイナンバーカードの申請状況について、この二、三年、給付金もありましたし、このマイナポイント第１弾もありますけれど、どのぐらいのパーセンテージが出ているのか教えていただけますか尋ねました。","respondent":"宮澤情報推進課長","answer":"令和３年１１月末現在の交付枚数は約１７万５,０００枚で、交付率は４３.１％になっております。令和元年度末の交付率が１９.３８％でございましたので、ここ１年強で２倍以上になったです。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問","question":"今は健康保険証として全体の８％しか使えていないということですが、そういったことで、もしお考えがありましたらお伺いしたいと思います。そういった高齢者世代への普及促進の施策についてお聞きしたいと思います。","respondent":"宮澤情報推進課長","answer":"広報紙でございましたり、区のデジタルサイネージとかでも周知等を図っております。交付を所管します戸籍住民課と連携しながら、イベント等の出張であったり、出前的なところで来年度以降も検討していこうと考えております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"けれども、今度マイナポイントをどうやったら取得できて使えるのかというのが分からない人もたくさんいると思うのです。その辺についてちょっとご見解を説明を求めました。","respondent":"宮澤情報推進課長","answer":"これにつきましては、戸籍住民課、地域活動課を含めて連携をとりながら行いたいと考えています。申し込んだ方々はおおむね約５０％ですので、支援が必要な方につきましては、先ほど申し上げました各窓口において支援をしていくという形です。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"使えないという方をやはりどうやって支援するか、フォローするのかということが、私は大事ではないかと。これはいつまでたっても増えないのではないかというような気がしますので、その辺は区としてもしっかり国に言ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"たけうち副委員長","kind":"質問","question":"昨年、このマイナポイントの２万円というのが報道でいろいろ出だして、大分区のほうにも、まだ始まっていないけれどもお問合せがあったやに聞いているのですが、その辺の状況とか、あとどのようなお問合せが多かっただとか、もしあれば説明を求めました。","respondent":"宮澤情報推進課長","answer":"その翌日に、電話のお問合せが３０件程度ございました。内容としましては、特に健康保険証の登録や公金の受け取りの部分についての問い合わせが多かったです。","id":"exchange-009"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"その後７,５００円使えるなら、変な話家族４人いれば８万円ですから、ではやろうかなという方が増えてくるのかなとは思っています。その辺の見込みはどうなっているかということと、ぜひ積極的にやっていただきたいと思うのですけれども、その辺のところを説明を求めました。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの交付体制、支援体制を含めて、所管します戸籍住民課と連携しながら進めているです。体制につきましては区職員、また会計年度任用職員、委託職員を活用しまして、体制を組んで積極的に対応していくです。","id":"exchange-010"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"ぜひ積極的に前向きにこれをうまく活用して、普及を広めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"資料７の「なぜスウェーデンの投票率は高いのか」というところで、小学校６年生の社会科の教科書を見てみると、投票に行くことや。ですから、もっと現実のことを教育すればいいのにと思ったりもしたのですけれども、その点はいかがでしょうかということを聞きたいです。","respondent":"齋藤選挙管理委員会事務局長","answer":"私も理解が足りていないかもしれません。やはり日本の国の立て付けでは、具体的にどこかの会派の主張を比べて評価するというのは、なかなか日本の学校では難しいのかなと考えております。","id":"exchange-012"},{"speaker":"おくの委員","kind":"確認","question":"罰則や入獄、あるいは権利制限というような方法で投票率を高めるというような方向に走ることはするべきではないということを改めて思いました。その点は、確認みたいになりますけれども、そういう理解でよろしいのでしょうか、伺います。","respondent":"齋藤選挙管理委員会事務局長","answer":"選挙制度に義務制を入れるということの議論は、品川区のレベルでできることではありませんし、私どももそのような権利制限ということを正しいとは考えておりませんので、あくまで投票率が高いという国の例をということでお示ししただけです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"何かあったら伺えればと思います。今、その若年層の方たちにどういった働きかけ、啓発活動がされているのかというところをお知らせほしいと求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"やはり小学校６年生ですとまだ発達段階にありまして、考えるというのがなかなか難しいので、主権者としての大きい一歩になると考えています。コロナが収束しましたら、もう少し幅広く立正大学以外の大学生や専門学校生も含めて、意見交換の場を持ちたいと考えております。","id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"「国分寺の投票率を１位にプロジェクト」というのが、今後あるのかというようなところがもし分かれば、お知らせいただけたらと思いますとの意見を述べました。","respondent":"齋藤選挙管理委員会事務局長","answer":"あるいは幾つかの商店街で選挙の投票済証を持っていくとちょっと割引が得られるといった仕組みが品川区でかつてあったことは承知しております。あくまで投票は本人の自発的意思に基づいて実施すべきもので、ちょっと今は尻すぼみでありまして、私どもとしても正直動きにくいです。","id":"exchange-015"},{"speaker":"田中委員","kind":"意見","question":"どうしたら投票率を上げられるのかという、ぜひ積極的に、それで品川区での投票率の向上を目指してほしいと思います。何かあれば、言ってほしいと求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"国政、都政に反映させるという意識も生まれると思いますので、そしてまたそういった考えを共有すること。そういった形でちょっと時間はかかるかもしれませんけれど、長い時間をかけて意識啓発に努めていきたいと考えています。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"それとも品川区独自の条例で何か所ということで、今四百幾つですか。そういうふうに決められているのか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"実は原則は５,０００枚、１,０００枚、その建物の所有者・管理者の同意を得て貼ることができるのが原則であります。一番いい場所というとなかなか難しいのが現実でありますが、これからも努めて見やすい場所ということは考えていこうと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"ひょっとしたらそちらのほうに、自分たちの気持ちが少しでも反映されるのかなと思ってもらえたらいいということで質問させていただきました。その真意だけ伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"実際いろいろなことを自分に置き換えて、そういえば子供の頃どうなんだろうかとか考えた中で、結局本当に声かけが大事なのですね。質問するとすれば、区の選挙の道具とか用品を持っていってやってみたりというような経験はあるのか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"今、委員のご指摘があった投票箱や記載台をお貸しするという例はございません。","id":"exchange-019"},{"speaker":"渡部委員","kind":"提案","question":"それが何かのルールで駄目だというならともかく、品川区の持ち物で、公立学校で生徒会長を決めるという時に、もしどこかの学校からそういう提案でもあったら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"小芝委員","kind":"質問・要望","question":"タブレットを児童・生徒に１個渡されるようになったわけですから、教室の中で政治の関わり、公民の授業。それが必ずしもその後の投票率に結びつくかどうかは分からないですけれども、そういった方向性があれば教えてほしいと求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"例えば学校をまたがって、小学校や中学校を要は交流しながらいろいろな考え方を交換するだとか、こういったツールとして活用できるものと理解をしています。","id":"exchange-021"},{"speaker":"小芝委員","kind":"質問・要望","question":"本当にただで使えるツールがたくさんこのインターネットの空間には転がっていますので、そういったものをぜひ活用していただきたいと思いました。意見です。","respondent":"齋藤選挙管理委員会事務局長","answer":"平成２６年からＳＮＳを活用したインターネットの選挙運動も解禁されておりまして、あるいはメールで有権者の方に送ったりという手法もあります。","id":"exchange-022"},{"speaker":"たけうち副委員長","kind":"質問","question":"この２１歳から２４歳まで、またさっき申し上げた１９歳に特化して対応してきたところの成果とか評価とか、その辺があれば説明を求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"１８歳、１９歳の方にはカードを送っておりますが、やはりもう少し啓発が必要なのではないかと考えております。２３区ではやはり都知事選が一番投票率が高いという傾向があり、区議選については、基本的にはないのかなということを考えているところです。","id":"exchange-023"},{"speaker":"たけうち副委員長","kind":"質問","question":"なかなか評価が難しいところだとは思うのですけれど、ただ、この１９歳の啓発チラシはまた続けてやっていかれるのかなと思います。この２１歳から２４歳、また２０歳、区内のそういったところに向けて選管が啓発していくということはやっていらっしゃるのか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"先ほどお話ししましたが、立正大学とはあるゼミとの関わりを持ちまして、意見交換の場を年に二、三度持ったところですが、他の大学とはありません。今後、そういった方々も含めて広くフィールドワークのような形でもって、若い人の層のご意見を聞きたいと思っているところです。","id":"exchange-024"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"分かりました。必ずしも住民票が品川区にあるかどうかというのは、地道かもしれないですけれど、着実に上向いていければいいなという期待を込めて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡辺委員長","kind":"質問・要望","question":"２０代、３０代がセットなのかとか、何か感覚でもあれば教えていただきたいのが一つ。この２点をまず伺います。","respondent":"齋藤選挙管理委員会事務局長","answer":"２００人の方がいらっしゃり、毎月運営委員会を開いておりますし、他の自治体から視察に来られる方もいらっしゃいます。品川区は２３区では大体６番目か７番目に投票率が高い認識があるのと、現下なかなか厳しい状況もあって、三年お持ちだというのは理解しています。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"２１歳、２２歳というような人たちが、見ていてすごく品川区ではこの状況があるのかなと考えています。ですから、２２歳というのがよそから流入された方たちだと、最後に言わせていだきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"これは質問していいのか、接種履歴確認のお知らせというのは、全く分からない状況に今もあるのか。それに返信用の封筒も切手も貼っていないのですけれど、どうしてこういうことが起きるのか尋ねました。","respondent":"古巻総務課長","answer":"転出した方の２回目接種は確認できるのですけれども、いわゆる今の３回目の接種対象にはならないので、区としてお知らせはしないです。ですが、あくまでも区として２回の履歴を把握できませんが、必要であれば接種券を申請してくださいというお知らせをしているということです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"けれども、品川区のほうから２度接種しましたかとまず案内が来て、もし接種したなら、接種したとご回答くださいと。どういうことだということで、だから区と国の連携がなければもうしようがないのですけれども、ちょっとこれは不思議だと思ったのですとの意見を述べました。","respondent":"渡辺委員長、古巻総務課長","answer":"今は総務課の範疇の答弁で、後でそこは個別にやってください。先ほどの続きの説明だけ。 どのように連絡しているかは私どもで把握していないので、すみません、所管のほうにご確認いただければと思います。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816435?Template=document&Id=2222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":28364,"voices":69}},{"id":"r04-20220118-14","meetingId":"r04-cm01","date":"2022年1月18日","dateIso":"2022-01-18","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、個人情報を適切に管理し、安心・安全を求める国民に信頼されているということがすごく大事だと思うのです。デジタル化を進めていく上での大前提となると思うのですけれども、区としてはどう考えているかを、まず説明を求めました。","respondent":"宮澤情報推進課長","answer":"平成２８年から、３つのネットワークに分けて、それぞれのネットワーク間が行き来できないような仕組みを取り入れています。個人番号を含めて、情報資産につきましては、適切に管理・保護をしていくことで、安全性を図っているところです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"プライバシーが侵害されたり、漏えいしたときに、責任を取るのは地方自治体になるのでしょうか。もし地方自治体が責任を取るとしたら、どのように取ることになるのか、そのようなところは、今、考えられているのかを伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"システムの標準化・共通化の対応につきまして、例えば、区のサーバー室もしくはクラウドサービスによるデータセンター等に保管等がされています。今の段階では、計画的・具体的なところは、お答えができないところになってあります。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"去年の２月にもデータセンターで事故が起きたりと、様々な事故が起きている下で、やめるべきではないかと私は思うのです。ですので、ガバメントクラウドの利用はやめるべきだと思うのですけれども、区の考えはいかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"ガバメントクラウドの件につきまして、昨年、政府のほうで、ガバメントクラウド運営事業者が決定したということは承知しています。システムの標準化後に、まだ詳細な仕様等が出てきていない段階で、なかなかお答えはできないと思うところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"しかし、やはり必要な人材というのは、しっかりととどめておいてほしいと思います。窓口業務はすごく大事だと私は思うのですが、まず、区の窓口業務の役割について、区はどのように考えられているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"窓口業務はすごく大事だと私は思ったので、区の認識を伺いたいと思って、お聞きしました。残すべきところは残すというところで、窓口業務、そして住民に接する業務の職員たちをどのように考えられているのかを伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"そのようなデジタル技術を活用することで、そのような区民の利便性が向上できるような形に図っていきたいです。業務の効率化を進める部分になりますが、業務の効率化を進めて、窓口では丁寧な対応ができるのではないかと考えるところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それの区としてのガイドラインの整備なども、区民に示していくべきではないかと私は思うのです。そのようなところを、どう強化していこうというところがあれば、ご説明いただきたいのですが。","respondent":"宮澤情報推進課長","answer":"１つ目として、丁寧な窓口対応等に振り向けることができるというところで、デジタル化のメリットを活かせるのではないかと思うところです。いわゆるデータセンターの位置から情報の取扱いまできちんと確認しているというところで、情報の安全を確認しています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"区民の利益とプライバシー、人権を守るデジタル化にしていくべきだと思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それを改善する新たなＩＴ情報の提供等をして、ぜひ、さらに前向きにデジタル化を進めていただきたいという思いで伺います。新たな課長になると思うのですけれども、そこの横串を刺す力の強さの２点、お伺いいたします。","respondent":"宮澤情報推進課長","answer":"デジタル化に取り組んでいきますので、デジタル化を進めていくに当たってのビジョンをつくって、区全体で共有する必要あると認識しております。先ほど説明させていただきました、全庁横断的に課題に取り組んでいく必要がありますので、進めていきたいと考えているところです。","id":"exchange-008"},{"speaker":"芹澤委員","kind":"提案","question":"ぜひ新しい会議体の中で新たな提案をして、最新のデジタル化ができればいいと思っていますので、よろしくお願いします。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"２点、お伺いさせてください。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西村委員","kind":"質問・要望","question":"具体的な質問で申し訳ありませんでした。そのような意味も込めまして、要望も含めて、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"サーバー、１つぐらいを購入して、この事業をやっているのかどうか。どのような形になっているのかを説明を求めました。","respondent":"宮澤情報推進課長","answer":"職員が、その法体制に対応できるように、カスタマイズを重ねていました。ＡＩチャットボットであれば、いわゆるライセンス契約を結んでいる、つまり、ユーザー契約で契約して、活用しているという形になってあります。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"そのときに、どこのサービスを使うのですかということが、一つの検討になってくるのだと思うのです。そのようなお考えを、個人としてどう思うかということと、どこかで始まっているということがあるのかどうかを説明を求めました。","respondent":"宮澤情報推進課長","answer":"まず、どのようなシステムを活かしていくかというところの検討から入っていかなければいけないというところがあります。で、標準化に向けた作業もやっていかなければいけないというところがあるので、それは一つの大きな課題かなと感じているところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"もしかしたらチャンスがあったりするのかなと思いますので、そこは、できることは進めていただきたいと要望したいと思います。このことについて、お伺いしたいと思います。","respondent":"宮澤情報推進課長","answer":"システムを標準化した場合です。ここがまだ国から示されていないので、どのような形になるかということが、現状ではまだお答えができかねるです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"ここをどこが負担するのかという、国が負担してくれるのかというところは、私としてはそうなのだろうなどと勝手に思っています。共通化することによって、品川区が自前でやっていたときよりは、負担は減るのだろうということは言えるというところでよろしいか尋ねました。","respondent":"宮澤情報推進課長","answer":"ガバメントクラウドを利用した場合につきまして、まだ詳細は出てきてはおりませんが、一定程度の負担は出ると考えているところです。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"動いているということの確認と、まず１点、教えてほしいです。マイナンバーカードの取得率が四十何％と伺って、そちらを最優先的にやるべきだと、その辺の考え方。","respondent":"宮澤情報推進課長","answer":"１２０台と申し上げましたが、テレワークを実施していますが、いわゆるＬＧＷＡＮ回線と言われる自治体専用回線を使う技術を導入しています。先ほど、専用のテレワークシステム、アプリケーションを導入した形でないと実施ができないというところがあります。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"その負担がどうなっているかどうかは存じ上げているところではありませんが、たしか７,５００円をもらえるという報告が、昨日ありました。３年後、４年後を見据えて、進めていただきたいというところは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"せお委員","kind":"質問・要望","question":"そのようなところとの関連は、システムの標準化・共通化のところは、どうなっていくのかということをお聞かせいただきたいです。やはり、品川区全体で情報を共有してほしいというところが大きくありまして、オアシスルームなどといったところの情報共有もされていくのか。","respondent":"宮澤情報推進課長","answer":"続いて、２点目のところです。個人情報になりますので、ご本人の同意なく共有化ということはできない、システムによる共有化は難しいと認識しているところです。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問・要望","question":"第１グループの標準仕様書となっていますけれども、本当に同じことを話すということが、私たちからするとすごく大変です。そのようなところで情報共有がされていけば、利便性は図れるのかなというところがありましたので、そこはお話だけさせていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"２４時間、それぞれお客様のサービス、要望に対応・処理しています。２０２５年を目標にするということは、その辺について、ご見解を説明を求めました。","respondent":"宮澤情報推進課長","answer":"システムの標準化に関係して、２つ、ご質問があったかと認識しています。義務化している令和７年度末までというところを目標として進めていくに当たりまして、状況認識、対応に向けてスタートアップをしています。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"このようなやり方で各自治体が押しつけられたら、これはたまったものではないと私は思います。２０２５年までにやれと言うなら、運用できるようにつくってくださいということが筋なのではないかと私は思うので、意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"それ以外はもう押さなくていいと、９割ぐらいは押さなくなるではないですか。誰がやるのか尋ねました。","respondent":"宮澤情報推進課長","answer":"考え方を持ち、進めていくという、いわゆる計画としてのものの準備を進めているところです。まさしく全庁的な連携を進めていく上での横断的な会議体の中で議論して、決定していくという形になろうかと思います。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてかというと、何をこうやっていこうといったときに、民間の人をたくさん入れたではないですか。それだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"可能な手続きということなので、すべてではないのかと思うのですが、そこのところの確認をさせていただきたい。やはり、そうした場合には、窓口で手続きができるようにすべきだと考えていますけれども、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"そのようなものの一つひとつを、どうしたらオンライン化できるかということを検討しながら、オンライン化につなげていくところです。人でのきめ細かな対応のほうに回すというか、振り向けていくという形になりますので、併せて取り組んでいくです。","id":"exchange-024"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"国にしっかり費用負担をしていただくように、支援を求めていただきたいと思うのですけれども、いかがでしょうか。伺います。","respondent":"宮澤情報推進課長","answer":"標準仕様書の中でのいわゆるオプションで対応ができるのか、今後、本格的な内容精査の中で決めていくという形になってあります。システム障害等の対応につきましては、速やかにベンダー業者との連携の下、復旧等の作業をしています。","id":"exchange-025"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"区が進めてきた政策が弱められないように、制限されないようにということで、区としても取り組んでいってほしいと求めました。対応が遅れたりといったことがないように、区としてもしっかり危機に対応できるようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/474872?Template=document&Id=6122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":28941,"voices":63}},{"id":"r04-20220119-19","meetingId":"r04-cm01","date":"2022年1月19日","dateIso":"2022-01-19","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"そうしますと、どうなのでしょう、古い防災ラジオは回収されずにそのままにしておくということなのでしょうか。そこら辺、ご説明ほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"平成２４年度の機種につきましても、お持ちいただいて、ラジオとしてご活用いただきたいというふうにもともと考えていたところです。アナログ波とデジタル波双方に対応した自動起動タイプが、しばらくの間、そういったところについては丁寧にご説明してまいりたいと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"でも、いずれにしろ、新防災ラジオがないと、防災ラジオとしての機能は十分に果たすことができないということであって、新防災ラジオは必要になるということではあるのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"今ご指摘のとおりでございまして、アナログ波の運用につきましても、あくまで暫定のものですので、今後、必ず終了する時期が参ります。その際には新たな防災ラジオが必要になるものと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"要するに防災ラジオは防災行政無線の補完という位置づけですから、無償でやるべきではないかと、別に有償のサービスでも何でもないわけですよね。そういう方のために必要になるものですから、その点、いかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"令和４年度予算に計上されるということもございまして、現状、現時点では有償配布ということで考えてあります。私どもも、様々な用途を重ねて補完機能と考えていますので、現時点ではラジオを無償でということは考えてございません。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"ですから、前にも言いましたけれど、江東区では無償で全戸配布したりもしています。どうしても有償でやるということが当然の前提になっていたのですけれども、有償を絶対的な前提とするということで今もお考えなのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"今ご指摘のございました他区の事例につきましては、私どもも様々なところを研究させていただいたところですが、品川区におきましては、平成２４年度の防災ラジオの更新というような観点もございまして、有償での配布ということを考えさせていただいているところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"同じことの繰り返しになりますけれど、しかもその補完の中でも非常に有力な手段なのが防災行政無線ですから、いま一つ筋が通らないと私は思います。そういうふうにお願いしまして、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問","question":"私からは、別紙の６ページの真ん中の防災タブレットの整備についてお聞きしたいと思います。なかなかどういうふうに使っていいのか分からないといった声も伺っているところなのですが、また、現状の取組みなどを教えてほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"もう１つ、行く行くは完全に電子化するなど、そういったところの取組みも進めさせていただきたいと思っています。さらには、より詳しく説明する機会を各地域ごとに設けさせていただきまして、より一層活用していただけるようにしていきたいと考えています。","id":"exchange-006"},{"speaker":"小芝委員","kind":"質問","question":"タブレットの中でのやり取りが大分、盛んになっているわけではないですけれども、一部のエリアでは盛んになっていると。これからいろいろとフォローアップをしていただくという話は伺ったのですけれども、例えば１シーズンに１回ぐらいとか、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"具体的にはどこまでいけるかというのもありますので、その前段階といたしまして、様々な集まる場での活用を考えていく。これは何も防災に限ったことではなくて、そういったところも捉えながら、広げていきたいなと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"１点だけお聞きしたいのが、もともと１０か所でしたけれども、課長たちの頑張りで３４か所まで増えたと。そういった部分に関して、これからどういった充実を求めていく考えがあるか、説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"よい情報の波及というところ、そういう意味では、ＬＩＮＥは使用率を考えますと非常に強いインフラと考えています。チャットボットなどの実装も行っているところですが、そういったところできちんと連携できるように、今後も充実させていただければと思ってあります。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"おっしゃるとおり、８０％、９０％、ＬＩＮＥを活用しているという部分で、しっかりとＬＩＮＥの波及、そしてまた、情報弱者と言われる方には防災ラジオの充実、品川区は確かに情報伝達にかけてはすごく一生懸命取り組んでいると思っていますので、今後とも引き続きとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"目黒川の氾濫とか津波ですとか土砂災害等の警戒地域というのですか、どういったとき、何回ぐらいあったのかというのが分かれば説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"当時ははがきを送っていただいて品川区のほうで登録をかけていたので、そういったところで数字を押さえられていたところです。台風１９号など、こちらの通知実績というものは、行っているところです。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"台風１９号のときということなので、そうすると、自動的に機械音みたいなので、電話を登録されている方のところにいって、その方が電話に出ると、機械音みたいな音で今こういう状況なので避難してくださいとか気をつけてくださいとか、イメージとしてはそういう感じなのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"電話ではなくてメールで鳴る、そういったところもありまして、その併用によって通知させていただいているところです。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"そういう面では今の緊急通知コールですか、数がもし５,３００台を上回ってしまったら、その辺のお考えを説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"緊急時の情報発信につきましては、様々な方法があること、そういったものもきちんときめ細かく周知してまいりたいと考えています。委員ご指摘のとおり、引合いの状況などを見ながら、今後の取組みを検討させていただきたいと考えているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"もしかすると体験・講座という9)に当たるのかしらと思いながら伺っていたのですが、教えていただきたいのですが、いかがでしょうか。丸の２つ目、もしこういう順番でこういうふうに強化していくのだというのが既にご計画としてあったら教えていただきたいのですが、いかがか尋ねました。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"私から、１点目の高齢者、障害者等、避難行動要支援者に対する周知というところをご説明します。避難情報の内容というところに変更がございましたので、避難行動要支援者の避難支援の体制整備でいろいろ事業を行っておりますので… 私からは、被災情報管理システムの充実の具体的な内容についてご説明します。さらには、職員間のチャット機能なんかを持ちまして、より情報共有がされるような、そういった機能を充実させていただいたところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"大丈夫だと思っていたのが、そういうようなこともこの体験・講座というところで何か品川区として考えておられることがあったら伺いたいと思います。情報提供とそれから福祉的な視点と両方、あったら教えていただきたいのですが、いかがか尋ねました。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"実際の災害の体験というお話です。熊本地震で実際に被災された方の体験を２名の方にお話しいただくという講座を予定しているところでございまして、そういった機会を予定しています。 いずれにしましても、障害者福祉課をはじめといたしまして関係部署ともきちんと連携させていただいて、それぞれの特性に応じた形で今後取り組めるようにしてまいりたいと考えています。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"活用まで進むと、この情報がより活きるかなと思いますので、ぜひそのことも今後に向けて検討してほしいと求めました。もし何かあったら、お答えほしいと求めました。","respondent":"山本防災課長","answer":"しながわ防災ハンドブックにつきましては、全戸配布という形で区民の方にお渡ししているものになってあります。かなりいい情報が載っているものだと考えていますので、今後機会を見ながら、いろいろ考えていきたいと思ってあります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いつも要望として出されるのが、会員の先生方、そのことを区民の方々に事前に周知していただきたいというご要望を毎回頂いています。こういう要望は多分区にも届いているのではないかと思うのですが、この対応はどうされているのか教えてほしいと求めました。","respondent":"山本防災課長","answer":"区で対応している部分につきましては、災害時、一般の医療機関は閉鎖されるというお知らせをしているところです。現在、引き続き医師会等ともお話ししながら、今後の対応というところは考えていきたいと思ってあります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、様々な防災情報というところの１つだと思うのですけれども、そういうふうにしていただきたいという要望が出されているのだと思いますので。例えば聴覚障害の方に対しては、これは具体的にどういう形で手話通訳の方が実際に派遣されるのかという辺りも教えていただけたらと思います。","respondent":"山本防災課長","answer":"１点目の医療救護体制の区民への周知というところですが、委員ご案内のとおり、引き続き医師会とも連携して検討していきたいと思ってあります。昨年度は中止という形になって実績はないのですけれども、そういったところで対応を進めているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"団体の当事者の方々の要望というか、不安な思いだったり、ぜひここのところは具体的なところで取組みを進めてほしいと求めました。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"教えていただきたいのですけれども、そこら辺を教えていただきたいのが１点と、その辺の状況をまず教えてください。現地に職員の方が情報収集に行かれるというところですか、車両を使って行かれることもありますけれども、その辺の状況も説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"そういったところを並行させていただきながら、ドローンのパイロットの養成を併せて進めまして、現在、５名体制での運用ということになっております。様々な手段で現地に赴きたいと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"確認","question":"その中の9)に書かれておりますしながわ防災学校のオンライン講座の開始について伺いたいのですが、応募できる方の対象要件はあるのでしょうか。はその点を確認させてください。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"今後、費用対効果なども見ながら、必要なところがどういったところなのかという検討を進めさせていただきたいと思ってあります。現在、具体的には検討していないところですが… 防災区民組織向けの防災区民組織コースと、それから区内事業所向けの事業所コース、それから一般コースというのがあります。一般コースにつきましては、区内の方で、基本的に興味のある方でしたら、どなたでも受講することができます。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"これ、オンラインで２０名というのは随分少ないなというイメージ、もし数字を間違えているのでしたらご指摘ください。ましてやオンラインですから、今後これはどういうふうに講座を開いていこうとされているのか、その辺をお聞きしたいと思います。","respondent":"山本防災課長","answer":"定員についてのお尋ねです。２０名の定員というところですけれども、オンラインという特性を考えれば、一定の制限を設けさせていただいたというところが理由です。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"やり取りをする、いわゆるワークショップみたいな、意見交換みたいなものなのかなと聞いていて思ったわけですけれども、何か工夫できないですかね。せっかくの講座なので、オンラインも今までどおりにしていてよろしいのですかと考えるわけですけれども、何かさらにありましたらお願いします。","respondent":"山本防災課長","answer":"やり方というところで、委員にご案内いただいたように、例えばオンライン、複数でやるというようなところも我々検討はしています。物によっては著作権等々ありますけれども、アーカイブで放送ができたり、そういったところも今検討しています。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"今はどうしてもコロナの関係があるので、バランスよく、より多くの方が受講できるような体制をぜひ考えてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"確認","question":"そこの地域の方は、一定のあれはあるでしょうけれども、全員対象だということでいいのですか。それとも、さっき、全区民に広がったというふうに私は受け止めてしまったのですけれども、そこをもう１回確認します。","respondent":"平原防災体制整備担当課長","answer":"土砂災害、それから高潮の立会川というところに限定となりますので、区からの案内もこの辺にお住まいの方に案内をさせていただいているところです。ただ一方で、今、このエリアでない方もこれらの情報を受け取ることができるというふうになったというものです。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"意見","question":"それを知っている方と知らない人とね。ホームページの表現の仕方を考えていただいたほうがいいかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"令和３年度区内一斉防災訓練等の実施結果","agenda":"令和３年度区内一斉防災訓練等の実施結果","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"アンケートの集計結果ですけれども、集計結果は分かりましたという感じですよね。次の訓練に活かされるようになっているのか、その仕組みといいますか、その方法について伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"まず各地区総合防災訓練、区内一斉防災訓練共に、１月２８日に実施予定の地区防災協議会会長連絡会でお話をお伝えしていきたいと考えています。区内一斉防災訓練であれば、避難所連絡会議のときに再度お伝えして、進めさせていただきたいと考えております。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"その後、やはり改善されていくことが必要かなと思っています。そういうことはされていると思うのですが、そのように考えていいか伺いたいのですが、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"それの町会員へのフィードバックのお尋ねですけれども、それは先ほど申し上げた場でさせていただいてあります。速報ではありますけれども、改善についてはまた今後検討した上で、また町会の皆様と情報共有できればなと考えています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひいろいろな場で協議しながら、ブラッシュアップというか、そういうものにアンケートが活かされるといいかなと思って伺いました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"これを実際にやったのか教えてほしいのと、一般の人も参加すべき」が３１％で、密を回避してという部分で高い回答がある。そういった訓練のやり方とかを決めるのは、行政側なのか、避難所連絡協議会の中で委託している方が決めるのか、そこら辺を説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"訓練不参加者に対するオンライン、浅間台小学校と東海中学校につきましては訓練実施時期を年度内の別日に延期するというご意見を頂いております。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはりオンラインを促すという形になるのか、それを確認したいのが１点と、訓練のあれは分かりました。でも、逆にいうと、避難所は密になるということが明確に分かるわけではないか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"３つお尋ねがございまして、今、しながわ防災学校の避難所開設運営イメージゲームはいかがですかという声かけはしていきたいなと考えています。","id":"exchange-030"},{"speaker":"松澤委員","kind":"意見","question":"コロナ対応マニュアル、確かにつくっていただいて、すごくしっかりしたものがありますけれども、やはり今後、こういった体験訓練とかつくる訓練というのは非常に大事だと思いますので、そういうものも含めて、また検討していただけるとありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実際に地震とかが起きたときにこの学校に参集する職員の方が来られたかどうかというのを分かれば教えていただきたいのと、生徒２６０名で、紹介してほしいと求めました。","respondent":"五十嵐災害対策担当課長","answer":"参集職員については、大型の地震が発生した際に参集する職員に初めから１０名対応していただいております。実際に現場で町会の方々を避難者と見立てた対応訓練を一緒にやっていただいております。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"ここだけＺＯＯＭにてと書いてあったので、この表現は、ＤＶＤをＺＯＯＭで視聴したということなのかな。生徒とか町会の方とかが、ＺＯＯＭなのかリアルなのかは分からないですけれども、話合いをされて意見交換をしたということではないということか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"訂正します。自分たち中学生に何ができるか検討するという部分につきましては、再確認した上で、またお伝えしたいと思います。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"どういうのが来たのかなと非常に興味深かったので、個別でも結構なので、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"令和３年度品川区地域防災計画の修正","agenda":"令和３年度品川区地域防災計画の修正","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"もしくは、あなたは通常の区民避難所ですということを事前に相談の上、決めておくということでよろしいか尋ねました。","respondent":"山本防災課長","answer":"避難行動要支援者の避難先についてですけれども、その段階で具体的に心身状況等を見まして、あらかじめご本人とも相談をしながら指定すると。実際に発災したときは、その指定された避難所に避難していただくという変更にする予定です。","id":"exchange-035"},{"speaker":"たけうち委員","kind":"質問","question":"もともと直接避難はもうちょっと前からできるようになったというのは伺っていたのですが、そうなるとやはりなるべく近いところということになるのかと思うのですが、その辺の全体像を説明を求めました。","respondent":"山本防災課長","answer":"それから、直接避難の部分についてですけれども、今、高齢者福祉課、それから障害者福祉課でも個別避難計画の作成を進めているところです。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"何かあるということのないように、そこは柔軟にやっていただいたほうがいいのかなと思うので、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、５年たたないと、全ての要支援者、高齢者や障害者の方々がどこの避難所に行くかという計画が立たない、立ち切れないわけではないですか。そういう中で、そこら辺の個別計画と今回の計画の変更というところの整合性というのですか、その点を説明を求めました。","respondent":"山本防災課長","answer":"個別避難計画につきましては、区としてはなるべく早く作成を進めていきたいというところで、まずそちらに力を入れていきたいと考えているところです。過渡期の対応ですが、当然、そういったところは柔軟に対応していきたいと思ってあります。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"直接福祉避難所に避難したいというご要望を随分お聞きしているのですが、現実問題、具体的にどうなるのかというのを教えてほしいと求めました。そうすると、福祉避難所が二次臨時避難所も含めて１割にもならないという状況ですけれども、そこら辺の区の考え方はどうか尋ねました。","respondent":"山本防災課長","answer":"現実的な対応というところを考えますと、そこから移動していただくというところが現実的な対応だと考えているところです。ご家族だけでも対応できない場合があるというところになった場合、共助の力でどう対応していくかというところは一つ課題だと思ってあります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"５,０３０人ということですけれど、特に障害者のところは３０人とかではなく、その課題に取り組んでいくというところでぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781505?Template=document&Id=6608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36965,"voices":101}},{"id":"r04-20220120-10","meetingId":"r04-cm01","date":"2022年1月20日","dateIso":"2022-01-20","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":5438,"voices":23}},{"id":"r04-20220204-10","meetingId":"r04-cm02","date":"2022年2月4日","dateIso":"2022-02-04","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"品川区新庁舎整備基本計画における議会機能に関する意見","agenda":"品川区新庁舎整備基本計画における議会機能に関する意見","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"請願・陳情の提出、災害時のエレベーターが止まるなど、上層階とすることには多くの問題があります。まとめに賛同できますけれども、「上層階の配置とする」という表現のまとめについては、改めて反対を申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、今年１０月から始まる窓口負担を１割から２割に引き上げるという件について、今回、報告や質疑はあったのかということを伺いたい。これは意見なのですけれども、先ほどの前段の質問についてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、結果的に高齢者の方の健康と命に直接関わってきますし、長い目で見れば重症化もしますし、やはりこういった方向にはすべきでないと思います。保険料の値下げ、あるいは窓口負担の軽減などについてもぜひ意見を述べていただきたいと、重ねて意見を申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"少し説明していただきたいのですけれども、今の中身のことを議会運営委員会に報告をする理由がよく分からなくて、そこを伺いたい。議長名により意見の照会を行うというのはどのようなことなのかよく分からないので、ご説明いただけたらと思います。","respondent":"工藤区議会事務局長","answer":"２点のご質問です。今日、事前にこの手続について説明したほうが分かりやすいということで、事前に頭出しをさせていただいたです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"やはり我々は話すということが基本ですから、議会に安心して出席でき、いろいろな方と安心してお話しできるような環境を設定していただけないかと。どなたが感染したのかというのは必要ではないかなと思いましたので、今、提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"議員だけといっても、名前云々は、やはり混乱の種になるような気がしてならないのです。なので、私はできれば現状の取扱いにしていただきたいなという希望だけ先に言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"提案","question":"参考までに、これからもいろいろな場面で状況が変わっていくとき、常に議論が必要だと思うのですが、須貝委員のご提案の中で、いい面は分かったのですが、デメリットは何か考えられますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"そうすると、もう責任の部署がほぼ分かるから、そうやって余計な情報は外に漏れないようにする。漏れたら、その連絡経路で分かるような対応をして、その個人のお名前云々が外に出ないように工夫しなければいけないと私は考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの須貝委員のご要望というのは、名前を公表するということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"意見","question":"ただ、公式見解では、先ほどあったとおり、濃厚接触者という判定がされれば、それは当然、連絡が行くようになっています。いい、悪いと、今、私は言うつもりはありませんけれども、いわゆるプライバシーの最たるものであるということは申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"名前を公表するということは、極めて慎重であるべきだと思うし、私は行うべきではないと思います。必要な対応を行っていくという、その徹底が必要なわけで、名前の公表は行うべきではないと意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"どういう環境、状況で感染したと思われますということも私はもし教えていただけると、よりありがたい。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"せお委員","kind":"提案","question":"この場をお借りしまして、自民・無所属・子ども未来から１つ提案をさせていただきたいのです。このオンライン開催に向けた議論をしていきたいと考えていますので、提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"確認","question":"確認ですが、これまでもそのような議論があって、今後もそうなのだろうと思っているのです。ＩＣＴ推進会議ではやらずに、ある意味、議会運営委員会に差戻しみたいな議論があったということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"その再開といったところを、結局、ＩＣＴ推進会議で議論したことが、最終的に議会運営委員会に来ると思うのです。まず、議会運営委員会で承認ではないですけれども、検討していくかどうかということを最終的にまとめてもいいのかなと思ったのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"大沢委員","kind":"提案","question":"議論していただくための提案ではないことを、ご承知おきいただきたい。そういう提案と捉えていただければ結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ぜひＩＣＴ推進会議のリーダーに進めてくださいとお願いしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"確認","question":"議員にも様々な生活があって、その上で議会というものに参加するため、参加できるよう十分な保障をすることはとても大事なことだと思います。もんでいただいて、何か結論が出たら議会運営委員会の場で報告していただいて確認をとるという、従来の進め方で良いかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"大沢委員","kind":"提案","question":"こちらのほうで提案というか、提案ということで、せお委員も十分満足していると思います。その辺のところでご理解賜りたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5444#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":11519,"voices":55}},{"id":"r04-20220216-10","meetingId":"r04-cm02","date":"2022年2月16日","dateIso":"2022-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":9218,"voices":26}},{"id":"r04-20220221-3","meetingId":"r04-c-budget","date":"2022年2月21日","dateIso":"2022-02-21","committee":"予算特別委員会","time":"午前１１時４７分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1142#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1860,"voices":18}},{"id":"r04-20220221-10","meetingId":"r04-cm02","date":"2022年2月21日","dateIso":"2022-02-21","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1672,"voices":13}},{"id":"r04-20220222-6","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"区民委員会","time":"午前１０時００分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"を行います。 令和３年特殊詐欺被害認知状況およびＡＩ型特殊詐欺対策アダプタの運用状況等","agenda":"を行います。 令和３年特殊詐欺被害認知状況およびＡＩ型特殊詐欺対策アダプタの運用状況等","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"この増減に関して、要因分析をお聞かせいただきたいのと、在宅している機会が増えたということとは相関関係がなかったのでしょうか。その１点を伺います。","respondent":"森田生活安全担当課長","answer":"今まで１事業者に卸していた固定電話の番号を卸せないように拒否できるというものがありましたので、それも減少の一因かなと思っています。以上です。","id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"今回は還付金詐欺がこれだけ増加したことを受けて、家の周りとか、還付金詐欺の注意喚起を行っている車が町中を走っているのは本当によく聞きます。これはもう都内だけではなく、令和４年に向けてどのような対策をしていく予定なのか、その１点を説明を求めました。","respondent":"森田生活安全担当課長","answer":"ＡＴＭで携帯電話はストップですよと言うと、あれという形になって、そういった取っかかりもつけられるということで広まっているところです。効果検証とかも図りながら、どんな対策が一番いいのかを考えながら、随時進めていきたいと考えています。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"続きまして２番、ＡＩ型特殊詐欺対策アダプタ運用状況等についてお伺いいたします。そういった部分が課題になってしまっているのか、月額利用料１,４３０円、もしくは４４０円、これがいずれなのかというのも説明を求めました。","respondent":"森田生活安全担当課長","answer":"当初５０台を予定しまして、先ほど説明したものは無料の貸出しを随時進めているところです。当初５０台を予定しておりまして、各警察署を窓口としておりました。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"以前５０台をどういった方に配付を検討されるのかと伺ったところ、そこにハードルが１つある。その２点をお伺いします。","respondent":"森田生活安全担当課長","answer":"夜間等につきましては、現在品川区での対応につきましては、祝・日曜を除く午前８時から午後８時までを対象としています。以上です。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問・要望","question":"１７件中１件、全国的に２００台導入されている中で、ブラッシュアップしてほしいと求めました。２名が夜間対応で電話が取れれば、全国で１人、時間外の対応もできるかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２点目が、自動通話録音機ですか、無料貸出しをしており、青パトの方たちが常にサポートし、例えば、設置サポートもやっておられると思うのです。そういう設置サポートの実績というのは今までどのぐらいあるのか尋ねました。","respondent":"森田生活安全担当課長","answer":"参考までに、品川区は９番目です。青パトでの設置はまだ進めてはおりませんが、設置の方法とか、その都度説明させていただいたり。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"注意喚起アラームの総数は１８件ということでよろしかったでしょうか。確認だけお願いします。","respondent":"森田生活安全担当課長","answer":"設置の当初から警察署とのやり取りを進めておりまして、必ず対応というか、署員の周知もしていただいているところもございました。今後ともこの評価をつなげていくには、やはり警察との連携が必要ですので、機敏な対応は警察との対応を踏まえてやっていきたいと考えています。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2920#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12951,"voices":25}},{"id":"r04-20220222-7","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"八潮地域や小山台住宅跡地、そういう答弁があったと思うのですが、今分かっているところでどんな計画になっているのかを聞かせていただけたらなと。具体的にどういうふうに計画や方針が変わったのか、聞かせていただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第２１号議案、品川区立シルバーセンター条例の一部を改正する条例","agenda":"第２１号議案、品川区立シルバーセンター条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このシルバーセンターは４８年経過しているということで、広くなるのかどうかというのと、それが何階建てになるのかというところを教えていただきたいです。","respondent":"菅野高齢者地域支援課長","answer":"私のほうから、現状の施設の広さおよび階数と、今後、改築するに当たっての広さおよび階数等についてご説明いたします。改築予定の北品川ゆうゆうプラザに関しましては、６３１.９平米を予定しておりますので、１.６倍の広さになる予定になっております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"高齢者クラブの会長の方にもお話を伺ったところ、１つでも広い部屋があると、そういう設計になっていないということが口々に語られたのです。広くもできるというような、そういう設計とかにもできない段階なのか、そこを伺いたいのですが。","respondent":"菅野高齢者地域支援課長","answer":"令和元年度から、近隣住民の方、そして利用者の方も踏まえて丁寧に説明を重ねてまいりました。現在の施設の利用状況や、他のゆうゆうプラザの部屋の大きさ等から検討して、その辺りのところをご理解いただくように説明は重ねてきたところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。そしてご理解と、あと要望も受け止めていただいて、反映させていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはよくやっていただきたいと思っているけれども、解体なのだけれども、消防団の小屋はもう終わったではないですか。そこの間の部分をもう一度教えていただきたいのと、一言言葉をつけ足してもらうと、そこら辺のところを説明ほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"今後の説明会等の予定については、その前に、工事説明会を近隣の方および利用者の方にご説明をしていきたいと考えています。その中で、恐らく５月か６月ぐらいに説明会が行われると思いますので、そういった中で、具体的に丁寧に説明をしていけたらと思っているところです。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"７月から解体ということで、ここはいわゆる埋立地かどうかというのはまたいろいろ歴史をさかのぼると、地下はどうなっているのか。しっかりやっていただきたいという思いで、確認だけさせてください。","respondent":"菅野高齢者地域支援課長","answer":"解体工事は７月から始まりますので、説明会が今年６月ということで、今後、業者が決まります。そこの中で説明会をしてという形になっていくと思いますので、その際に、工事の期間を過ごせるようにということで配慮していきたいと考えています。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"工事ですから、どういう状況になっているか分からない、致し方なく工事内容を変更する。それで途中の様々な変化、また区民、近隣からのご要望に対しても、これは区が対応するのか、区のほうも業者任せではなくて、しっかりと寄り添って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ゆうゆうプラザでも大きいところは八十何人とかが入れる状況であると思うのですけれども、そういうところと比べてどうなのか、伺いたいと思います。令和４年第３回定例会において上程する予定ということであるのですけれども、いつ頃、そのスケジュールを分かっているところで説明を求めました。","respondent":"菅野高齢者地域支援課長","answer":"一番広いお部屋が約７８.５平米ということで、８０平米弱のお部屋が広間としてありまして、私も何回かそこに説明会でお邪魔させていただきました。現状は舞台を含めての約７８.５平米なのですが、大分、説明会の際にはご説明させていただいている次第になっております。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところは本当に大事にしていただいて、たくさんの方が集えるような方向でぜひご検討いただきたいと要望させてほしいと求めました。コロナが終息した後の定数だけ教えていただけたらと思います。","respondent":"菅野高齢者地域支援課長","answer":"実施設計がまだ仕上がっていない段階ですので、他の施設を見ると、６０人弱ぐらいの定数が確保できるかというところで考えております。１つのお部屋だけではなく、そういったところを工夫して、お使いいただければと思っているところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからもまだ検討する余地というのはあるのでしょうか。ぜひご検討いただきたいと思うのですけれども、最後に、その点をお願いします。","respondent":"菅野高齢者地域支援課長","answer":"一番広いお部屋の面積のことにつきましては、確かに説明会のときも、そういったご意見は出ておりました。工夫して設計しておりますので、その辺りのところは、今後も利用者の方の声を聞きながら検討していきたいと思っているところです。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"このときでも、この地域は、保育園の方も病院の方も言っていたけれども、全くクレームがなかった。利用者の方も溶け込んでいる方が多いので、ぜひそこら辺はクレームのないようにやっていっていただきたいと、これだけ要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"令和４年陳情第７号、補聴器助成金制度に求める陳情","agenda":"令和４年陳情第７号、補聴器助成金制度に求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"強い要望だなと私たちも思っていますので、ぜひ検討していただきたいなと私も思うのですけれども、昨年の３月に。この結果も出ているのですけれども、そもそもそれは把握されているのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"調べれば分かるのですけれども、回答する必要があるものについては、基本的には回答するという方針でやっております。それから、今ご案内いただきました内容につきましても、通知等につきましては、見落としがない限りは一通り、目は通しているつもりです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした提言、本当によく出てくれたなと私も思っているのですけれども、これらについてどのように区としては考えられているでしょうか。要は、自治体としてこれが必要だというふうに提言がされているのですけれども、これに関して、区としてはどのように捉えられているか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"もちろん自治体も検討することは十分可能だと考えていますし、我々は医療連携のほうも力を入れて、この間ずっとやってきております。品川区のほうでは在宅介護支援センターであったり、その中で先ほど２つ補足させていただいたような形で、こんなふうに考えております。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう中でもやはり５つ目の提言のところでは、一体的な支援が必要だ、そうした組織体制を構築することが重要であると言われているわけです。どのように捉えられているのかと伺ったのですけれども、そうした提言として、どう捉えられているのかというのをもう一度伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"そういった声をしっかり受け止めて、それを医療連携等でしっかりつないでいくというのが、これまで品川区がやってきた取り組みです。品川区に不足しているもの、少し弱いもの等があるようでしたら、そこは強化するというのが基本的な考え方です。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、家族の方に伺うと、やはり耳が聞こえづらくなってきてからが大きく変化していった、要は認知症が進んでいったと感じるとおっしゃったのです。こうした状況をつくっているので、これを見ても補聴器購入への助成制度は今こそ進めるべきではないかなと思うのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"どのような施策を実施していくかにつきましては、それから財政面から見れば優先順位といったものも出てくるかと思います。実施している自治体の有無につきましては、今は情報収集、研究というところでこの問題をしっかり捉えていくという認識です。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"情報収集等も必要ですけれども、情報収集と、ずっと答弁で言われているのですけれども、もう必要な情報は結構そろっているのではないかと思うのです。介護予防やＱＯＬの向上に向けてどう進めていくのかというのが問われていると思いますので、ぜひ積極的に、早急に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"自治体に対してこれだけ明確に５点にわたっての提言がなされて、こういうのも全部、自治体の役割として行うべきだという提言が出されたのですよね。適切な受診や支援につながらない、このことに関しての認識について、改めて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"前回の請願・陳情審査等でこの件を説明させていただいたときと今回で何が大きく違っていたかといいますと、まさに今、副委員長からご説明があった。当然把握しているので、先ほどと同じ答弁になりますけれども、今回このような答弁をさせていただいているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それから、補聴器を利用するための相談や認定補聴器技能者の周知、こういうところも区として取り組んでいくというところで検討していくということで捉えてよろしいか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"先ほどと同じ答弁になるのですけれども、まさにこの情報が入ってきた直近ですので、これを踏まえて、行政として今後どういうことをやっていく必要があるかということは、まさにこれからの検討課題ということになってくるかと思います。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私たちが求めてきた早期発見のための仕組みの構築という点では、そういうのもぜひ検討してほしいと求めましたし、これを進めるに当たって。私はぜひ補助制度をつくっていただきたいと思うのですけれども、そのルートに乗せるという点での補助制度という点ではいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"ルートに乗ることによって補助制度が生きてくるというのが正しい考え方であろうと考えています。効果的な使い方ができるのであれば、今の段階では補助制度をつくることによってルートに乗せるというそういう考え方は、私は持っておりません。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうふうなところになるわけですから、結局使い勝手が悪いので使われなかったというルートが問題になるのではないかと思うのです。だって専門ではないところでもいっぱい売っているわけですから、そういう点では。","respondent":"寺嶋福祉計画課長","answer":"しかも正しい使い方をしっかり継続してサポートしてもらうということ、これがまず重要な、ここは避けて通れない部分なのだろうと。この部分については全く同意見です。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてこの研究のまとめを見たときに、そのうちで補聴器相談医というのは４,７５８人で、半分以上が補聴器相談医という形になっているのです。そういう仕組みというのは、この品川区では環境として十分つくっていくことができるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"それから難聴の件について、何かご提案、お話があったということは記憶しておりません。もちろんそういうお話があれば、当然そういう機会はありますので、意見交換できることは当然あり得ることだとは思っております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"連続で３回ぐらい医師会の先生方から要望を受けまして、その要望というのは品川区にも同様に上がっている要望だと思うのです。ぜひつくっていただきたいと思うのですけれども、補聴器補助制度を、これからどうされていくのかということについてお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"現段階で補助制度の創設の考えはないということは、冒頭申し上げたとおりです。こういった中で、また１ついい形が何かできればということで、引き続きしっかり研究してまいりたいと思います。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この包括補助制度は、半分を東京都が出すということになっているわけですから、品川区としても助成制度を検討してほしいと求めました。東京都もこういう形で包括補助も出すと言っている中で、検討もしないのか、改めて再度、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"その自治体として取り組んでいるもので、やっていく事業の中に財源確保できるものがあれば、それはしっかり取っていこうというのが基本的な考え方。そういった中で、品川区のこの包括補助、選択事業を活用して、様々なところに財源として充てているというのが実態です。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そしてこういうデータも出されて、ここまでの提言がなされているわけですから、ぜひ補助制度を創設していただくようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"補聴器を利用している会派のメンバーがいたということもありまして、１０年以上前から会派の政策要望に出させていただいていたという経緯があります。我々も調査をする中で、本当にそれでいいのかというような議論も当時あって、会派の政策要望からは外したという経緯があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"若林委員","kind":"提案","question":"そういういわゆるアウトカムというのでしょうか、成果というのでしょうか、また検討を打っていただきたい。それに対しても私たちの提案等があれば、積極的にさせていただきたいなというのが今の会派としての立場だと申し上げて、したがって不採択で結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問・要望","question":"難聴患者の実態とか、あと品川区が連携できる医療機関など、そういったところも含めて引き続き調査・研究はしていただきたいと思っています。そういったできるところはしっかり取り組んでいただきたいなとは、そこは要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"使わない理由と購入しない理由は違うと思うのです。やはり助成制度を進めることが普及啓発につながると思いますので、採択で、ぜひ助成制度をつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"木村委員","kind":"意見","question":"我々としては、そういう意味では賛成していきたいなと、このように思っております。よって、これには賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、これまでのご説明を担当の方に伺いました。ただ、政策全体としてこれからどうするかというレベルでの検討をしていただいて、そういった大きな枠組みを検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"令和４年陳情第１２号、高齢者が健康づくりと生きがいづくりに集える入浴設備のあるシルバーセンターを八潮に整備するよう求める陳情","agenda":"令和４年陳情第１２号、高齢者が健康づくりと生きがいづくりに集える入浴設備のあるシルバーセンターを八潮に整備するよう求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"求められているものだと私も思うのですが、令和３年度予算において増改築の基本計画の必要経費を計上しているとあるのですね。それがあるのかどうかというのと、ぜひこういう機会にやはり検討していくべきではないかと、そこを改めて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"八潮南特別養護老人ホームの増改築の検討、定員増が図れるのではないかということで検討をするということで、こういった内容です。こういった検討、しっかり検討していくという、こういった状況です。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今のお話を伺うと、この八潮の地域では高齢化率が３５％を超えているというところでも、求められている施設だと思います。そうした部分でも、ぜひ、こうした改修の機会がありますので、ご検討いただきたいと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"８回陳情が出ているというお話でしたけれども、これらの陳情のほか、地域の方から入浴設備に対する一定のニーズがあると区としては捉えております。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう特質といいますか、しかもお風呂というところでは利便性もいい状況にあると思うので、ぜひ検討の中に入れていただきたいと思うのです。どうしてシルバーセンターに入浴施設というのはついているのか、その大本の根拠を伺いたいのですが。","respondent":"菅野高齢者地域支援課長","answer":"やはり既存の利用者の声を聞く中で、新しいところでも継続してそのサービスを続けさせていただいているというのが実状になっております。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり１人で自宅で入るには不安が大きいというところからも、生きがいづくり、そこには大いにこうした思いも共通してくるのではないかと思うのです。その話もずっと答弁の中では出されているのですけれども、具体的にそうした検討が始まるというのはいつになるのか、伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"以前も全世帯に対してアンケートの実施など、都市計画課で行いまして、まちづくりの検討についてを進めていると認識しております。令和４年度に新しく組織を設置するという話が出ておりますので、その中でまた、より具体的な検討が進められていくのかと認識しているところです。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１階が平塚橋ゆうゆうプラザで、これから増改築するということですので、ここにつくっていただくのが一番いいのではないかと思うのです。可能かどうかということで、そういうところからすると可能かどうかという点では、可能だと考えていいか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"この段階でお答えするのは非常に難しいところがありまして、その他のニーズも含めて、なかなか申し上げられないということがあります。そういったことを考えると、できます、できませんというのがなかなか答えられないと。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうふうなところが八潮にはないわけですから、地理的なことも踏まえて、ぜひつくっていただく方向でご検討をお願いしたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大規模改修の中でこうやっていこうと今お考えになっているということには私も大変理解できますので、そこら辺のところもしっかり踏まえていただいて。今度ここができるからどうという話ではないと私は思っていますので、そういうことも踏まえていただいて、全体を見てやっていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すでお願いします。将来像についてのまた具体的な前進もあるとお聞きしておりますし、しっかりやっていただきたいということで、引き続き不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。八潮全体を総合的に考えたところで、今後検討していっていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"高齢者の皆さん、お風呂のそういった施設の要望は多いというふうに把握もされているわけですので、そういった観点からも求められていると。そしてこういう増改築の機会があって、可能性もあると思いますので、ぜひそこの検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。入浴設備のあるシルバーセンターという１つの項目ではなく、区の政策全体でバランスの取れるような形で進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"第３２号議案、東京都後期高齢者医療広域連合規約の変更","agenda":"第３２号議案、東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この第３２号議案の資料の１の変更内容のところの、関係区市町村の一般財源から保険料の軽減のために負担を求める経費のこの５項目、これは５項目トータルで幾らなのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"トータルですけれども、保険料の最終案では、市区町村の負担額２年分といたしまして、合計でおよそ２２４億円を想定しています。品川区の想定ですけれども、５億１,１００万円ほどを見込んでいるところです。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、品川区が出す分というか、経費としては５億１,１００万円、これは２年間で半分ずつ入れていくという感じの経費になるのですか。そこを伺いたいのと、後期高齢者保険料は２年分ですよね。","respondent":"池田国保医療年金課長","answer":"今申し上げました５億１,１００万円につきましては、２年間分ということで、これを半分ずつにしたものが毎年の支払いということで考えているところです。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしないと、どういうふうに変わってきたのかという変化がなかなか見えないと思うので、ぜひ出していただきたい。毎回出していただいていたのですけれども、それが今回出ない理由というのは何かあるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"広域連合議会が１１月３０日に開かれまして、広域連合議会のほうが議決されないとご説明できないということがございましたので、時期によってはまたきちんと出すような形を取らせていただきます。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"確認","question":"前回は１１.４１％だったと思うのですけれども、それが上がっただけで、この２,８５６円の値上げになるという、そういう見方でいいのですか。前回１１.４１％だったものが１１.７２％に上がった０.３１ポイント分ということでいいのですかということの確認をお願いします。","respondent":"池田国保医療年金課長","answer":"それと現役世代の後期高齢者支援金というような形でやっていまして、残りの１割を加入している方の保険料で賄うことになっております。そこの部分が、それが１１.７２％に伸びるということで、後期高齢者負担率が上がったための保険料の値上げということになってあります。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"もともと１割というふうにしていたのに、厚生労働省がどういう根拠、そういう上限というのはあるのか。毎回上がり続けていっていいものなのかと思うのですけれども、そこを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"後期高齢者支援金ということで、加入している方ともども、今回は１１.７２％というような形になってくるのだとご理解いただければと思います。今後どのようになるかということについては、そこら辺は私どものほうでは見当がつかないところです。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に際限なく上がっていくということになってしまうのかなということで、心配だなと思って伺ったのですけれども、分からないということです。マイナス１.２０％と推計というふうにあるのですけれども、ここの説明をお願いします。","respondent":"池田国保医療年金課長","answer":"３の設定条件の（５）の所得の伸び率ということでのご質問だと思いますけれども、所得が減っているということで、マイナス１.２％ということで推計しています。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、要は７５歳以上でも働かれているということになるわけですよね。７５歳以上の後期高齢者の方が、分かれば教えていただきたいのと、この対象は何人ぐらいになるのかというのを伺いたいのですが。","respondent":"池田国保医療年金課長","answer":"６４万円という限度額を超える方については、全加入者のうちの３.３％ぐらいおりまして、１,３９５人の方が限度額を超える方がおります。この方が６６万円になったときにどのぐらいかということになりますと、それほどの影響はないかと考えています。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこに対して、平均で３,７８９円もの値上げになったというところでは、本当に高齢者からは悲鳴が上がっている状況ではないかと思います。しかも年収２００万円の方で２割負担になるというところでは、保険料の引下げこそしていただきたいと思うのですけれども、最後にいかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"当然特別区長会を通じて広域連合に要望を出しますけれども、こういった施策につきましては、２３区および全都で統一した形で支援していきたいと考えているところです。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"特例軽減は令和３年度で全面的になくなったと思うのですけれども、もともと一番初めに始まったときにはかなりの特例軽減がされていたわけです。全部保険料で入ることになったわけなので、そこはどこがどれくらい増えることになったのか、その点について伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"副委員長のお話があったように、被扶養者の軽減額につきましては、令和元年からおよそ１,４００万円ぐらい減っているところではあります。これが品川区の分では１,４００万円ほど減っているというふうな現状です。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、品川区分が１,４００万円で、東京都はその３倍と考えていいということでしょうか。もしそういう形で、それがどこかにどういう形で使われるとかという考え方は全くないのか、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療制度に加入されている方で７割、５割等の軽減を受けている方は、既にもう公費のほうで負担をさせていただいているとご理解いただければと思います。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、７割、５割、２割というのは、国民健康保険でもあるような本則ですから、それは当然のことなわけです。全面的に特例軽減をなくすという措置を取ったわけですから、高齢者の生活そのものが大変な状況になっているわけですから、改めていかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"私ども２３区、要望としては、特別区長会を通じて保険料を上げないようなことは要望はさせていただいてあります。今後も続けると思います。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"意見","question":"令和４・５年度の保険料率のところでは値上げすべきでないと主張させていただきましたけれども、この第３２号議案は軽減対策に必要な経費のための議案ですので、この議案には賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-06","title":"第３４号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３４号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"引下げこそということを私たちは本当に思っているし、求めているところですけれども、それで全体的に伺っていきたいのです。品川区が納める納付金総額は幾らになるのかというのを伺いたいのと、今回の国と都からの交付金は幾らになるのか、そこも伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"約８７億円、後期高齢者支援金分が約２４億８,０００万円、合計すると約１２３億円が令和４年度のほうの納付金額という形になります。国と都の支援金ですけれども、今回、東京都全体で繰入金を１.９億円ほど入れるというような形になっているところです。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だから品川区に１.９億円ではないと思うので、本当に保険料引き下げのために都にも力を尽くしていただきたいなというのは要望していただきたい。そして国にも言ってもらいたいということで額を伺ったのです。","respondent":"池田国保医療年金課長","answer":"来年の保険料については、また検討するという形になりまして、今後の景気状態によって変わってくるかと思っているところでございました。よろしいでしょうか。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区が入れる分は減らすわけですから、未就学児の均等割が１ページの(３)のところに少し書いてあるだけというか、本当に大きなことだと思うのです。だからこそ均等割はなくすべきだと私たちは求めてきましたので、２割軽減されている方、すごく分かりづらくなってしまったなという印象なのです。","respondent":"池田国保医療年金課長","answer":"未就学児の均等割についての説明が不足だです。その方たちが令和４年度の保険料で計算すると、合計額が２,９９０万円、およそ３,０００万円ほどが保険料の金額という形になります。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"減額なしの方も人数を教えていただきたいのと、上から４行目ぐらいですか、品川区保険料率等のところの均等割額が上げられたのですね。前回、令和３年度からは３,３００円か尋ねました。","respondent":"池田国保医療年金課長","answer":"次に、保険料の部分で、均等割がなぜ３,３００円上がったかですけれども、こちらは、先ほど保険料のご説明をしたときに、賦課額が出たかと思います。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この国民健康保険料の数字を伺っているのは、下げていただきたいということでいろいろ伺っているのですけれども、それともどういう意味で２億円上がっているのかというのを伺いたいのですが。","respondent":"池田国保医療年金課長","answer":"保険料の結果の部分で、基礎額の保険料が本来ですと９７.３％でやらなければいけないところを、９２.３％でやらなければいけない。後期高齢者支援金分、法定外の部分というのが、繰入金の部分は増えているとご理解いただければと思います。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして払える保険料にしていく、それが国民健康保険を維持していくことにもつながっていくと思いますので、そこはぜひやっていただきたいなと。ぜひ引下げをお願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"大変申し訳ございません。医療費とかを全部含めてですけれども、令和４年度につきましては、２１０億８,０００万円ほどを交付金として頂くような考えでやっているところです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"全体でですか。お願いします。","respondent":"池田国保医療年金課長","answer":"都の繰入れ、繰上げ、２号分とかの純粋たる成績分の額ということではないですよね。そこだけ確認させてください。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"確認","question":"国は２１０億円で、国民健康保険への支援金として入ってくるのは２３区全体で２１０億円ということですか。最後、確認だけお願いします。","respondent":"池田国保医療年金課長","answer":"都全体に入ってくるお金は３,５２３億円が入ってくる予定になっていまして、あと前期高齢者の交付金として２,３４６億円が入ってまいります。残り、納付金については、都全体では４,３４６億円というふうな形になってあります。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国民健康保険事業の運営に関する協議会の資料そのものを厚生委員会にも示していただけないかなと思うのですけれども、その点、いかがでしょうか。今回８５万円に、３万円値上げになるのですけれども、その人数も教えていただけたらと思います。","respondent":"池田国保医療年金課長","answer":"明後日にご説明するための資料の部分が抜かれているのと、私どもとしては、ご理解いただければと思うところです。それから、およそ２.７３％の世帯が限度額を超している世帯ということでございまして、その世帯の若干という形になるかと思ってあります。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７割減額の場合は、半分の７割減額ということになるので、これぐらいになるのだなというところを一々計算しないと見えにくいではないですか。１人当たりで６,７２４円の値上げになるというのはどういう理由からなのか、その理由について教えていただけたらと思います。","respondent":"池田国保医療年金課長","answer":"こちらの６,７２４円、６,７２４円上がっているということで、計算上は保険料としては１人当たりの額は上がってしまうと。これだけの値上がりになってしまったというふうにご理解いただければと思います。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"だけれども値上げになるということは、それを超えて収入が増えているということで考えていいということなのでしょうか。均等割額は３,３００円の値上げなのに、平均で６,７２４円になるという、その考え方ですが。","respondent":"池田国保医療年金課長","answer":"（国民健康保険に）入っている方の今年の収入が、昨年よりも入っている方が上がっているとご理解いただければと思います。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしましたら、例えば１人当たりの収入ですとか所得とか、その平均が幾らみたいなことというのは出ている部分があるのでしょうか。それは去年と比べて今年が幾らになるのかというのが分かる数字があったら、教えていただけますか尋ねました。","respondent":"池田国保医療年金課長","answer":"特にこちらのほうは、算定した時点でいつの時点かというのが、大変申し訳ないのですけれども、私個人としてはまだ判明していませんけれども、こちらについては調べまして、次回、報告します。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区でも前年度が幾らで今年度が幾らというのが分かったら、この次の機会でも結構ですので、ぜひよろしくお願いしたいと思います。特別区長会などでも要望を出したりとかもしているということですけれども、ぜひ引下げに、そういう方向で取り組んでいただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは産業経済費の審査のところでやるかどうかは別として、それで２年間留保した、今のところ４月から両方返してくれと言っている。そういうところが出てきているということは、どこかで調べてというか、理解をしておいてほしいなということをお伝えだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"意見を述べさせていただきたいのですが、社会保障は改悪の一途です。だからこそ、今こそ住民に一番身近な自治体、品川区があらゆる努力をして、一般財源投入を含めて、軽減に踏み出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3620#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":53812,"voices":191}},{"id":"r04-20220222-8","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"建設委員会","time":"午前１０時００分～午後 ４時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を129件整理しています。","topics":[{"id":"topic-01","title":"(1)占用料の減額措置","agenda":"(1)占用料の減額措置","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この占用している方がどういう方なのか、道路と法定外公共物、公園ということで内訳が分かればお答えほしいと求めました。占用料が上がるということなのですけれども、この関係性をお聞きしたいのですが、固定資産税評価額が上がると占用料が上がる仕組みを伺います。","respondent":"稲田土木管理課長","answer":"今回の固定資産税評価額との関係です。これは３年に一度改定をしていくというものですが、占用料の額は、この道路価格に固定資産税評価額を反映しているというものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"この占用している方が個人か事業者かの内訳ということでお聞きしたのですが、今は分からないということなのですか。このところも改めて答弁があったら伺いたいのと、そういった方にはぜひお知らせをしていただきたいと思うのですが、いかがか尋ねました。","respondent":"稲田土木管理課長","answer":"それともう１つが……。〔「減額措置」と呼ぶ者あり〕 これは毎年、４月当初から１か月の間に納めてもらうということなので、ずっと占用している方には更新手続をやってもらいます。すみません、ちょっと今、探します。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"教えてほしいのですけれども、これを支払っている、３種類ありますけれども、これは全て、どうやったら、全ての方が支払っていただいているのか。管理という意味では、どういう管理をされているのか尋ねました。","respondent":"稲田土木管理課長","answer":"例えば、木が出ているところがあります。ああいうものも土木監察担当で、道路上にはそういうものをなくすようにということで、指導しながらやってきているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"申請して支払っているのですかということと、お店、飲食の店とかで看板を道路側に立ててしまったりとかしている場合がありますね。それは区別がつくようになっているのか尋ねました。","respondent":"稲田土木管理課長","answer":"ただし、表示している画面が２m2以上のものからお金を取るというところになっております。その出幅を計ったりとか、そういうこともうちのほうではやったりしております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"いいのでしょうかというところが、何かそういうものがあると分かりやすいと思うのですけれども、そういうものはあり得ないのか。やっぱり許可していますという何か証明がないと、周りからやっぱり分かりづらいと思うのですけれども、そういう実態はどうなのか尋ねました。","respondent":"稲田土木管理課長","answer":"許可していないものに対して、許可しているというシールとか、そういうものは貼るようにはなっていないです。出しては駄目ですよというような、定期的なそういうキャンペーンというか、パトロール等をやっているところです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"不正を働いているというような場合であれば注意するとか、そういうこともできるし、そういう工夫はできないのですか。これはちゃんとした許可の下、使っているのだなというふうに分かると思うのですけれども、いかがか尋ねました。","respondent":"稲田土木管理課長","answer":"区報の８月号には、そういうものを毎年載せていまして、非常に分かりやすいやり方で区民の皆さんにもアピールしているというところです。ぜひ区の土木監察担当のほうにお知らせいただければ、私どもは常に現場へ行っていますので、やっていきたいと思います。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"１点だけ質問します。もしそういうケースがあれば。","respondent":"稲田土木管理課長","answer":"件数は、なかなか今は出ないのですけれども、例えば、警察とはもう既に、常に情報を共有しています。道路交通が非常に重要になってきますので、交通管理者とは、いろいろな情報をやり取りしながらやっていくということです。","id":"exchange-007"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"そう多くはないのですけれども、その辺りの道路使用、道路占用の考え方について教えていただきたい。","respondent":"稲田土木管理課長","answer":"どのように扱うかは今後だと思いますが、１つ、屋外広告物に影響してくるのではないかというふうに考えております。事例が出てきたら、そのときに精査していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"３年に１回実施されているということで、前回、前々回ぐらいまで分かれば教えてほしいと求めました。","respondent":"稲田土木管理課長","answer":"固定資産税評価額の推移、平成２２年から平成２５年の３年間のところで、一度上がっていたものが下がっているという状況がございました。それからまた、平成２５年から平成２８年、平成３１年、令和４年、それ以降、上がってきているという状況です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"１年間ということになっておりますけれども、ここら辺の１年間ということでの、１年間で更新するからというところでの１年間という考え方ですか。背景みたいなことをもう少し詳しく教えていただきたいのと、期間についての考え方、これを確認させてください。","respondent":"稲田土木管理課長","answer":"何か対応できるものがあるのかというところでございまして、区内の方においては、何とか安くというところでやってきました。期間の考え方なのですけれども、委員おっしゃられたように、１年間の徴収なものですから、１年というところで定めた次第です。","id":"exchange-010"}]},{"id":"topic-02","title":"続きまして、(7)第２８号議案、品川区災害対策基本条例の一部を改正する条例","agenda":"続きまして、(7)第２８号議案、品川区災害対策基本条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"「災害時要援護者」から「避難行動要支援者」に名称を変更するということで、これまでの施策については変更があるのかどうかを伺いたいと思います。そして、避難行動要支援者の支援の中に、避難生活の支援というのは含まれているのかどうか伺います。","respondent":"山本防災課長","answer":"１点目の施策の変更があるかですが、平成２８年度、要配慮者に対する品川区要配慮者支援全体計画を策定しておりまして。生活支援の部分、事業者と連携して様々支援をしていく必要があるところですので、今後検討していきたいと考えています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"後段のほうで、この避難行動要支援者の支援をするところで、そうすると、避難生活というのは含めていきたい、検討していくというお考えの答弁だったのか、そこをもう少し詳しくといいますか、改めて伺いたいと思います。","respondent":"山本防災課長","answer":"生活支援につきましては、その後の生活支援というところも、その辺りの支援方法というところはしっかり考えていきたいというふうに思ってあります。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"この前の状況のときでも、５段階まであったという認識はどこまでされているのでしょうか、区民の人たち。４で「避難指示」になったら避難ですよということではないか尋ねました。","respondent":"山本防災課長","answer":"なかなか区民の方も理解されていない方もいらっしゃるというところで、これまでも区としても様々な機会を捉えながら周知を進めてきたところです。今後の周知の方法というところ、区民の方に分かりやすい方法は、引き続き考えていきたいというふうに思ってあります。","id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"避難をしたときにどうすべきなのかということが、今後いろいろと防災関係については、いろいろな情報を区民の皆さんに出されると思うのです。それだけ覚えてという形でメッセージを絞った形でぜひお願いしたいと、意見を申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"今後どういうふうに、全戸配布されている防災ハンドブックがあるかと思うのですけれども、こちらのほうに対する影響です。不勉強で申し訳ないのですが、防災ハンドブックと地域防災計画を今後どう改定していくかというところについての現状でのお考えを説明を求めました。","respondent":"山本防災課長","answer":"修正、反映は終わっておりまして、新しい用語を使って施策を進めているところです。新旧対照表ではないですけれども、こちらのほうを挟んでお渡ししているというところで対応しているところです。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"結構な人数になる方々をどうやってというのは、非常に難しい部分が、課題が見えているかと思います。現状、どうやってさらに進めていくようなお考えであるのかということを考えていたら、お聞きしたいと思います。","respondent":"山本防災課長","answer":"この部分ではかなりネックになっているというふうに我々も認識しています。検討を進めているところですので、こういった中で連携を図りながら、一人ひとり支援できる体制をつくっていきたいというふうに思ってあります。","id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"賛成です。財産を守る支援の強化や抜本的改正が必要ですけれども、今回の改正は文言整理ということですので、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-03","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そこで事故が起こったというのはどういうことなのか。今後、起こらないように改善していく取組というのはどう考えていらっしゃるのか伺います。","respondent":"山本防災課長","answer":"ちょっと前方の確認が不注意だったというところで、ぶつけてしまった、進んでしまったというところが概要です。今も進めてはいるのですけれども、１人で運転するのではなくて、助手席に必ず同乗者を乗せるような対応を進めているところです。","id":"exchange-018"}]},{"id":"topic-04","title":"の１、議案審査を再び議題に供します。 まず、(1)第２２号議案、品川区住宅修築資金融資あつ旋条例の一部を改正する条例","agenda":"の１、議案審査を再び議題に供します。 まず、(1)第２２号議案、品川区住宅修築資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"件数と融資額、そこを伺いたいと思います。どういう方が申請されているのかというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"過去５年以内には２０代の方のお申込みはなくて、平成２５年でお一人、２０代の方がいらっしゃったです。それから、融資あっ旋額は、令和３年度が２,５４２万円、令和２年度が１,５４５万円、令和元年度が３,２８９万円となっております。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、大体５０歳未満の方はほとんどいないということで、トラブルとか、そういったことは心配ないということでよろしいか尋ねました。","respondent":"竹田住宅課長","answer":"それ以外は５０歳以上の方ですので、人生経験豊富な方ですので、若年による詐欺等の心配は、さほどないのかなです。ただ、ご相談者とは、十分にコミュニケーションをとりながら、適切に事業の運営に努めていきたいと考えております。","id":"exchange-020"}]},{"id":"topic-05","title":"第２３号議案、品川区立従前居住者用住宅条例の一部を改正する条例","agenda":"第２３号議案、品川区立従前居住者用住宅条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"戸数全体としては２５戸あるというところで、この従前居住者用住宅にするのは１６戸ということで、この１６戸にした理由を伺います。この間の入居実績といますか、どういった件数になっているのか、その辺りを伺いたいと思います。","respondent":"森木密整備推進課長","answer":"５世帯の方が仮入居として入っていらっしゃるという形になりまして、ソレイユ戸越については、仮入居者の方は今は入っていらっしゃらないです。大体毎年５戸から１０戸の間ぐらいで、仮入居の方としては入っていただいているです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。実際、そこはまた問題だというふうに思うのですけれども、そこのところはどのように考えていらっしゃるのか伺います。","respondent":"森木密整備推進課長","answer":"そういったものをある程度見込んでも、埋まる予定がないというところであれば、それは区の施設をしっかりと利用するという観点から。そういったものについては、今後、所管と調整をしながらやっていきたいというふうに考えているところです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"詳しくは今後検討ということでしたけれども、空室がいっぱいならないような配慮といいますか、何割まで入れるとか、１戸は絶対に空けておくとか、そういった決まり、そういったものはあるのかどうか伺います。","respondent":"森木密整備推進課長","answer":"先ほど申しました全体の必要戸数を算定して、中延や戸越へ割り振って考えた中でも、一定、２戸から３戸程度の余裕は見ているところではあります。急に、例えば特区の事業を使いたいので入りたいといった方にも対応していきたいというふうには考えるのですけれども、今回。","id":"exchange-023"},{"speaker":"芹澤委員","kind":"質問・要望","question":"数を必要に応じて減らしたりということができるのかどうかを教えていただきたいのと、内容の確認で、３年が上限というようなお考えでよろしいのか説明を求めました。","respondent":"森木密整備推進課長","answer":"ＵＲのほうも、年に２回ほど、区のほうに変更がありますかというような問合せをしていただく予定になっています。申し上げましたように、あくまで従前居住者住宅ですので、３年という限度でやらせていただきたいというふうに考えております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"確認","question":"一応確認なのですけれども、この(2)の仮入居者制度の見直しというのは、従前居住者住宅全体に関わる話ということですね。コンフォール品川西大井だけではないですねという確認と、なぜこういう確認をするかというと、運営者が違うので、所有者が違うので。","respondent":"森木密整備推進課長","answer":"仮入居制度につきましては、３棟全体に関わるものとして捉えていただければと思います。ですので、借地借家法の中にも定期借家の規定はありますので、それに基づいた住宅確保要配慮者への提供という形に考えてあります。","id":"exchange-025"},{"speaker":"塚本委員","kind":"確認","question":"もう１点、確認なのですけれども、住宅セーフティネット法の中で、いわゆる家賃補助が４万円あったと思います。区が所有者の場合とで若干違ったりもするのかもしれないですけれども、この補助の適用は、特に問題ないのかどうかの確認をお願いします。","respondent":"森木密整備推進課長","answer":"ほかの近辺の新築の住宅ですと、それよりも４割、５割ぐらい高いというようなところですので、大分安く設定をさせていただいているところです。","id":"exchange-026"}]},{"id":"topic-06","title":"第２４号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第２４号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回この建築物の制限に関する条例ということで改正が出ましたけれども、今回、この広町地区で計画をされている建築物、高さですとか用途などをご説明ほしいと求めました。","respondent":"多並都市開発課長","answer":"階についても、１１５ｍのほうが地上２６階建て、１２２ｍのほうが地上２３階建ての予定です。Ａ－２地区につきましては、高さが２７ｍで、階数が地上３階建ての予定と聞いているところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"意見","question":"２７ｍ、３階建てということで、商業施設が計画されるという状況になっています。幾らになるのか、概算でも構いませんけれども、お示しほしいと求めました。","respondent":"多並都市開発課長","answer":"現在の状況としましては、事業計画をこれから認可申請をして決定していくという段階であります。委員会の中でもご説明させていただきましたが、認可のご説明をさせていただき、現時点はまだ検討中です。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で地区計画なども進めてきているわけですから、実際のこの金額というのは大体大づかみでは区はつかんでいるわけです。１円単位までは当然決まっていないと思いますので、そこは概算で何億円ということでも構いませんので、ご説明ほしいと求めました。","respondent":"多並都市開発課長","answer":"事業者がこの事業者になりますので、その中で最終的にまとめて、都のほうにその認可を申請していくということになります。事業者が公表していくことになりますので、現時点で公表されていないことですから、公表する内容ではないというお答えをさせていただいたものです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"都市計画決定もしてきたというわけですから、等価交換というのであれば、改めてここは強く要望しておきたいというふうに思います。手続を進めていくということは、おかしいのではないかと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"土地区画整理事業の今後の流れをまずご説明しますと、今申し上げたように、事業計画の認可等で施行認可がある。そういう形の段階で進めていくことになりますので、そういう形であるということで区としても認識しています。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"交換できないということになった場合、この都市計画決定、建築物の制限はどうなってしまうのでしょうか。伺います。","respondent":"多並都市開発課長","answer":"それを実施するのは、民間開発企業が行うということですので、それはあくまでも都市計画の中で最後に実施するのは民間ということになりますから。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"やはりそうした決まらないうちに進めていくというのはおかしいというふうに思いますし、それはＢ地区のほうも言えるのです。全体計画が示される中で、その地区計画が全体としてどうなのかということは検討されていくべきだというふうに思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"Ｂ街区も含めて、それをこの地区内の中のものがそれを確認して、これでよろしいということで同意をしてこうなっていくことになっています。それをより具体的に、今回、条例という形で定めるという内容と理解いただければと思います。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"新庁舎のところはある程度のところが示されておりますけれども、そうした中で、全体のこの建築物も含めての計画は示されていないわけではないですか。そうしたところをちゃんと計画を示さないで進めていくということが、やはり問題があるのではないかというふうに思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"意見","question":"反対です。このビル２棟、ＪＲに利益をもたらす計画を具体化するための条例改正ですので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"実態調査を求めるものもありますので、先ほど休憩中に陳情者の方からも別で審査をしていただきたいということで伺いまして、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"こちらは検討会資料の抜粋となりますが、羽田空港への導入可能なものとして、記載の２つの飛行方式が選定されております。現在、選定した２つの飛行方式について、羽田空港への導入に向け、具体的な安全性の評価など、検討が行われているところです。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"一時停止を求めるということで、豊島区ということで、品川を含めて７つの区議会で提出をされているということで新聞でも報道されております。併せて、羽田新ルート、実施をする目的は、どう示されているのか伺います。","respondent":"鈴木都市計画課長","answer":"これは旅客による収入ということでご説明しますと、８７.９％の減、あるいは９０％の減です。２つ目の新飛行ルートの運用の目的ですが、国は当初の計画を打ち出したところの説明では、海外とのつながりを強化していく。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"当然、他国との移動は制限をされているというところで、こうしたもともと示されていた目的を達成することができないという状況です。必要性がなくなったということですから、区としてもぜひ国にそう求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"国が主体的に進めていくものというところで、その辺の判断につきましても、国がしっかり判断をしていくというところが区の考えです。これを早急に具体的に示すようにというところで国に求めてまいりましたが、区としては、こうした点を強く国に求めていくです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民への被害軽減に向け固定化回避を求めるというのですけれども、そうであるならば、この一時停止、凍結を求めるべきではないかと思いますが、そことの関係性はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした区民からも先ほど４４５件という、その中には、このコロナ禍における羽田新飛行ルートの一時凍結という声も寄せられております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として態度表明をしていくべきだと思いますし、当初の目的は達成できないという状況ですから、区としても言っていただきたいというふうに思います。特に信号機のないところで道路を渡る際、この羽田新ルートを所管課として、視覚障害者の方々に与えている被害は問題だと考えていないのか伺います。","respondent":"鈴木都市計画課長","answer":"先ほどの４４５件の中に、当然、声としてあるというふうなことは区としても認識しています。運用開始後、状況によっては国に求めるなど、今後もそうした声をしっかり国に届けていきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ意見交換の場を求めてほしいと求めましたが、自分たちが危険に、一時凍結をしてほしいということで求められております。ぜひそうした願いを区としても聞き入れて、国に求めていただきたいというふうに思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この視覚障害者の方を含めて、区に寄せられた様々な声につきましては、今後も国のほうにしっかり届けていきたいというふうに考えてあります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"届けていくということで、届けていただきたいとは思いますが、区としても、そこはきちんと求めていただきたいというふうに思います。８０デシベル以上２３回ということで、やはり７０デシベル出ているということが、区民に被害が出ていると考えているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"本格運用開始後、国も、区のほうにもこれまでも寄せられているところです。そうした中で、国は、一定取組を示し、実施しているというような状況です。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"やはり住民には影響があるということですので、そうした実態を把握していくためにも、今回、実態調査の陳情が出されております。ぜひ品川区としても、区民への被害を把握していくために必要だというふうに思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"被害の実態等、やはり必要性があると判断される場合であれば、これはやはり事業主体である国が行うべきというところが区の考えです。やはり区としましては、これまでも寄せられている声をしっかり今後も国に届けていくというところでございす。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"実態調査などは国が行うべきということですけれども、それならば、国に実態調査をしてほしいということで、区としては求めたのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"実際、細かいアンケートを行うべきかどうかも含めて、やはりそれは国の事業であります。国が主体的に考えて判断していくべきというふうに考えてあります。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区も一番影響を受ける自治体の１つというふうに思いますので、品川区としても、港区ができて品川区ができないというのは何かあるのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"区民の方に説明をし、それで、意見をお寄せくださいという形で港区は実施したというふうに聞いてあります。羽田新飛行経路について声をお寄せいただきたいという実施方法ですので、あるいは本格運用開始後も、より丁寧な説明の募集。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"実施を求めた住民の会が、今回求められているのは、子どもからもしっかりと意見を聞けるようにということで求められていますので。５０歳以上の方が７９％ということで、区としてもやっていくべきではないかというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした手法も含めて、検討を行うべき主体は、やはり事業の実施主体である国が行うべきというふうに考えてあります。区としましては、これまでどおり、区に寄せられた声をしっかり国のほうに届けていくです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"だから、それを受けて、品川区としてどうするのですかということなのです。ただ、それは当たり前の世界であって、そうではない、品川区としてどういう態度をもって向き合っていくのですかということなのです。","respondent":"鈴木都市計画課長","answer":"不安解消に向けた丁寧な説明を求めるというところと、そうした取組を強く進めていただきたいというところは、これまでも国のほうに求めてきたです。先ほどからご説明しているとおり、これはやはり国が事業主体として考え、判断していくべきものというふうに考えてあります。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"品川区としてどうするのですか。例えば、今回いろいろなルートの中で、２つ、5)番と9)番というのがありましたけれども、これを見て怖くないか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはりその歩みを止めることなく検討を続けて、固定化回避に向けた検討を進めていただきたいということで、区としては要望したです。国が検討会を立ち上げて検討していますので、ぜひそれを検討し、実施していただきたいというところが区の思いです。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"だったら、なぜ区ははっきり言わないのでしょうか、必要ないでしょうと。なぜそれを突きつけないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今のこの２ルートから少しでも環境、騒音影響、それを継続して検討していただきたいというところが区としての強い思いだです。当初からこの検討会立ち上げの中で、そうした視点で検討してきているというところで、そうした国が今現在示している考え方も含めて。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"それを国のやることだから国がやるべきだと言ったら、では、どこを見ているのですか、区の人たち、区長も含めて、区民を見てくださいということです。本当にこの上空を通らないようになるのですかと聞いたら、何とも返事はなかったです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"本多委員","kind":"質問・要望","question":"質問は１つなのですけれども、もう１０区ですか、過半数の区で上空を飛ぶわけです。羽田に近いわけですから、特に品川も都心の特に上空が一番低くなってくるところですから、国がやってほしいと求めました。","respondent":"鈴木都市計画課長","answer":"今、羽田新ルートに関わる２３区で影響する区というところで、１９区が新ルートによって影響が出ているというような状況です。そうした実施について、実施していくものですので、しっかり国のほうには届けていくです。","id":"exchange-050"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"国のほうに顔を向けているのではなくて、あくまでも区民に対して顔を向けていただきながら、様々な要望、意見を国に届けていただいているのですね。それを確認させてください。","respondent":"鈴木都市計画課長","answer":"１件１件、そうした声をしっかり届けておりますし、国あるいは東京都を絡めた意見交換の場を定期的に設ける。ルート下１９区の中で、そうした中で検討会も立ち上がったですので、国のほうに届けていくです。","id":"exchange-051"},{"speaker":"大沢副委員長","kind":"意見","question":"２３区、国があって、都があって、２３区があるということです。地方自治というものを行いながら、この件については国にしっかりと届けていただいている、そういう認識でいいわけですねとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"その認識で国に届けているところです。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"落下物についてお聞きしたいのですけれども、先日、今月２月１１日に成田空港で落下物がありました。やはり落下物の危険性というのは依然としてなくなっていないというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"重さが６０kgと非常に大きなものが欠落したというところで、区のほうにも説明というか、連絡がございました。この取組による成果も含めて、今後の取組の成果も含めて、区民にしっかり周知、説明いただくように、それは区としても求めていきたいです。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"この羽田新ルートは反対だと態度表明をして、中止を求めるべきだというふうに思いますけれども、いかがでしょうか。ほぼなくなっていると、目的も達成し得ないという状況で必要がなくなっているというものですから、中止を求めてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"当時、夜１１時以降から朝６時まで離着陸は禁止していたにもかかわらず、やはり区としてもしっかりそれに対して申入れをしていかなければいけない。区民の方にもしっかり意識をお聞きして、そうした申入れをしていく上で、区として調査を行ったという経緯です。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"昭和５２年にこうした区としても実態調査を行ったということですから、ぜひ今回も実態調査を行っていただきたいというふうに思いますし、ぜひ実施をしていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問・要望","question":"１件ずつというのは理解しておりますが、様々な国会議員を通じて、固定化回避というような要望をしてまいりました。１００点満点の答えは今のところ出ていませんが、検討会の様子を見るべきだという思いで、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"塚本委員","kind":"意見","question":"令和２年の請願第３号についてですけれども、なぜかといえば、品川区上空の新ルートを回避していこうという方向で議論が進んでいる。そういった経緯から含めて、今回におきましても、この請願については、継続ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"大沢副委員長","kind":"意見","question":"しっかりこれは見守っていく必要があると思いますので、継続。繰り返しますが、継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"のだて委員","kind":"意見","question":"さらには、この新ルート実施の目的である国際便の増便は、コロナの影響で実際には大幅減便となっていますので、新ルートは必要ありません。以上のことから、この羽田新ルートは中止にすべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"その際におっしゃっていたのは、基準も何もないですよね、その基準はいつになったらできるのですかと言ったら、いつになるか分からないという話です。私は撤回を、危険をさらすようなことについては容認できないということでありますので、採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。羽田新ルートを撤回すべきだと考えますし、国に求めていくべきだというふうに思いますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出すということで、採択をお願いしたいと思います。やはりこれも２０１９年ですので、結論を出す、そして採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。令和２年請願第３号と同様ですし、これは本格実施前にやめてほしいというものですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"塚本委員","kind":"意見","question":"継続でお願いいたします。若干まだ水際対策等が今後どうなっていくのかというような動きがあったりとか、また、継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"しっかりと区民の意見を国に伝えていただいて、そこの部分でしっかりと固定化回避検討会で検討を行ってもらうように強く言ってもらいたいと思います。固定化回避検討会がしっかりとした判断ができるように、しっかりと区民の意見を伝えていただきたい、こういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。この羽田新ルートを中止すべきだと言っておりますけれども、従来ルートに戻すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"その上で、品川区としてどういう態度をとるのかということを追求していますので、今までのやっていることは当たり前です。それを認めるにしても、区の姿勢を問うているわけですから、これは採択というふうにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。どこまでの範囲を区の責任でやっていくのかというのは、ちょっと私は違うのかなという思いで、今回は不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"品川区内の地域センター等に置いて、広くそういった意見を届けられるようにと、こういった取組を随分されてきております。そういった中で、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"そこは品川区の地の利は皆さんよく分かっているわけですから、あるいは意見を集約する事業に対して、何が足らないのか。どういうふうにすれば、皆さんに十分に周知できるように国に伝えていただきたい、これが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"のだて委員","kind":"意見","question":"新ルートが実施されてから２年が経とうとしていますけれども、子どもも含め、実態調査することは、区民の被害実態を明らかにすることになります。このアンケートを区民を抽出して実施をしていくということが必要だというふうに思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"どういう方々がいらっしゃって、どういう困り事があって、当然ながら品川区の課題ではないですか。品川区の問題を収集するのは大切なことではないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"意見","question":"やはりこの現状を改善する必要がありますので、採択です。ほかの理由は、令和４年陳情第４号と同様ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたい、採択でお願いします。なので、採択を区議会として決めていただき、前に進めていきたいという思いの意見として採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営についてなのですけれども、先ほどもありましたけれども、令和４年陳情第１６号については、都市計画審議会でどういうふうに判断されたのかということで、そういったところがメインになっておりまして、ほかの請願とは別に審査をしていただきたいというふうに思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"陳情者の方から、意見陳述をしたいということですので、ぜひ審査の前に、陳情者のお気持ちなどを聞いていきたいというふうに思います。それを踏まえてやはり審査をしていくべきだというふうに思いますので、審査の前に意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、区計審のときに、組合の参加確認の状況を伺いました。この計画を進めていく上では、そうした情報もしっかりと示していくべきだというふうに思いますが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"先ほどの最初のご説明でもお話しいたしましたけれども、組合設立と併せて事業計画が出されることになりますけれども、その中で資金計画が出てきます。その中で、その事業計画の中で、資金計画の中で整理されていることですので、現時点でお答えするものはないです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"この第２地区のほうで、議決権を行使したのが３７.７名だということですけれども、区計審のところでの数と同じだということでよろしいでしょうか。金額も含めて伺いたいと思います。","respondent":"多並都市開発課長","answer":"参加者が、加入者が４４.５名ということで、総会のときの組合の方が４４.５名ということで同じということになっていると聞いています。","id":"exchange-078"},{"speaker":"のだて委員","kind":"提案","question":"土地所有者４３名中２８.６名、借地権者１３名中１３名ということで、総会を行った際の参加者数ということでよろしいということですか。そこの確認をさせていただきたいのと、そうしたまだ提案が出されていない、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"もう一度説明いたしますと、組合員数が４４.５名の中、総会に出席された方が３７.７名というふうにお聞きしています。この方が、全員、そのときに賛成されたとさっき説明いたしました。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"すみません、組合参加のところなのですけれども、総会には４４.５名の方が参加したというのは分かりました。そのときに、先ほどご説明あった人数と変わりないのかというところでお聞きしたかったので、そこをご説明いただければというふうに思います。","respondent":"多並都市開発課長","answer":"もう一度ご説明しますけれども、準備組合に参加されている方、全体が４４.５名です。それが全員、このとき出席された方が、この企画提案については賛成された、そういう説明をしたものです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営状況、３分の２の賛同の確認などということで、これをどのように区として把握をしているのか伺いたいと思います。ぜひ示していただきたいというふうに思うのですが、反対意見が３０６名から出ているということで、いかがか尋ねました。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"委員からご質問があったときにも、できる限り区の見解として意見書の見解のところで引用させていただきながら説明させていただいたつもりです。それに対しての見解ということで、１つ１つ説明させていただいたというところで… 冒頭、計画の内容について区のほうから説明させていただいて、ご意見をいただいて進められたです。そうしたところをしっかりご説明をし、最終的な採決といいますか、そうした形で表していただくです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"準備組合の状況をオブザーバーなどで参加してつかんでいるということでした。そうした中で準備組合が事業実施の責任を負える団体だということで判断をしたということなのかどうか、その理由も含めて伺いたいと思います。","respondent":"多並都市開発課長","answer":"準備組合の事業実施の能力ということですけれども、組合設立、事業の遂行能力等を区もしくは東京都が判断していくことになります。その準備組合の皆様が責任を持って行っていくということですので、そこについては区が判断するものではなくて、地域の方が自主的に行うです。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区は、なぜこの都市計画決定を進めていこうというふうに判断をされたのでしょうか。反対意見が区計審の中でも３０６人の方から出されているという状況ですので、区としては、こうした状況をどのように捉えているのか伺います。","respondent":"多並都市開発課長","answer":"繰り返しになりますけれども、都市計画を決定することと、事業の実施をすることは、段階が違うものです。それに基づいて実際の事業を実施していく段階で、また、その事業の実施能力があるかということをそこで判断していくことになります。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"どれだけ住民の方が賛同しているかどうかということは、区としては、そういったことは自分でやって構わないということなのでしょうか。実際、今回、区計審でも３０６名の方から反対意見が出ましたけれども、こうした意見をどのようにして反映をしていくつもりなのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"都市計画の決定の段階は、その地域の方が主体で検討された企画提案という形で受けた内容が、それを決定していくものです。それをまた具体的に事業として実施していく段階については、これ以上申しませんけれども、これからチェックしていくものです。","id":"exchange-084"},{"speaker":"こんの委員長","kind":"質問","question":"ただいまご答弁いただいたように、繰り返しのご答弁というか、質問も繰り返しになっている。質問を、改めての質問でしたらお受けいたしますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした住民の方がよく知らない下で手続を進めていくべきではないというふうに思うのですけれども、いかがでしょうか。こうした再開発には税金も投入していくわけですし、都市計画決定なども区が一緒になってやっていくわけですから、区の責任はどこにあるのか伺います。","respondent":"多並都市開発課長","answer":"その際に、また皆さんでお話し合いいただいてそこを考えていくことになりますので、そこの中で判断していくということだと認識しています。ただ、事業の実施主体につきましては、民間の事業、組合というのは民間ですので、民間の事業なので事業主体としては民間になります。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"請願にもありましたけれども、説明会をやっていくということが必要だと思いますけれども、いかがでしょうか。反対している人の意見も反映していかなければ、今こそ意見をしっかりと反映していくべきだというふうに思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"説明会につきましては、繰り返しになりますけれども、法令で定められていますので、その法令の手順に従って説明会を開かせていただきました。段階的なところという説明をしましたが、方針であったり、その事業の検討をされて。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、この陳情者の方の意見を聞いていきたいというふうに思います。実際の関係のところからお話をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"芹澤委員","kind":"意見","question":"まちの思っていないビジョンに変わってしまうというのが１点と、やり方が、法にのっとっていないというような２点になるかと思います。段階を経て、やることはしっかりとやっていくというようなお話がありましたので、今回は不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問","question":"結論は、不採択でお願いいたします。そういったことが区の上位計画等に照らして妥当なのかどうか、いろいろ伺っておりますけれども、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"不採択でお願いします。みんなにとってよい開発であるような、しっかりと指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"のだて委員","kind":"意見","question":"こうした状況で決定をすべきではないというふうに思います。議論する場へと改善することが必要だと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"西本委員","kind":"意見","question":"この請願の中に１２月１３日の件があって、住民合意ということで、住民主体が基本にあります。そこは、そこは区としてできることはそんなにないとは思いますけれども、速やかにご理解をいただけるようにお願いしたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"芹澤委員","kind":"意見","question":"内容としては、「見切り発車」とかそういう表現もありますけれども、基本的には、情報公開をしてくれというようなお話かと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問・要望","question":"結論は不採択でお願いいたします。都市計画審議会の中で本来議論すべき、この請願で言われているいろいろな情報公開等の要望、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"大沢副委員長","kind":"質問","question":"しっかりと、組合ができるわけですから、皆さんの意見が反映されるような形づくりを、イニシアチブを握って区のほうで指導方をお願いしたいのです。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。具体的な説明を求めているものですので、当然の要望ですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。住民間討議で進められるべきというのは、１００％できているとはもちろん言いませんけれども、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"結論は、不採択でお願いいたします。請願第５号の内容と同じですけれども、区もオブザーバーとして参加しているわけですから、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"のだて委員","kind":"意見","question":"やはりどのように品川区の都市計画審議会で決定されたのか、あまりにも不透明だと、そのまま進めてよいのかということだと思います。しっかりと説明をすべきなので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"教えてくださいということになると、ちょっと違う、提出する場所がちょっと違ったかなというふうな思いがあります。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"審査する上でも陳情者の意見を聞いていくべきだというふうに思いますので、先に意見陳述をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"この環境アセスメントの、環境影響評価がこの計画に反映されてこないということにもつながってくるというふうに思うのですが、いかがでしょうか。こうした環境アセスについて盛り込む必要はないと考えているのか、そこも伺いたいと思います。","respondent":"河内環境課長","answer":"当該アセスメントですが、４段階に分かれて進捗していくものと認識しています。その際に、区長意見や区民の方の意見も取り入れながら進んでいくものというふうに認識しています。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"この中には、関係区市町村からも意見は出されていないということですが、品川区として意見を出しているのかどうかも伺いたいと思います。ＣＯ２の問題ですとか、こうしたことをしっかり反映した計画にしていくということが、こうした手続の進め方でできるのか伺います。","respondent":"鈴木都市計画課長、河内環境課長","answer":"都市計画図書にある都市計画の中身について、その旨答申していいかどうかということを、最終的に各委員が態度を表明していただくという形です。そうした法律の下でしっかり手続が進められていくというところで… 私からは、区長からの意見などにつきましてご説明させていただきたいと思います。それから２回目につきましては、今後、こちらにつきましては公示・縦覧される予定と聞いておりますが。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"先ほどの説明でも４段階あるということで、その３段階目の見解書ということだというふうに思ったのですが、どのような意見を言ったのか伺います。ＣＯ２の関係で、ＣＯ２の排出も増えていくということになっていくと思いますけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"工事中および供用開始後における管理者の出入りなど、工事における安全、それからルールの徹底をお願いしたいという点がされている点です。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"いかがでしょうか。どう住民に影響があるかというところは、やはり住民にも大きな影響があるというふうに思いますので、いかがか尋ねました。","respondent":"河内環境課長","answer":"そのようなルールにのっとりまして、各段階におきまして、私ども区、地域センターなどで公示・縦覧など、必要な手続に従って行っているというふうな状況です。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"超高層ビル、大きなインフラだと影響が出てくるというふうに思いますけれども、区としてはどのように考えていらっしゃるのか伺いたいと思います。人命にも関わってくるということにもなりますので、そうしたところで駅の混雑になってしまうのではないかと思いますが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"実際の開発計画を立案を検討される際には、また保育園の件であれば保育支援課という形で、必ず協議しながら進めているところであります。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"ご説明いただきたいのと、区として、こうした容積率の緩和などの廃止を考えているのか伺いたいと思います。そうした実際の数字なども含めて示していただきたいと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今度は、区として進めたいホテルなどの区が新たに誘導したい施設についての誘導をしていくということで、そういう理解をしております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問","question":"品川区としては、この規制、容積率の緩和などの廃止は考えていらっしゃらないのかというところを伺いたいと思います。人がやっぱり集まるところで、そうした一極集中のまちづくりを変えていく必要があるのではないかというふうに思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長、多並都市開発課長","answer":"検討を今現在進めておりますが、そうした方向性は、改定の中でもしっかり受け継いでいくというところで今考えてあります。身近な公園ですとか、あるいは公共空間の活用ですとか… しっかりその辺は検討して方向性は打ち出していきたいですが、現行の計画、現行のマスタープランは基本的に方向性としては引き継いでいくです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"都市計画審議会なのですけれども、これは建設委員会とはどういう関係性があるのでしょうか。建設委員会とは直接的な関係は、報告義務はあったと思うのですけれども、その関係性を説明を求めました。","respondent":"鈴木都市計画課長","answer":"諮問をし、最後は、区であれば区長が決定をするです。都市計画もまちづくりですので、適宜、建設委員会のほうにも説明会の前に情報を報告するというような形で進めているところです。","id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"なので、ここも、ちょっと審議するのは難しいなというのが正直な話なのです。審議をする際に、そこを踏まえながら検討していかなければいけないかなというふうにちょっと思いましたので、そういう感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"のだて委員","kind":"質問","question":"すみません、１つ聞き忘れまして、環境アセスの意見を聞かずに、この決定時期をどうして決められるのかというところで陳情にも書かれておりますので、そこの決定時期を決めた理由といいますか、都市計画決定を決定する時期を決めた理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当日、今後の予定というところで書かせていただいているところでございまして、予定としてある程度お示しすることで審議をしていただくという形で。資料に記載のとおり、予定としてお示ししています。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問","question":"ぜひこの場で陳述者の意見をお聞きして、さらに理解を深めていきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"芹澤委員","kind":"質問・要望","question":"説明を求めるようなものが主になるかと思いますので、今ご議論をいろいろいただいて、基本的にはご説明いただいたのかと思います。区議会のほうで、この説明を求めるというところに対して、するしないということを求める立場ではないかなと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"塚本委員","kind":"意見","question":"不採択でお願いいたします。この質疑の中で、正にここに書かれている回答についての答弁があったというふうに思いますし、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"大沢副委員長","kind":"意見","question":"そこのところで結論を出すには、ちょっといろいろと課題があると思います。なので、私は、不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"},{"speaker":"のだて委員","kind":"意見","question":"やはりそれはしっかり説明されたもので審議をしていくべきだというふうに思いますので、採択を主張したいと思います。併せて、区が設置した審議会ですので、区としても指導していくということはできると思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどもちょっと質問いたしましたけれども、やっぱり審議会のことは審議会の件で、そこまで立ち入ることは難しいだろうというふうに思いました。回答を求めますということで、十分それで答えたというふうに認識しておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"芹澤委員","kind":"質問","question":"区がどういった情報を持っているのか、区の考えはというような区の見解を伺うものですので、先ほどの議論で十分お話は尽くせたのかと思います。不採決でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"塚本委員","kind":"質問","question":"同様に、ここに書かれている、ある意味、質問と言ったらいいのでしょうか、この質疑の中で区からは回答があったと思いますので。ここで一括して何か結論めいたことを言うということは、ふさわしくないのかと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。説明をしてほしいということは、そうしたことは抑制していくべきだというふうに思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"伺いたいということであったりとか、なぜでしょうというのがあって、解消できたのではないかというふうに思います。まちづくりと人口動向というのは当然関わってくるものですから、いろいろと他部署の方、関係部署と話をして進めているということですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、委員についてご説明がありましたけれども、そうした委員を選定するに当たっての基準などというのはあるのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"先ほどもご説明いたしましたが、冒頭説明をさせていただいて、それぞれの方のご判断です。町会の方であれば、そうした様々な視点の方々が学識経験者として入っていただいて、ご議論いただいて進めるというのが区の考え方です。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問・要望","question":"発言をするかしないかというのは、やはり活発な議論をして、そういった議論を行っていくということがやはり望ましいのかなというふうに私は思います。それぞれの中で、私もぜひ発言をしていただきたいというふうに思いますので、活発な議論をできる審議会にしていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。その中身について、こちらの場でどうこうという話ではないかなと思いますので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"塚本委員","kind":"意見","question":"こちらに名簿が記されておりますけれども、発言があれば、しっかり発言をするというような方々であるというふうには承知をしているつもりです。それをもってして、審議会について何か疑義を挟むということではないのかなと思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-126"},{"speaker":"大沢副委員長","kind":"意見","question":"よって、そこの中で活発な議論、会長、議長の裁量によって、議題によって、その運営が図られるべきだと考えています。表現が適切かどうかは分かりませんけれども、私は、これは不採択にするべきだと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-127"},{"speaker":"のだて委員","kind":"意見","question":"その中でぜひ発言をしていただいて、議論を活発にしていくということは必要だと思いますので、趣旨採択です。その気持ちは分かるということで、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"なぜしないのかということもあります。とてもそれは役を超え過ぎているというふうに思いますので、すべきではないということから、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985406?Template=document&Id=4342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":89486,"voices":404}},{"id":"r04-20220222-9","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"文教委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"治療の性質上、５日で足りるのかという不安があるのですけれど、５日または１０日という日数の根拠は何なのか伺いたいと思います。現状は年次休暇を取得するしかないと思うのですけれど、これを取得されている方というのはどれくらいいらっしゃるのか、分かれば伺いたいと思います。","respondent":"工藤指導課長","answer":"１５日までですと２０２名、で２０日まで取った者は１１１名というところが、私どもで知り得ている令和２年度の実績です。ただ、年休取得に当たりまして、事由については説明する必要がないというものですので、何のために取っているかというのは把握してないところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認させてほしいと求めました。区教委として何か支援すべきところがあれば支援していただきたいと思うのですけれど、そこについてはいかがか尋ねました。","respondent":"工藤指導課長","answer":"１１日から１５日までというのが２０２名で１６％、１６日から２０日とられている方が８.８％という割合です。新しくできたこういった休暇も、きちんと周知を図りながら、啓発も図っていきたいと考えています。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"というのが今のご質問の趣旨だったと思うのですけれど、手続的な高さの話ですけれど、その辺はどのようになっているのですか。伺いたいと思います。","respondent":"工藤指導課長","answer":"取得するときには、例えば細かい内容等には踏み込まなくていいということになってありますので、基本的には出生サポート休暇という項目を選べば、それでいいことにもなってありますから、内容まで、細かく確認しなければいけないということではなく、取得できるものです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"できるだけその辺の申請は、かなりセンシティブな内容なので、とは言いながら、５日以内、もしくは１０日以内と、カテゴリー分けがあるわけですよね。その辺を少し心配しているのですけれど、その辺教えていただけると。","respondent":"工藤指導課長","answer":"医療内容によって１０日まで取得できるもの、副校長、それであっても必要最小限の情報で取得できるものです。そこについては配慮しながら行いたいと思います。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。働く場の環境ということと、制度上、申請の手続についてのハードルというのは、ぜひ排除してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"有給休暇の使い方としては、１日単位の方が半分ぐらいで、それ以外の方でも結構半日単位で取っていらっしゃる方もいると伺っています。特別休暇の場合は、例えば産休はたしか日単位で、時間単位ではなかったと思うのですけれど、この今回の場合はどちらになっていくのか尋ねました。","respondent":"工藤指導課長","answer":"今回のこの出生サポート休暇は時間単位でも取れるものです。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"条例か規則のほうに根拠があるのですか。今後のためにも少し学んでおきたいので、根拠条文が今、出るようでしたら伺えればと思います。","respondent":"工藤指導課長","answer":"本資料の２枚目、３枚目につけてありますが、条例としては、この出生サポート休暇は改めて示すものですので、そのほかは規則で定めるところです。ただ、国家公務員に準じた内容にいたしますので、時間単位で取れるものに、規則のほうで規定してまいります。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"少し基本的なところを確認させていただきたいのですが、最大が２０日を限度に、繰越しもあるというふうになっていますね。通常、権利として持っている１５日から引かれるのではなくて、５日付与されて、それで承認されるという理解がどうか、説明を求めました。","respondent":"工藤指導課長","answer":"お尋ねのように、いわゆる年次有給休暇とは全く別に、特別休暇として出生サポート休暇が５日、最大１０日まで付与されるというものです。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどはこういう休暇が取りやすい環境を求めて質問いたしましたが、その辺の丁寧な配慮も一緒に、お願いできたらと思います。条例については、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"ですから、こういうものをどういう仕様にするかというのは、丁寧な慎重な対応が必要なのではないかと思っています。こういう懸念というのをどのように払拭して、今回人工芝にするという結論を出したのか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"それから、今はもう全体的にソフトスパイクにも対応できておりますので、少年野球や少年サッカーで使えないという状況にはないと考えております。日々、子どもたちがそこで生活して運動する場ということで、ご理解をいただきたいと考えています。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"大きく変わるわけですから、区教委としても、そういったことは直接つかむ必要があるのかなと私は思っています。出された懸念に対しては、きちんと当事者が納得するような説明がされたという認識なのか、その辺をお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"工事が始まるということで、一応説明会等は行っていますし、例えば学校からも、学校だより等で説明を行っているです。最終的に相手がどこまで納得できたかというところまでは、確認できていませんけれど、説明をし、その上で工事は進めさせていただいているです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"今後の校庭整備などに当たっては、なるべく人工芝を整備していくというお考えなのでしょうか。そこら辺についても伺いたいと思います。","respondent":"有馬庶務課長","answer":"利用団体への説明ですけれど、第２グラウンドを主に使っている団体かと思いますけれど、併せてこちらからも説明はしています。それ以外については学校のほうから、保護者および利用団体については説明をお願いしています。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"やはり子どもにとって、先ほど花火大会の話もありましたけれど、地域でその学校に通っている子どもも、とても楽しみにしている行事です。地域の皆さん、子どもの声を聞きながら、整備すべきだと私は思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"その辺の説明というのは、どのようにされているのか、現状を伺いたいと思います。それで、悪いことが後から分かるのよね、というふうに聞いているのですけれど、その辺について、区教委としての見解を伺いたいと思います。","respondent":"有馬庶務課長、小林学校施設担当課長","answer":"デメリットの説明ですけれども、こうなりますよということは説明してありますし、我々が町会長会議に行った時も説明しております。我々のほうも人工芝には、重たい消防車両は一切駄目だという認識がありましたけれども… なかなか難しいものですから、人工芝内では飲食は禁止。普通消防車でしたら縦列で３台程度、あとスケルトン車も、そこのアスファルト舗装部分に駐車して学習するスペースを造っております。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"子どもたちのものなのだから、子どもたちの意見を聞いてほしいと、こういう陳情になって上がってきたのかなと思っているのですけれども。教育委員会のほうからもその辺の意見を聞くべきではないか、直接聞くような機会を持つべきではないかと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"私も子どもの消防の写生会というのですか、あれは確かに、重いからできなくなったのですよね。何というのですか、雨水で流れてしまうという中で、ネットをいろいろ拡充して敷いていただくという話があったのですけれども。","respondent":"小林学校施設担当課長、有馬庶務課長","answer":"さらに、最終桝から下水道に排水するところに、流出防止用の籠を置いて、そこで防ぎ、小まめに処分してもらう。ということで、二重の対策を考えているところです。 側溝の中は週に１回とか、グラウンドの周囲は週２回から毎日とか、その辺は頑張っていただいているという状況があります。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問・要望","question":"人工芝での食事の課題とかもいろいろありますけれど、運動会だと、熱中症対策という部分で、教室を開放してくれたりしていたのです。学校、保護者、教育委員会でやっていただけるように要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"一つ思ったのが、当区の場合も、校区教育協働委員会があるかと思います。そういったことは、これまであまりやられてこなかったのか、お願いします。","respondent":"有馬庶務課長","answer":"そういう要望はどんどん出してもらえればと思っています。どうしても人工芝を選択しなくてはいけない場面も出てくるかもしれませんので、そこは協議をしながら、ということになります。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問・要望","question":"要望があってこういうふうにしましたという、手続の正当性の維持というのは、やはり重要なのかなと。というふうに納得していただきやすいのかなと思いますので、そこは丁寧に進めていただければと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"つる委員","kind":"確認","question":"陳情されている要旨の２つについては、まず前提を確認したいのですけれども。質疑でいろいろ確認がありましたけれど、どういうふうにやっていくか、教育現場というのはあるわけであって。","respondent":"有馬庶務課長","answer":"そのような形で、打合せの中で現場に幾つかの製品を実際に見てもらって、対応しているという形です。いずれにしても、製品はいろいろ比べながら、合ったものを選択していくという状況です。","id":"exchange-020"},{"speaker":"つる委員","kind":"提案","question":"人工芝を張らないでほしいというご意見、提案してこられるところを、これは単価には代えられないと思うのです。そういう製品の提案があるようなところに積極的に声かけをして、高くてもなぜそれが高いのか、いいのかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"松澤委員","kind":"意見","question":"不採択でお願いいたします。皆さんの質疑、答弁の中で、十分にお話を聞いていると判断いたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"本日結論を出すで、不採択であります。これは要望したいところと、保護者の声を聞いてほしいというのは、やってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもですとか保護者、実際に使っている関係者、地域の声を聞いて決定していくというのは当然だと思います。趣旨は大変分かりますので、趣旨採択ということにさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"意見","question":"保護者らの声を聞いてほしいというのは、先生に言ったはずの意見がどうも教育委員会には伝わってないみたい、というようなこともあります。その辺の風通しをよくしていただければいいのですけれども、この訴えについてはぜひ、採択という形で答えたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"子どもの意見を聞いてほしいというところですけれど、逆に我々、そういうことを議会でお伝えしていくというのも一つ役割だと考えています。なので、趣旨採択ではなく、いろいろお伝えさせていただいたという前提で、今回は不採択と考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"採択か不採択かということになれば、子どもをはじめ様々な主体との意見を交わす中で決めるべきなので、採択とまでは言えないという考えです。もし可能であれば、吉田委員に、趣旨採択にしてもらえるとありがたいという、私の考えを述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"確認","question":"少しずつ材質が進んでいるということは確認しておりますし、基本は、やはり人工芝の方向に進まないでほしいということです。その趣旨をということで、今回は趣旨採択ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"名前が紛らわしいので整理して、相談先を明確にするという改正だと認識しております。基本的に事業がこれによって廃止されることはないということの確認と、資料の２の（２）、理由について伺いたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"実施事業について何か縮小するということではなく、これまでどおり継続して実施してまいります。０歳から１歳未満という対象が出てまいりまして、１歳から１歳半というところもしっかりと対応していきたいということから、拡充に臨んだところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"その分かりやすい言い方というのは、通称というのでしょうか、何か必要ではないかと思うのですけれど、その辺についてどのようにお考えか、伺います。今までどう分かりにくかったのが、どのように明確になるのか、区としての見解も伺いたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"子育て支援センターは、事業としては家庭あんしんセンターの中で行っているということは、分かりやすいところにつながるかなと考えています。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"（２）の１２歳から１５歳の変更についてですが、条例上の文言の変更ということでなく、対象年齢が変更できるということなのでしょうか。そこをまず説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"今回こちらの名称を子どもショートステイと明確化を図る中で、規則でしたり要綱といった形の部分で、手当てをしてまいりたいと考えています。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"逆に１２歳、中学校３年生とか、いろいろばらばらなのですね。今回１５歳にして、逆に言うと１８歳までなど、今回１５歳としたというところを説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"そちらにつきましては各区で、事業の実施主体、対象をどのように捉えるかというところで差異が生じているところです。今すぐ手当てする必要性はあまりないものかと考えておりまして、１５歳まで、中学校３年生というところを一つの指標とさせていただいたところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"今回は、こういう可能にするという、できる規定だと思っていますけれど、電磁的方法による対応が可能になるものとは、具体的に何なのか、また、対象となる施設の範囲について、それぞれ伺いたいと思います。","respondent":"若生保育支援課長","answer":"会計帳簿、職員に関する情報、重要事項説明の文書とそれに対する同意等が対象として挙げられると考えます。先ほど少し説明でも申し上げたのですけれども、ダウンロードの同意、そういった手法が具体的に考えられるものです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。実際の電子化の状況について伺いたいのですが、それ以外など様々あると思うのですが、少し現状について説明を求めました。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"委員からご指摘いただきました連絡帳であったり日誌ですが、まず、区立保育園に関しましては、現状でも保育の記録に関しましては、電子連絡帳という形で、もう既に電子化をして運用しています。 退園等のシステムですとか、そういったことも含めまして、ＩＣＴのシステムを入れている事業者が８割以上に及んでおります。これは認可保育所、地域型を含めた数字です。","id":"exchange-034"},{"speaker":"安藤委員","kind":"確認","question":"ある意味導入を強制するとなると、逆に現場の負担感がすごいという話も、認可保育園の方からも聞いているのですけれど。今回はできる規定ということで、これをもって現場に電子化が強制されるものではない、という考えでよろしいか、それだけ確認をさせてください。","respondent":"若生保育支援課長","answer":"委員ご指摘のとおり、電子的方法による対応も可能、できるという規定になってありますので、特に強制する意図はございません。ただ、国等のデジタル化の方針もありますので、そういったことを区としても積極的に進めていくです。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"１つ疑問に思ったのが、これまでは付則の第５条の第２項で、一部の文書については電磁的な方法で可能だったのだと思います。条例上の規定によると、文書も出さないといけないことになっていたという理解で、よろしいのか尋ねました。","respondent":"若生保育支援課長","answer":"重要事項説明以外のもの、あるいは先ほどご説明したような保育日誌とか、保護者に対して説明をしなければいけない資料等も含めまして。重要事項説明に関してのみ同意が必要だということでございましたけれども、保護者への説明文書全てについて、適用されるということになります。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"条例違反だったら悪いかもしれないけれど、逆にもっと早く条例を改正していく流れが必要だったのかなというふうに、改めて思いました。磁気ディスクの扱いについて、記載する必要があるのかいうところ、少しお伺いできればと思います。","respondent":"若生保育支援課長","answer":"そういった手段がまだ使われている地域や自治体等もあるという想定の中で、規定されているものと認識しております。それを品川区として、どうしていくかというところは、また全庁的に検討が必要かと考えています。","id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"そこの部分は、意識を全体的に変えていかないといけないのかなと思いながら、少し質問させていただきました。この件だけではないので、大変失礼しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-02","title":"令和４年請願第２号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"令和４年請願第２号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"４月入園の申込みの０・１・２歳児の実際の申込み状況を伺いましたけれども、５歳児と、不承諾数などを伺いたいと思います。区の当面の認可保育園の増設計画を伺いたいのですが、来年４月の増設についても、今決まっているものがあれば説明を求めました。","respondent":"立木保育課長、若生保育支援課長","answer":"４歳が３９名、５歳が１４名、０歳から５歳までの合計で２,１９１名になっております。それから、不承諾数ですが、３歳が１２３名、４歳が４０名、５歳が１５名、０歳から５歳までの合計で９１３名となっています。 それから、期中開設等は予定してございませんので、年度中に関しても４月の１園のみです。再来年度、令和５年度につきましては、現状の計画では５園、これは認証保育所から認可への移行も含めまして、５園を予定しています。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"お伺いしたいのは、二次で入る方の見込みがもし分かっていれば教えていただきたいのですけれど、この９１３人のうち二次で入れるのか。ということについて伺いたいと思います。","respondent":"立木保育課長","answer":"二次の入園選考の結果発表ですが、３月８日に発表の予定になっております。それから、二次の見込みですけれども、現在、入園選考の最中でございまして、今のところはっきりしたお答えは出せない状態です。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"先日の本会議で他の議員の質問に対して、なぜそうなるのか、ご説明ほしいと求めました。もちろん、増設は必要だと私たちも思っていますけれど、そこら辺についても伺います。","respondent":"若生保育支援課長","answer":"保育需要に対して満たせる見込みであるというような答弁内容だったと認識していますが、需要、保育需要は満たせるというお答えをしたところです。現状の計画上は、当面増えていく見込みですので、それに合わせて増設計画を立てているところです。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"今明らかになった９１３人、何百人という方が不承諾になるという、ここが重要なのではないですか。それに合わせた増設をしないと、先ほど言ったような需要とかニーズに対して満たしているとは言えないと思うのですけれど、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"そういった意味でも、保育ニーズについては満たせる見込みだということを、申し上げているところです。なお、待機児童の取扱いにつきましては、国の基準にのっとり行っているところでございまして、適正に算出しているものと認識しています。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"事業で４園に園庭補助をという話がありましたけれども、４園のうち、伺いたいと思います。その措置はいつ解消するのか、これからもずっと続けるというお考えなのか、伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"積極的に園庭等を整備していただいたところに対して、上限３００万円で、補助をしているという事業です。当然、きちんと基準は満たしておりますので… そういったことで弾力化をしている園がありますが、どの程度の割合なのかというところは、今正確にお答えできません。最大面積としては３００強… ４園中３園が屋上園庭、それ以外の１園については、地上１階部分に整備したものです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"区立、私立それぞれについて、どういうふうな対応をするのですか。これも区立、私立それぞれについて、今の認識をお伺いしたいと思います。","respondent":"若生保育支援課長、初貝保育教育運営担当課長","answer":"処遇改善事業の内容ですけれども、こちらは現在、国からの事業スキームが示されていて、それに対して区のほうで実施の検討を進めているところです。… 私からは、公設民営、幼児保育、定期利用保育に関しまして、お答えさせていただければと思います。保育支援課長からも説明がありましたけれども… 答弁に漏れがございました。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変だとは思いますが、全てのところで漏れなく実施できるように、よろしくお願いしたいと思います。ぜひ、本会議での代表質問でも求めましたが、どうしても努力をしていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"それはきちんと受け止めて、審査というのでしょうか、調査とかに入っていただけると理解してよろしいでしょうか。それを１つ、答えるよう求めました。","respondent":"立木保育課長","answer":"私立であれば保育支援課、公立であれば保育課のほうで確認をした上で、それは正すような形で指導しています。実際にそのようなお話は、今はございません。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"例えば疑問というか、というようなことを申し出る人は誰であっても、受け止めていただけるというふうに理解してよろしいでしょうか。ぜひ、そうであってほしいという趣旨での質問なのですけれど、その辺については、いかがか尋ねました。","respondent":"立木保育課長","answer":"例えば匿名等でも、区にそういったお話があった場合にはきちっと、園のほうにも調査をさせていただいて、確認をする。これはどなたからでも、そういう形でやっているというのは間違いございません。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういう実態があるということについて、単に見た目の感覚でも、ちゃんと受け止めてもらえるということでよろしいでしょうか。その辺についてもぜひ、広く受け止めていただきたいという趣旨なのですが、その辺についてはいかがか尋ねました。","respondent":"立木保育課長","answer":"ケースバイケースだと思いますが、きちっとお話を伺った中で、調査等どのような対処をするかというのは判断するということだと考えています。","id":"exchange-048"},{"speaker":"吉田委員","kind":"提案","question":"それから、３園が屋上園庭ということで、子どもたちにとって良い屋上園庭というものを提案している団体からもご意見をいただいております。保育士の一人ひとりの手元にちゃんと行くような仕組みになっているのか、その辺についても確認させていただきたいのですが、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"区として実施する場合においては、きちんと処遇改善がされているかどうかは、実績報告を求めて確認するというスキームになってあります。事業者から、個々の職員の方に対して、賃金等の手当てをしていただくという形になってあります。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"事業者としては、一人ひとりの手元に行っているかということを確認するのが必要ではないかと思うのですけれど、難しいということでしょうか。その辺どうしても、その辺について確認させていただきたいのですが、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"そういったところを全て書面等に整えていただいて、それを区でもきちんと確認する、ということになってあります。個々の職員に対して、区が一人ひとり確認するというのは難しいかなと考えているところです。","id":"exchange-050"},{"speaker":"吉田委員","kind":"提案","question":"例えば決算の人件費比率が何％以上でないと、ということを心配しておりますので、ぜひその辺についてもお考えがあったら伺いたいと思います。保育課なりと一緒に考えていただきたい、提案もしていっていただきたいのですが、その辺についてのお考えを伺いたいと思いますとの意見を述べました。","respondent":"若生保育支援課長、高梨公園課長","answer":"園庭に関してお答えします。その年度の人件費比率等、そういったところをもって支給を制約するということは、区の立場としてはなかなか難しいのではないかと認識しています。区内の公園、児童遊園等におきましては、周辺の保育園等から多くの園児の方が来て、遊んでいただいているということは、把握しています。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろんお年寄りも使っていただきたいですし、この一人ひとりの子どもが大切にされる品川区は、生活者ネットワークとしても求めたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"松本委員","kind":"意見","question":"請願の２点目で、「現代ビジネス」の２０２１年４月１日の記事で、区立から私立への転園が圧倒的に多いという記述があるのですね。こういった事実はあるのかどうか、お答えくださいとの意見を述べました。","respondent":"立木保育課長","answer":"特に統計等とってはおりませんので、そういったところは把握してございません。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問","question":"ではこれは、区議会議員が答えている形にもなっているので、その人が集計、自分でアンケートをとったりとかいうふうな可能性ぐらいしか、考えられないという理解でよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"松本委員","kind":"質問","question":"分かりました。では少し修正して、集計としては、区立から私立、あるいは私立から区立という形での統計は、とられてないという理解でよろしいか尋ねました。","respondent":"立木保育課長","answer":"特にそこの部分で統計をとっているということございません。","id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"一応確認で、２歳児以上の人数掛ける３.３平米が、その敷地内に園庭を設ける際の基準というふうにあると思うのですけれども。２０１９年の質疑で私が確認した中では、保育施設全体の６３％ぐらいがもう、公園を園庭として活用しているというような質疑の確認が。","respondent":"若生保育支援課長","answer":"屋外遊戯場と言われるものの基準ですが、委員ご指摘のとおり、満２歳以上の園児に対して、３.３平米掛ける２歳児の人数分というところが基準です。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、今、品川区が一生懸命頑張ってやっていただいているところなのかなという理解ではいるのですけれど。幼老複合施設というのですか、そういうふうになっているところはあったか尋ねました。","respondent":"若生保育支援課長","answer":"いわゆる高齢者施設との複合というところでは、今、全て網羅的に把握してはいないのですけれど、幾つかあります。今、その上にこうほうえんが運営する高齢者施設が設置されているという形での運営で、そこで双方の交流が行われたりということがあります。","id":"exchange-057"},{"speaker":"つる委員","kind":"確認","question":"園庭を確保すること、公園もそういうふうに活用できるわけですから、共通に共同で活用することはできるわけですね。そういった意味で少し確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"園庭の代替で公園を使うという話の中で、屋上園庭でふと思ったのですけれど、児童センターの屋上は、遊具といいますか、何件か、富士見台児童センターとかゆたか児童センターとかありますけれど、ああいうところは使えるのか尋ねました。","respondent":"廣田子ども育成課長","answer":"保育園と児童センターの合築型は多々あるのですけれども、屋上もそうですけれども、案内についても日中に関しては小中高生は来ませんので、話し合って使ってもらっているというところは、既に多くのところです。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問","question":"今の松澤委員の質問で思い出したのですけれど、前年度ぐらいから区の施設を、それは屋内ですけれど、使っていいですよというのがありますよね。それを改めて説明を求めました。","respondent":"若生保育支援課長","answer":"そういった施設のスポーツ室など園が利用した場合、その利用料を補助する事業を、令和元年度から実施しています。そういった事業も活用して、今後も公園の混雑の解消とともに、園児が外遊びできる運動場所の確保を図っていきたいと考えております。","id":"exchange-060"},{"speaker":"松澤委員","kind":"意見","question":"区独自で屋上園庭の整備補助、こういうことは果敢に方策の中で力を入れていただいていると、お話の中でありました。そういったことをしっかりと周知していって、子どもたちが遊べる場、そういったものを広げていただければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"つる委員","kind":"意見","question":"結論を出すで、不採択です。先ほど質疑させていただいたことを、品川区にもこれからもしっかりとやっていただくということで、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"認可保育園は増えてきていますけれども、大半は株式会社園なので、園庭がない点ですとか、保育士の待遇改善などが必要だと思います。子どもたちの健やかな育ちの環境整備へ、こちらを採択して、これらの施策を進めるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"民間保育園がどんなに増えても、公立保育園の存在意義が必要だと考えていますので、この項目２つ目についても賛同いたします。現実に園庭がない保育園があるわけですから、これからも進めていただきたいということで、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。より人気が出たという話というのも当然あるわけですので、この点はやはり沿い難いところで、私は不採択と申し上げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今回支払いを求める訴えを起こしたということなのですけれど、支払ってもらった例というのはどれぐらいあるのでしょうか。伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"そういうふうな流れの中で、それでもなかなか、音沙汰がないという形に陥った場合には、こういう形での対応ということで続けて行きたいと思います。ただ、残念ながら回収不能、回収できなかったというものも存在しているのは事実です。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"もともと大変ですから、奨学金を借りているという方だと思うのです。最後に、先ほどの２つ目の質問のところで、大体４０件のうち、こういった手法で回収できたところというのは、何割ぐらいになるのか尋ねました。","respondent":"伊東子育て応援課長","answer":"この間、滞納解消となったのは１５件です。","id":"exchange-067"},{"speaker":"松本委員","kind":"質問","question":"通常は、連帯保証人まで訴えたほうが回収率が上がると思うのですけれど、ここに差が出ているのは、どういった理由でしょうか。お願いします。","respondent":"伊東子育て応援課長","answer":"時期によりまして、連帯保証人を２名つけるという時期があったのと、今は１名という形になってあります。それで、事件一覧の３番に関しましては、連帯保証人が亡くなったということで、連帯保証人に関しては訴えていないという形になってあります。","id":"exchange-068"},{"speaker":"松本委員","kind":"意見","question":"貸付けで延滞した場合は、延滞金がつくようになっているかと思いますけれども、今回の場合はその扱いはどうなっているのか。お願いしますとの意見を述べました。","respondent":"伊東子育て応援課長","answer":"延滞金は、違約金という形で滞納額の１０％がかかるという形になってあります。","id":"exchange-069"},{"speaker":"松本委員","kind":"質問・要望","question":"条例上はそこも規定があるところですから、やるべきことはやっていただきながら、対応してほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問","question":"最低１度は示されていて、これはもしかしたら松本委員に伺ったほうがあれかもしれないですけれど、その時点での時効は停止しますよね。だから、請求し続けることはできるわけではないか尋ねました。","respondent":"伊東子育て応援課長","answer":"それなりの対応をするということにはなるのですけれども、それでも一定期間音沙汰なしという形になって、やむを得ず提起をしたというような状況です。","id":"exchange-071"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それは上がるということでよろしいのでしょうか。伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"対象となりまして、委託先に調査をかけて、申請していただいて対応しようというふうに考えているところです。児童センターにつきましては預かりをやっておりませんので、今回は対象となっておりません。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問","question":"私の認識不足だと思うのですけれど、すまいるスクールは、今まで第三者評価はなかったのでしょうか。お答えいただけますか。","respondent":"廣田子ども育成課長","answer":"今までは、内部の監査とかはしていたのですけれども、やっておりませんで、令和４年度から実施したいということで、新規予算で計上しております。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"では、そういう補助金、制度もできたということで、早速活動しましょうと。そういう趣旨と理解してよろしいか尋ねました。","respondent":"廣田子ども育成課長","answer":"そのとおりです。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"こういう状況は、コロナ禍なのでなお一層、間違われた方にとってはかなり、怒り心頭というか、さらに好ましくないと思うのですけれど。今回なぜそのようなことになったのかという反省と分析がすごく大事だと思うのですけれど、そこについて、なぜ起こったのか尋ねました。","respondent":"伊東子育て応援課長","answer":"入力作業のほうはそのまま、しっかり入っていたのですけれども、受給者変更をするところで漏れてしまったです。２月支給分での調査で判明したということになりますので、支給月の各種調査など、再度業務の進行管理を徹底していくという形で考えております。","id":"exchange-075"},{"speaker":"松本委員","kind":"確認","question":"本来は、タイミングに応じて両方の所得を確認しないといけないのだけれども、そのまま受給対象のほうだけ確認していたと。というふうな流れでよろしいか尋ねました。","respondent":"伊東子育て応援課長","answer":"そのとおりです。","id":"exchange-076"},{"speaker":"松本委員","kind":"確認","question":"その間違いが生じた部分と、なぜ発覚が生じたのか、発覚がなぜできたのかというところは、一応確認しておく必要があるのかなと思います。発覚ができた理由をもう一度お願いできますか尋ねました。","respondent":"伊東子育て応援課長","answer":"２月の支給に際して、今回の２月支給分には大丈夫だったのだけれども、発覚したと。未処理のままスルーしてきたということが発覚したです。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/921668?Template=document&Id=5058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":55215,"voices":243}}]);
